import { NextResponse } from "next/server";
import PocketBase from "pocketbase";

export async function POST(request: Request) {
  try {
    const { classId } = await request.json();

    if (!classId) {
      return NextResponse.json({ error: "Missing classId" }, { status: 400 });
    }

    const pb = new PocketBase(process.env.NEXT_PUBLIC_POCKETBASE_URL);

    // Auth as superuser to bypass rules for updating status
    await pb.admins.authWithPassword(
      process.env.POCKETBASE_ADMIN_EMAIL || "afkerahmad@gmail.com",
      process.env.POCKETBASE_ADMIN_PASSWORD || "Afker1234",
    );

    // Get the class to ensure it exists
    const classRecord = await pb.collection("classes").getOne(classId);

    // Update the status to completed
    if (classRecord.status !== "completed") {
      await pb.collection("classes").update(classId, {
        status: "completed",
      });
    }

    return NextResponse.json({ success: true });
  } catch (error: any) {
    console.error("Error ending class:", error);
    return NextResponse.json(
      { error: error?.message || "Failed to end class" },
      { status: 500 },
    );
  }
}

import { NextResponse } from "next/server";
import PocketBase from "pocketbase";
import fs from "fs";
import path from "path";

export async function POST(request: Request) {
  try {
    const authHeader = request.headers.get("authorization");
    if (!authHeader?.startsWith("Bearer ")) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const token = authHeader.substring(7);
    const tokenParts = token.split(".");
    if (tokenParts.length !== 3) {
      return NextResponse.json({ error: "Invalid token" }, { status: 401 });
    }

    const decoded = JSON.parse(Buffer.from(tokenParts[1], "base64").toString());
    const userRole = decoded.role;

    if (userRole !== "lecturer" && userRole !== "admin") {
      return NextResponse.json({ error: "Forbidden" }, { status: 403 });
    }

    const { classId, username, demote } = await request.json();

    if (!classId || !username) {
      return NextResponse.json(
        { error: "Missing classId or username" },
        { status: 400 },
      );
    }

    const pb = new PocketBase(process.env.NEXT_PUBLIC_POCKETBASE_URL);

    // Auth as superuser to bypass rules
    await pb.admins.authWithPassword(
      process.env.POCKETBASE_ADMIN_EMAIL || "afkerahmad@gmail.com",
      process.env.POCKETBASE_ADMIN_PASSWORD || "Afker1234",
    );

    const classRecord = await pb.collection("classes").getOne(classId);

    if (!classRecord.galene_group) {
      return NextResponse.json(
        { error: "No Galene group found for this class" },
        { status: 404 },
      );
    }

    const groupsDir = path.join(process.cwd(), "services", "galene", "groups");
    const filePath = path.join(groupsDir, `${classRecord.galene_group}.json`);

    if (!fs.existsSync(filePath)) {
      return NextResponse.json(
        { error: "Galene configuration file not found" },
        { status: 404 },
      );
    }

    // Read and parse current configuration
    const config = JSON.parse(fs.readFileSync(filePath, "utf-8"));

    // Extract wildcard password (which students use)
    const attendeePassword = config["wildcard-user"]?.password;

    if (!attendeePassword) {
      return NextResponse.json(
        { error: "Cannot determine attendee password" },
        { status: 500 },
      );
    }

    // Initialize users object if undefined
    if (!config.users) config.users = {};

    // Inject the specific username as an OP with the attendee password.
    if (demote) {
      if (config.users[username]) {
        delete config.users[username];
        fs.writeFileSync(filePath, JSON.stringify(config, null, 2));
      }
    } else {
      config.users[username] = {
        password: attendeePassword,
        permissions: ["op", "present", "message", "record"],
      };
      fs.writeFileSync(filePath, JSON.stringify(config, null, 2));
    }

    return NextResponse.json({ success: true });
  } catch (error: any) {
    console.error("Error promoting user:", error);
    return NextResponse.json(
      { error: error?.message || "Failed to promote user" },
      { status: 500 },
    );
  }
}

import { NextResponse } from "next/server";
import PocketBase from "pocketbase";
import fs from "fs";
import path from "path";

export async function POST(request: Request) {
  try {
    const authHeader = request.headers.get("authorization");
    if (!authHeader?.startsWith("Bearer ")) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const token = authHeader.substring(7);
    const tokenParts = token.split(".");
    if (tokenParts.length !== 3) {
      return NextResponse.json({ error: "Invalid token" }, { status: 401 });
    }

    const decoded = JSON.parse(Buffer.from(tokenParts[1], "base64").toString());
    const userRole = decoded.role;

    if (userRole !== "lecturer" && userRole !== "admin") {
      return NextResponse.json({ error: "Forbidden" }, { status: 403 });
    }

    const { classId } = await request.json();

    if (!classId) {
      return NextResponse.json({ error: "Missing classId" }, { status: 400 });
    }

    const pb = new PocketBase(process.env.NEXT_PUBLIC_POCKETBASE_URL);

    // Auth as superuser to bypass rules for updating status
    await pb.admins.authWithPassword(
      process.env.POCKETBASE_ADMIN_EMAIL || "afkerahmad@gmail.com",
      process.env.POCKETBASE_ADMIN_PASSWORD || "Afker1234",
    );

    // Get the class to ensure it exists
    const classRecord = await pb.collection("classes").getOne(classId);

    // Update the status to in_progress
    if (classRecord.status !== "in_progress") {
      await pb.collection("classes").update(classId, {
        status: "in_progress",
      });
    }

    // Backward compatibility: ensure admin user exists in Galene config for older classes
    if (classRecord.galene_group) {
      const groupsDir = path.join(
        process.cwd(),
        "services",
        "galene",
        "groups",
      );
      const filePath = path.join(groupsDir, `${classRecord.galene_group}.json`);
      if (fs.existsSync(filePath)) {
        try {
          const config = JSON.parse(fs.readFileSync(filePath, "utf-8"));
          if (config.users?.lecturer && !config.users?.admin) {
            config.users.admin = { ...config.users.lecturer };
            fs.writeFileSync(filePath, JSON.stringify(config, null, 2));
            console.log(
              `[Classroom] Patched admin user into ${classRecord.galene_group}`,
            );
          }
        } catch (e) {
          console.error("Failed to patch galene group config:", e);
        }
      }
    }

    return NextResponse.json({ success: true });
  } catch (error: any) {
    console.error("Error starting class:", error);
    return NextResponse.json(
      { error: error?.message || "Failed to start class" },
      { status: 500 },
    );
  }
}

import { NextResponse } from "next/server";
import PocketBase from "pocketbase";
import fs from "fs";
import path from "path";

export async function GET(request: Request) {
  try {
    const { searchParams } = new URL(request.url);
    const secret = searchParams.get("secret");

    if (process.env.CRON_SECRET && secret !== process.env.CRON_SECRET) {
      return NextResponse.json(
        { error: "Unauthorized: Invalid secret" },
        { status: 401 },
      );
    }

    const pb = new PocketBase(process.env.NEXT_PUBLIC_POCKETBASE_URL);

    await pb.admins.authWithPassword(
      process.env.POCKETBASE_ADMIN_EMAIL || "afkerahmad@gmail.com",
      process.env.POCKETBASE_ADMIN_PASSWORD || "Afker1234",
    );

    // Fetch all completed classes
    const records = await pb.collection("classes").getFullList({
      filter: `status = "completed"`,
    });

    let deletedCount = 0;
    const groupsDir = path.join(process.cwd(), "services", "galene", "groups");

    for (const record of records) {
      if (record.galene_group) {
        const filePath = path.join(groupsDir, `${record.galene_group}.json`);

        if (fs.existsSync(filePath)) {
          fs.unlinkSync(filePath);
          deletedCount++;
        }
      }
    }

    // Clean up uploaded chat documents
    let chatFilesDeleted = 0;
    const chatUploadsDir = path.join(
      process.cwd(),
      "public",
      "uploads",
      "chat",
    );

    if (fs.existsSync(chatUploadsDir)) {
      const chatFiles = fs.readdirSync(chatUploadsDir);
      for (const file of chatFiles) {
        const filePath = path.join(chatUploadsDir, file);
        if (fs.statSync(filePath).isFile()) {
          fs.unlinkSync(filePath);
          chatFilesDeleted++;
        }
      }
    }

    return NextResponse.json({
      success: true,
      message: `Nightly cleanup finished. Deleted ${deletedCount} Galene groups and ${chatFilesDeleted} chat uploads.`,
    });
  } catch (error: any) {
    console.error("Cron Cleanup Error:", error);
    return NextResponse.json(
      { error: "Failed to run scheduled cleanup", details: error.message },
      { status: 500 },
    );
  }
}

import { NextResponse } from "next/server";
import fs from "fs";
import path from "path";

// Function to generate the Galene JSON configuration
const generateGroupConfig = (
  passwordHost: string,
  passwordAttendee: string,
  durationMin: number,
) => {
  return {
    users: {
      lecturer: {
        password: passwordHost,
        permissions: ["op", "present", "message", "record"],
      },
      admin: {
        password: passwordHost,
        permissions: ["op", "present", "message", "record"],
      },
    },
    "wildcard-user": {
      password: passwordAttendee,
      permissions: ["present", "message"],
    },
    autolock: false,
    "max-history-age": durationMin * 60 + 3600, // Duration plus 1 hour buffer
  };
};

export async function POST(request: Request) {
  try {
    const body = await request.json();
    const { classId, passwordHost, passwordAttendee, duration } = body;

    if (!classId || !passwordHost || !passwordAttendee || !duration) {
      return NextResponse.json(
        {
          error:
            "classId, passwordHost, passwordAttendee, and duration are required",
        },
        { status: 400 },
      );
    }

    // Define the path to the Galene groups directory
    // Galene docker-compose mounts ./services/galene/groups to /var/lib/galene/groups
    const groupsDir = path.join(process.cwd(), "services", "galene", "groups");
    const filePath = path.join(groupsDir, `${classId}.json`);

    // Create the directory if it doesn't exist
    if (!fs.existsSync(groupsDir)) {
      fs.mkdirSync(groupsDir, { recursive: true });
    }

    // Generate and write the config file
    const config = generateGroupConfig(
      passwordHost,
      passwordAttendee,
      duration,
    );
    fs.writeFileSync(filePath, JSON.stringify(config, null, 2));

    return NextResponse.json({
      success: true,
      message: `Galene group ${classId} created successfully.`,
      path: filePath,
    });
  } catch (error: any) {
    console.error("Failed to create Galene group:", error);
    return NextResponse.json(
      { error: "Failed to create Galene group", details: error.message },
      { status: 500 },
    );
  }
}

export async function DELETE(request: Request) {
  try {
    const { searchParams } = new URL(request.url);
    const classId = searchParams.get("classId");

    if (!classId) {
      return NextResponse.json(
        { error: "classId is required" },
