            minute: "2-digit",
          }),
          status: "pending",
          courseName: course?.name,
          subjectName: subject?.name,
          link: `/dashboard/admin/assignments/${a.id}`,
        };
      });

      setCalendarEvents([...classEvents, ...assignmentEvents]);
