    email: "",
    address: "",
    city: "",
    gender: "",
    dateOfBirth: "",
    IdentificationDocument: "",
    guardianName: "",
    guardianRelationship: "",
    guardianContact: "",
    whatsapp: "",
  });

  useEffect(() => {
    if (!isOpen) return;
    setFormData({
      name: student.name || "",
