              <Menu size={24} />
            </button>
            <h1 className="text-xl font-black text-gray-900 tracking-tighter uppercase">
              Academix
            </h1>
            <div className="w-12 h-12 bg-indigo-600 rounded-2xl flex items-center justify-center text-white shadow-lg shadow-indigo-100">
              <LayoutIcon size={20} />
            </div>
          </div>

          {children}
        </main>
      </div>
    </div>
  );
}

