"use client";

import React, { useState, useEffect, useRef } from "react";
import { useRouter } from "next/navigation";
import {
  ShieldX,
  Menu,
  Layout,
  TrendingUp,
  Clock,
  GraduationCap,
  BookOpen,
  FileEdit,
  Video,
  CalendarIcon,
  Lock,
} from "lucide-react";
import { motion } from "framer-motion";
import pb from "@/lib/pocketbase";
import Sidebar from "@/components/lecturer/Sidebar";
import UpcomingClasses, {
  type UpcomingClass,
} from "@/components/lecturer/UpcomingClasses";
import AllSchedulesModal from "@/components/lecturer/AllSchedulesModal";
import IntakesTree, {
  type Intake,
  type Course,
  type Subject,
} from "@/components/lecturer/IntakesTree";
import StatsCarousel from "@/components/admin/StatsCarousel";

// Mock user type
interface MockUser {
  id: string;
  name: string;
  role: "lecturer" | "student" | "admin";
  accountStatus: "active" | "disabled";
}

// Mock data
const mockUser: MockUser = {
  id: "lect-001",
  name: "Dr. Sarah Johnson",
  role: "lecturer",
  accountStatus: "active",
};

const mockIntakes: Intake[] = [
  {
    id: "intake-1",
    code: "INT-2024-01",
    name: "January 2024 Intake",
    startDate: "2024-01-15",
    endDate: "2024-06-30",
    courses: [
      {
        id: "course-1",
        name: "Computer Science Fundamentals",
        code: "CS101",
        subjects: [
          {
            id: "subject-1",
            name: "Programming Basics",
            code: "CS101-A",
            assigned: true,
          },
          {
            id: "subject-2",
            name: "Data Structures",
            code: "CS101-B",
            assigned: true,
          },
          {
            id: "subject-3",
            name: "Algorithms",
            code: "CS101-C",
            assigned: false,
          },
        ],
      },
      {
        id: "course-2",
        name: "Web Development",
        code: "WEB201",
        subjects: [
          {
            id: "subject-4",
            name: "Frontend Development",
            code: "WEB201-A",
            assigned: true,
          },
          {
            id: "subject-5",
            name: "Backend Development",
            code: "WEB201-B",
            assigned: false,
          },
        ],
      },
    ],
  },
  {
    id: "intake-2",
    code: "INT-2024-02",
    name: "March 2024 Intake",
    startDate: "2024-03-01",
    endDate: "2024-08-31",
    courses: [
      {
        id: "course-3",
        name: "Mathematics",
        code: "MATH101",
        subjects: [
          {
            id: "subject-6",
            name: "Calculus I",
            code: "MATH101-A",
            assigned: true,
          },
        ],
      },
    ],
  },
];

// Data fetching for real classes
const fetchUpcomingClasses = async (
  lecturerId: string,
): Promise<UpcomingClass[]> => {
  try {
    const res = await fetch(`/api/lecturer/classes?lecturerId=${lecturerId}`);
    if (!res.ok) {
      throw new Error(`Failed to fetch: ${res.statusText}`);
    }
    const data = await res.json();
    const records = data.records || [];

    const today = new Date().toISOString().slice(0, 10);

    const mappedRecords = records
      .filter((record: any) => {
        if (record.status === "completed") {
          const recordDate = new Date(record.start_time)
            .toISOString()
            .slice(0, 10);
          return recordDate === today;
        }
        return true;
      })
      .map((record: any) => {
        const csExpand = record.expand?.course_subject;
        const subjectsArr = Array.isArray(csExpand)
          ? csExpand
          : [csExpand].filter(Boolean);
        const isMerged = subjectsArr.length > 1;

        return {
          id: record.id,
          intakeName:
            subjectsArr.length > 0
              ? Array.from(
                  new Set(
                    subjectsArr.map(
                      (cs: any) =>
                        cs.expand?.course_intake?.expand?.intake?.code,
                    ),
                  ),
                )
                  .filter(Boolean)
                  .join(", ") || "N/A"
              : "N/A",
          courseName:
            subjectsArr.length > 0
              ? Array.from(
                  new Set(
                    subjectsArr.map(
                      (cs: any) =>
                        cs.expand?.course_intake?.expand?.course?.name,
                    ),
                  ),
                )
                  .filter(Boolean)
                  .join(" & ") || "N/A"
              : "N/A",
          subjectName:
            subjectsArr.length > 0
              ? Array.from(
                  new Set(
                    subjectsArr.map(
                      (cs: any) =>
                        cs.expand?.subject?.[0]?.name ||
                        cs.expand?.subject?.name,
                    ),
                  ),
                )
                  .filter(Boolean)
                  .join(" & ") || "N/A"
              : "N/A",
          classTitle: record.title,
          startTime: new Date(record.start_time).toLocaleString("en-US", {
            month: "short",
            day: "numeric",
            hour: "2-digit",
            minute: "2-digit",
          }),
          rawStartTime: record.start_time,
          duration: record.duration,
          status: record.status as any,
          lecturerName: record.expand?.lecturer?.name || "Lecturer",
          isMerged,
        };
      });

    const now = Date.now();
    const activeUpcoming: UpcomingClass[] = [];
    const ended: UpcomingClass[] = [];

    mappedRecords.forEach((item: any) => {
      const scheduledEnd =
        new Date(item.rawStartTime).getTime() + item.duration * 60000;
      if (now >= scheduledEnd) {
        ended.push(item);
      } else {
        activeUpcoming.push(item);
      }
    });

    return [...activeUpcoming, ...ended];
  } catch (error) {
    console.error("Error fetching classes:", error);
    return [];
  }
};

function DateTimeStatCard() {
  const [now, setNow] = useState<Date | null>(null);

  useEffect(() => {
    setNow(new Date());
    const timer = setInterval(() => setNow(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  if (!now) return null;

  const time = now.toLocaleTimeString("en-US", {
    hour12: false,
    hour: "2-digit",
    minute: "2-digit",
  });
  const date = now.toLocaleDateString("en-GB", {
    weekday: "short",
    day: "numeric",
    month: "short",
  });

  return (
    <div className="bg-white rounded-[1.8rem] shadow-sm border border-gray-100 px-6 py-3 flex items-center gap-4 hover:shadow-md transition-all group">
      <div className="w-10 h-10 bg-indigo-50 rounded-xl flex items-center justify-center text-indigo-600 group-hover:bg-indigo-600 group-hover:text-white transition-all">
        <Clock size={18} />
