  const [password, setPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const [loginError, setLoginError] = useState("");

  useEffect(() => {
    if (!pb.authStore.isValid) return;

    const role = (pb.authStore.model as any)?.role;
    switch (role) {
      case "admin":
        router.replace("/dashboard/admin");
        break;
      case "student":
        router.replace("/dashboard/student");
        break;
      case "lecturer":
        router.replace("/dashboard/lecturer");
        break;
      default:
        router.replace("/dashboard");
    }
  }, [router]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setLoginError("");

    try {
      // Authenticate with PocketBase using userId

      const authData = await pb
        .collection("users")
        .authWithPassword(userId, password);

      // Check if account is disabled
      if (authData.record.accountStatus === "disabled") {
        pb.authStore.clear();
        setLoginError(
          "Your account has been disabled. Please contact the administrator.",
        );
        toast.error("Your account has been disabled.");
        return;
      }

      // Get user role
      const role = authData.record.role;

      toast.success("Login successful!");

      // Redirect based on role
      switch (role) {
        case "admin":
          router.push("/dashboard/admin");
          break;
        case "student":
          router.push("/dashboard/student");
          break;
        case "lecturer":
          router.push("/dashboard/lecturer");
          break;
        default:
          router.push("/dashboard");
      }
    } catch (error: any) {
      // Generic but clear error for authentication failures
      const isAuthError = error?.status === 400 || error?.status === 404;
      const errorMsg = isAuthError 
        ? "Invalid User ID or password. Please check your credentials."
        : (error?.data?.message || error?.message || "An unexpected error occurred. Please try again.");

      setLoginError(errorMsg);
      toast.error(errorMsg);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex min-h-screen items-center justify-center bg-gray-50">
      <main className="flex flex-col items-center gap-0 bg-white rounded-[2.5rem] shadow-2xl shadow-gray-200/60 max-w-4xl w-full overflow-hidden md:flex-row border border-gray-100">
        {/* Left: Illustration */}
        <div className="flex flex-col items-center justify-center w-full md:w-1/2 bg-indigo-600 p-12 gap-6 min-h-[300px] md:min-h-[560px]">
          <div className="flex flex-col items-center gap-2 mb-2">
            <h2 className="text-3xl font-black tracking-tighter text-white flex items-center gap-1.5">
              ACADE<span className="text-indigo-200">MIX</span>
              <span className="w-2 h-2 rounded-full bg-white animate-pulse" />
            </h2>
            <div className="flex items-center gap-1">
              <div className="h-0.5 w-8 bg-white/40 rounded-full" />
              <div className="h-0.5 w-2 bg-white/20 rounded-full" />
            </div>
          </div>
          <motion.div
            animate={{ y: [0, -16, 0] }}
            transition={{ duration: 3, repeat: Infinity, ease: "easeInOut" }}
            className="w-full flex justify-center"
          >
            <LoginIllustration />
          </motion.div>
          <p className="text-indigo-200 text-[11px] font-black uppercase tracking-widest text-center">
            Your Academic Management Platform
          </p>
        </div>

        {/* Right: Form */}
        <div className="flex flex-col w-full md:w-1/2 p-10 md:p-14 gap-6">
          <div>
            <h1 className="text-3xl font-black text-gray-900 tracking-tight mb-2">
              Welcome <span className="text-indigo-600">Back</span>
            </h1>
            <p className="text-[11px] font-black text-gray-400 uppercase tracking-widest">
              Sign in to access your dashboard
            </p>
          </div>

          <form onSubmit={handleSubmit} className="flex flex-col gap-4 w-full">
            <div className="flex flex-col gap-1.5">
              <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">
                User ID
              </label>
              <input
                type="text"
                placeholder="Enter your User ID"
                value={userId}
                onChange={(e) => setUserId(e.target.value)}
                className="w-full px-5 py-4 rounded-2xl border border-gray-100 bg-gray-50 text-gray-900 text-sm font-medium focus:outline-none focus:border-indigo-300 focus:ring-4 focus:ring-indigo-50 transition-all placeholder:text-gray-300"
                required
                disabled={loading}
              />
            </div>
            <div className="flex flex-col gap-1.5">
              <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">
                Password
              </label>
              <input
                type="password"
                placeholder="••••••••"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full px-5 py-4 rounded-2xl border border-gray-100 bg-gray-50 text-gray-900 text-sm font-medium focus:outline-none focus:border-indigo-300 focus:ring-4 focus:ring-indigo-50 transition-all placeholder:text-gray-300"
                required
                disabled={loading}
              />
            </div>
            <button
              type="submit"
              disabled={loading}
              className="w-full bg-indigo-600 hover:bg-indigo-700 text-white px-6 py-4 rounded-2xl font-black text-xs tracking-widest uppercase shadow-xl shadow-indigo-100 hover:shadow-lg transition-all mt-2 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
            >
              {loading ? (
                <>
                  <div className="h-4 w-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                  Signing In...
                </>
              ) : (
                "Sign In"
              )}
            </button>
            {loginError && (
              <p className="text-xs text-red-500 font-bold text-center mt-2">
                {loginError}
              </p>
            )}
          </form>

          <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest text-center">
            Contact your administrator if you&apos;re having trouble accessing
            your account.
          </p>
        </div>
      </main>
    </div>
  );
}

"use client";

import { useEffect } from "react";
import { useRouter } from "next/navigation";
import pb from "@/lib/pocketbase";

export default function Home() {
  const router = useRouter();

  useEffect(() => {
    // Always redirect to login if no valid session
    if (!pb.authStore.isValid) {
      router.push("/login");
    } else {
      // If user is logged in, redirect to their dashboard based on role
      const role = (pb.authStore.model as any)?.role;
      if (role === "admin") {
        router.push("/dashboard/admin");
      } else if (role === "lecturer") {
        router.push("/dashboard/lecturer");
      } else if (role === "student") {
        router.push("/dashboard/student");
      } else {
        router.push("/login");
      }
    }
  }, [router]);

  return null;
}

"use client";

import React, { useState, useEffect } from "react";

import { ModernModal } from "@/components/ui/modern-modal";
import {
  X,
  CheckCircle,
  Clock,
  Calendar as CalendarIcon,
  Info,
} from "lucide-react";

// Event data structure (empty - to be loaded from database)
const mockEvents: any[] = [];

// Helper to get days in month
function getDaysInMonth(year: number, month: number) {
  return new Date(year, month + 1, 0).getDate();
}

// Helper to get start day of week for month (0=Sun, 1=Mon...)
function getStartDay(year: number, month: number) {
  return new Date(year, month, 1).getDay();
}

export { mockEvents };

// Helper to get week days
const weekDays = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

// Event badge color
const typeBadge: Record<string, string> = {
  "Online Class": "bg-blue-100 text-blue-700 border-blue-200",
  "Physical Class": "bg-yellow-100 text-yellow-700 border-yellow-200",
  Holiday: "bg-purple-100 text-purple-700 border-purple-200",
  Assignment: "bg-green-100 text-green-700 border-green-200",
};

// EventItem component
function EventItem({ event }: { event: (typeof mockEvents)[0] }) {
  return (
    <div
      className={`flex items-center gap-2 mt-1 px-1 py-0.5 rounded text-xs bg-gray-50 border ${typeBadge[event.type] || "border-gray-200"}`}
    >
      <span
        className={`px-2 py-0.5 rounded-full text-xs font-semibold ${typeBadge[event.type] || "bg-gray-100 text-gray-700 border-gray-200"}`}
      >
        {event.type}
      </span>
      <span className="font-medium truncate">{event.subjectName || event.title}</span>
      {/* Show topic for Zoom class */}
      {event.type === "Online Class" && event.topic && (
        <span className="ml-2 text-blue-500 font-medium truncate">
          {event.topic}
        </span>
      )}
      {event.startTime && (
        <span className="ml-auto text-gray-400">
          {event.startTime}
          {event.endTime ? ` - ${event.endTime}` : ""}
        </span>
      )}
    </div>
  );
}

// DayCell component
function DayCell({
  day,
  date,
  events,
  isToday,
  isSelected,
  onClick,
}: {
  day: number;
  date: string;
  events: typeof mockEvents;
  isToday: boolean;
  isSelected: boolean;
  onClick: () => void;
}) {
  return (
    <button
      className={`w-full h-24 p-1 rounded-lg border flex flex-col items-start text-left relative transition border-gray-300
        ${isToday ? "bg-indigo-100 border-indigo-400" : "hover:bg-gray-50"}
        ${isSelected ? "ring-2 ring-indigo-400" : ""}
        min-w-0 max-w-full overflow-hidden`}
      style={{ minWidth: 0 }}
      onClick={onClick}
    >
      <span
        className={`text-lg font-bold ${isToday ? "text-indigo-600" : "text-gray-700"}`}
      >
        {day}
      </span>
      <div className="flex-1 w-full overflow-y-auto">
        {events.slice(0, 3).map((event) => (
          <EventItem key={event.id} event={event} />
        ))}
        {events.length > 3 && (
          <span className="text-xs text-gray-400">
            +{events.length - 3} more
          </span>
        )}
      </div>
      {events.length > 0 && (
        <span className="absolute top-1 right-1 w-2 h-2 bg-indigo-400 rounded-full"></span>
      )}
    </button>
  );
}

// Main Calendar component
export interface CalendarEvent {
  id: string;
  title: string;
  topic?: string;
  type: "Online Class" | "Physical Class" | "Holiday" | "Assignment" | string;
  date: string; // YYYY-MM-DD
  startTime?: string;
  endTime?: string;
  status?: string;
  courseName?: string;
  subjectName?: string;
  link?: string;
  rawStartTime?: string;
  duration?: number;
}

interface CalendarProps {
  onModalOpenChange?: (open: boolean) => void;
  events?: CalendarEvent[];
}

const Calendar: React.FC<CalendarProps> = ({ onModalOpenChange, events = [] }) => {
  // Render day view (must be inside Calendar to access state)
  function renderDay() {
    const d = new Date(current.year, current.month, current.day);
    const dateStr = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
    const dayEvents = getEventsForDate(dateStr);
    return (
      <div className="grid grid-cols-1 gap-2">
        <DayCell
          key={dateStr}
          day={d.getDate()}
          date={dateStr}
          events={dayEvents}
          isToday={dateStr === todayStr}
          isSelected={selected === dateStr}
          onClick={() => {
            setSelected(dateStr);
            setModalDate(dateStr);
            if (onModalOpenChange) onModalOpenChange(true);
          }}
        />
      </div>
    );
  }
  // State for view, date, and selected day
  const [view, setView] = useState<"month" | "week" | "day">("month");
  const [current, setCurrent] = useState(() => {
    const now = new Date();
    return {
      year: now.getFullYear(),
      month: now.getMonth(),
      day: now.getDate(),
    };
  });
  const [selected, setSelected] = useState<string | null>(null);
  const [modalDate, setModalDate] = useState<string | null>(null);

  // Prevent background scrolling when modal is open
  useEffect(() => {
    if (modalDate) {
      document.body.style.overflow = "hidden";
    } else {
      document.body.style.overflow = "unset";
    }
    return () => {
      document.body.style.overflow = "unset";
    };
  }, [modalDate]);

  // Get today string for highlight
  const todayStr = new Date().toISOString().slice(0, 10);

  // Get events for a date
  const getEventsForDate = (date: string) =>
    events.filter((e) => e.date === date);

  // Navigation handlers
  function prev() {
    if (view === "month") {
      setCurrent((c) => {
        const m = c.month === 0 ? 11 : c.month - 1;
        const y = c.month === 0 ? c.year - 1 : c.year;
        return { ...c, year: y, month: m };
      });
    } else if (view === "week" || view === "day") {
      setCurrent((c) => {
        const d = new Date(c.year, c.month, c.day - (view === "week" ? 7 : 1));
        return { year: d.getFullYear(), month: d.getMonth(), day: d.getDate() };
      });
    }
  }
  function next() {
    if (view === "month") {
      setCurrent((c) => {
        const m = c.month === 11 ? 0 : c.month + 1;
        const y = c.month === 11 ? c.year + 1 : c.year;
        return { ...c, year: y, month: m };
      });
    } else if (view === "week" || view === "day") {
      setCurrent((c) => {
        const d = new Date(c.year, c.month, c.day + (view === "week" ? 7 : 1));
        return { year: d.getFullYear(), month: d.getMonth(), day: d.getDate() };
      });
    }
  }

  // Modal for expanded day events
  const closeModal = () => {
    setModalDate(null);
    if (onModalOpenChange) onModalOpenChange(false);
  };

  // Render month view
  function renderMonth() {
    const days = getDaysInMonth(current.year, current.month);
    const start = getStartDay(current.year, current.month);
    const cells = [];
    for (let i = 0; i < start; i++) cells.push(<div key={"empty-" + i}></div>);
    for (let d = 1; d <= days; d++) {
      const dateStr = `${current.year}-${String(current.month + 1).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
      const events = getEventsForDate(dateStr);
      cells.push(
        <DayCell
          key={dateStr}
          day={d}
          date={dateStr}
          events={events}
          isToday={dateStr === todayStr}
          isSelected={selected === dateStr}
          onClick={() => {
            setSelected(dateStr);
            setModalDate(dateStr);
            if (onModalOpenChange) onModalOpenChange(true);
          }}
        />,
      );
    }
    return (
      <div className="grid grid-cols-7 gap-2 w-full max-w-full overflow-x-hidden">
        {weekDays.map((w) => (
          <div
            key={w}
            className="text-xs font-bold text-gray-400 text-center mb-1 min-w-0"
          >
            {w}
          </div>
        ))}
        {cells}
      </div>
    );
  }

  // Render week view
  function renderWeek() {
    const refDate = new Date(current.year, current.month, current.day);
    const weekStart = new Date(refDate);
    weekStart.setDate(refDate.getDate() - weekStart.getDay());
    const days = [];
    for (let i = 0; i < 7; i++) {
      const d = new Date(weekStart);
      d.setDate(weekStart.getDate() + i);
      const dateStr = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
      const events = getEventsForDate(dateStr);
      days.push(
        <DayCell
          key={dateStr}
          day={d.getDate()}
          date={dateStr}
          events={events}
          isToday={dateStr === todayStr}
          isSelected={selected === dateStr}
          onClick={() => {
            setSelected(dateStr);
            setModalDate(dateStr);
            if (onModalOpenChange) onModalOpenChange(true);
          }}
        />,
      );
    }
    return (
      <div className="grid grid-cols-7 gap-2">
        {weekDays.map((w) => (
          <div
            key={w}
            className="text-xs font-bold text-gray-400 text-center mb-1"
          >
            {w}
          </div>
        ))}
        {days}
      </div>
    );
  }

  return (
    <div
      id="calendar-root"
      className="w-full h-full bg-white rounded-2xl p-4 flex flex-col max-w-full overflow-x-hidden"
      style={{ boxSizing: "border-box" }}
    >
      {/* Header: Navigation & View Switch */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2 mb-4">
        <div className="flex items-center gap-2">
          <button
            onClick={prev}
            className="p-2 rounded hover:bg-gray-100 text-gray-500"
          >
            <span className="sr-only">Previous</span>
            <svg width="20" height="20" fill="none" viewBox="0 0 20 20">
              <path
                d="M12 15l-5-5 5-5"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          </button>
          <div className="text-lg font-semibold text-gray-700">
            {view === "month" &&
              `${new Date(current.year, current.month).toLocaleString("default", { month: "long" })} ${current.year}`}
            {view === "week" &&
              `Week of ${new Date(current.year, current.month, current.day).toLocaleDateString()}`}
            {view === "day" &&
              `${new Date(current.year, current.month, current.day).toLocaleDateString()}`}
          </div>
          <button
            onClick={next}
            className="p-2 rounded hover:bg-gray-100 text-gray-500"
          >
            <span className="sr-only">Next</span>
            <svg width="20" height="20" fill="none" viewBox="0 0 20 20">
              <path
                d="M8 5l5 5-5 5"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          </button>
        </div>
        <div className="flex gap-2">
          <button
            onClick={() => setView("day")}
            className={`px-3 py-1 rounded-lg text-sm font-medium ${view === "day" ? "bg-indigo-600 text-white" : "bg-gray-100 text-gray-700"}`}
          >
            Day
          </button>
          <button
            onClick={() => setView("week")}
            className={`px-3 py-1 rounded-lg text-sm font-medium ${view === "week" ? "bg-indigo-600 text-white" : "bg-gray-100 text-gray-700"}`}
          >
            Week
          </button>
          <button
            onClick={() => setView("month")}
            className={`px-3 py-1 rounded-lg text-sm font-medium ${view === "month" ? "bg-indigo-600 text-white" : "bg-gray-100 text-gray-700"}`}
          >
            Month
          </button>
        </div>
      </div>
      {/* Calendar Body */}
      <div className="flex-1 w-full max-w-full overflow-x-hidden">
        {view === "month" && renderMonth()}
        {view === "week" && renderWeek()}
        {view === "day" && renderDay()}
      </div>

      {/* ModernModal for expanded day events */}
      <ModernModal
        open={!!modalDate}
        onOpenChange={(open) => {
          if (!open) closeModal();
        }}
        title={
          modalDate
            ? (() => {
                const d = new Date(modalDate);
                return `${weekDays[d.getDay()]}, ${d.toLocaleDateString()}`;
              })()
            : ""
        }
        subtitle={
          modalDate
            ? `${getEventsForDate(modalDate).length} event(s)`
            : undefined
        }
        avatarChar={modalDate ? `${new Date(modalDate).getDate()}` : undefined}
        avatarColor="bg-indigo-600"
        className="max-w-2xl"
      >
        <div className="overflow-y-auto no-scrollbar py-2 space-y-4">
          {getEventsForDate(modalDate || "").map((event) => (
            <div
              key={event.id}
              className={`bg-white border rounded-[2.5rem] p-8 flex flex-col gap-6 shadow-sm hover:shadow-2xl hover:shadow-indigo-100/50 transition-all duration-300 w-full group relative overflow-hidden ${
                event.type === "Online Class"
                  ? "border-blue-100"
                  : event.type === "Physical Class"
                    ? "border-yellow-100"
                    : event.type === "Assignment"
                      ? "border-green-100"
                      : event.type === "Holiday"
                        ? "border-purple-100"
                        : "border-gray-100"
              }`}
            >
              <div className="flex flex-col sm:flex-row sm:items-start justify-between gap-6 relative z-10">
                <div className="flex-1">
                  <h4 className="font-black text-gray-900 text-xl tracking-tight group-hover:text-indigo-600 transition-colors uppercase leading-tight">
                    {event.subjectName || event.title}
                  </h4>
                  <div className="flex items-center gap-3 mt-3">
                    <span
                      className={`text-[10px] px-3 py-1 rounded-xl font-black uppercase tracking-widest ${
                        event.type === "Online Class"
                          ? "bg-blue-50 text-blue-700"
                          : event.type === "Physical Class"
                            ? "bg-yellow-50 text-yellow-700"
                            : event.type === "Assignment"
                              ? "bg-green-50 text-green-700"
                              : event.type === "Holiday"
                                ? "bg-purple-50 text-purple-700"
                                : "bg-gray-50 text-gray-700"
                      }`}
                    >
                      {event.type}
                    </span>
                    {event.topic && event.type !== "Assignment" && (
                      <div className="flex items-center gap-2 text-[10px] font-black text-blue-600 bg-blue-50/50 w-fit px-3 py-1 rounded-xl uppercase tracking-widest">
                        <Info size={12} /> {event.topic}
                      </div>
                    )}
                  </div>
                  {event.courseName && (
                    <div className="mt-2 text-[10px] font-bold text-gray-500 uppercase tracking-widest">
                       <span>{event.courseName}</span>
                    </div>
                  )}
                </div>

                <div className="shrink-0 flex gap-3">
                  {event.type === "Online Class" ? (
                    (() => {
                      const now = Date.now();
                      const scheduledEnd = event.rawStartTime 
                        ? new Date(event.rawStartTime).getTime() + (event.duration || 60) * 60000 
                        : 0;
                      const hasEnded = event.status === "completed" || (scheduledEnd > 0 && now >= scheduledEnd);

                      if (hasEnded) {
                        return (
                          <span className="px-6 py-3 rounded-2xl bg-gray-100 text-gray-400 text-xs font-black uppercase tracking-[0.1em]">
                            Class Ended
                          </span>
                        );
                      }

                      return (
                        <button 
                          onClick={() => {
                            window.location.href = `/dashboard/classroom/${event.id}?role=attendee`;
                          }}
                          className={`px-6 py-3 rounded-2xl text-white text-xs font-black uppercase tracking-[0.1em] shadow-xl transition-all ${
                            event.status === "ongoing" || event.status === "in_progress"
                              ? "bg-green-600 shadow-green-100 hover:bg-green-700"
                              : "bg-blue-600 shadow-blue-100 hover:bg-blue-700"
                          } hover:scale-105 active:scale-95`}
                        >
                          {event.status === "ongoing" || event.status === "in_progress" ? "Join Live" : "Join Session"}
                        </button>
                      );
                    })()
                  ) : event.type === "Assignment" ? (
                    <button 
                      onClick={() => event.link && (window.location.href = event.link)}
                      className="px-6 py-3 rounded-2xl bg-green-600 text-white text-xs font-black uppercase tracking-[0.1em] shadow-xl shadow-green-100 hover:bg-green-700 hover:scale-105 active:scale-95 transition-all"
                    >
                      View
                    </button>
                  ) : event.link ? (
                    <button 
                      onClick={() => window.location.href = event.link!}
                      className="px-6 py-3 rounded-2xl bg-indigo-600 text-white text-xs font-black uppercase tracking-[0.1em] shadow-xl shadow-indigo-100 hover:bg-indigo-700 hover:scale-105 active:scale-95 transition-all"
                    >
                      View
                    </button>
                  ) : null}
                </div>
              </div>

              <div className="flex items-center gap-6 text-[10px] font-black uppercase tracking-[0.15em] text-gray-400 relative z-10 pt-4 border-t border-gray-50">
                <span className="flex items-center gap-2">
                  <CalendarIcon size={14} className="text-gray-300" />{" "}
                  {event.date}
                </span>
                {event.startTime && (
                  <span className="flex items-center gap-2">
                    <Clock size={14} className="text-gray-300" />{" "}
                    {event.startTime} - {event.endTime}
                  </span>
                )}
              </div>
            </div>
          ))}
          {modalDate && getEventsForDate(modalDate).length === 0 && (
            <div className="text-gray-400">No events for this day.</div>
          )}
        </div>
      </ModernModal>
    </div>
  );
};

