// Badge color mapping (referenced from Calendar.tsx)
const typeBadge: Record<string, string> = {
  "Online Zoom Class": "bg-blue-100 text-blue-700 border-blue-200",
  "Physical Class": "bg-yellow-100 text-yellow-700 border-yellow-200",
  Holiday: "bg-purple-100 text-purple-700 border-purple-200",
  Assignment: "bg-green-100 text-green-700 border-green-200",
};

interface EventType {
  id: number;
  title: string;
  topic?: string;
  type: string;
  date: string;
  startTime?: string;
  endTime?: string;
  platform?: string;
}

function getUpcomingSchedules(events: EventType[]): EventType[] {
  const today = new Date().toISOString().slice(0, 10);
  // Only future or today events
  return events
    .filter((e: EventType) => e.date >= today)
    .sort((a: EventType, b: EventType) => {
      // Today first, then by date ascending
      if (a.date === today && b.date !== today) return -1;
      if (b.date === today && a.date !== today) return 1;
      return a.date.localeCompare(b.date);
    });
}

export default function Section5Schedules() {
  const router = useRouter();
  const [modalOpen, setModalOpen] = useState(false);
  const [loading, setLoading] = useState(true);
  const [upcoming, setUpcoming] = useState<any[]>([]);
  const today = new Date().toISOString().slice(0, 10);

  useEffect(() => {
    fetchSchedules();

    // Real-time subscription: re-fetch when any class changes
    pb.collection("classes").subscribe("*", () => {
      fetchSchedules();
    });

    return () => {
      pb.collection("classes").unsubscribe("*");
    };
  }, []);

  const fetchSchedules = async () => {
    try {
      setLoading(true);
      const user = pb.authStore.model;
      if (!user) return;

      // 1. Fetch enrollments
      const token = pb.authStore.token;
      const resp = await fetch("/api/student/enrollments", {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (!resp.ok) throw new Error("Failed to fetch enrollments");
      const { enrollments } = await resp.json();

      const intakeIds = enrollments.map((e: any) => e.course_intake);
      if (intakeIds.length === 0) {
        setUpcoming([]);
        setLoading(false);
        return;
      }

      // 2. Fetch the actual course_subject IDs that match these intakes
      const csFilter = intakeIds
        .map((id: string) => `course_intake = "${id}"`)
        .join(" || ");

      const matchingCourseSubjects = await pb
        .collection("course_subjects")
        .getFullList({
          filter: csFilter,
          fields: "id,course_intake",
        });

      const csIds = matchingCourseSubjects.map((cs) => cs.id);

      if (csIds.length === 0) {
        setUpcoming([]);
        setLoading(false);
        return;
      }

      // 3. Fetch classes that contain any of these course_subject IDs
      const todayStart = new Date();
      todayStart.setHours(0, 0, 0, 0);
      const todayISO = todayStart.toISOString();

      const classFilter = csIds
        .map((id: string) => `course_subject ~ "${id}"`)
        .join(" || ");

      const classes = await pb.collection("classes").getFullList({
        filter: `(${classFilter}) && status != "cancelled" && (status != "completed" || start_time >= "${todayISO}")`,
        expand:
          "course_subject.subject,course_subject.course_intake.course,course_subject.course_intake.intake,lecturer",
        sort: "start_time",
      });

      const formatted = classes.map((c: any) => {
        const subjectsArr = Array.isArray(c.expand?.course_subject)
          ? c.expand.course_subject
          : [c.expand?.course_subject].filter(Boolean);

        // Find all matching subject records for this student's enrollment
        const mySubjectRecords = subjectsArr.filter((cs: any) => {
          const csIntakeId =
            typeof cs.course_intake === "string"
              ? cs.course_intake
              : cs.course_intake?.id;
          return intakeIds.includes(csIntakeId);
        });

        // Use the first match as primary, but collect all unique names if multiple
        const mySubjectName = Array.from(
          new Set(
            mySubjectRecords
              .map(
                (cs: any) =>
                  cs.expand?.subject?.[0]?.name || cs.expand?.subject?.name,
              )
              .filter(Boolean),
          ),
        ).join(" & ");

        const myCourseName = Array.from(
          new Set(
            mySubjectRecords
              .map((cs: any) => cs.expand?.course_intake?.expand?.course?.name)
              .filter(Boolean),
          ),
        ).join(" & ");

        const myIntakeCode = Array.from(
          new Set(
            mySubjectRecords
              .map((cs: any) => cs.expand?.course_intake?.expand?.intake?.code)
              .filter(Boolean),
          ),
        ).join(", ");

        return {
          id: c.id,
          title: mySubjectName, // User requested to show only their subject, not merged title
          type: "Class",
          date: new Date(c.start_time).toISOString().slice(0, 10),
          startTime: new Date(c.start_time).toLocaleTimeString([], {
            hour: "2-digit",
            minute: "2-digit",
          }),
          endTime: new Date(
            new Date(c.start_time).getTime() + c.duration * 60000,
          ).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }),
          course: myCourseName || "Course",
          intakeCode: myIntakeCode || "N/A",
          lecturer: c.expand?.lecturer?.name || "Lecturer",
          status: c.status,
          rawStartTime: c.start_time,
          duration: c.duration,
        };
      });

      const now = Date.now();
      const activeUpcoming: any[] = [];
      const ended: any[] = [];

      formatted.forEach((item: any) => {
        const scheduledEnd =
          new Date(item.rawStartTime).getTime() + item.duration * 60000;
        if (now >= scheduledEnd) {
          ended.push(item);
        } else {
          activeUpcoming.push(item);
        }
      });

      setUpcoming([...activeUpcoming, ...ended]);
    } catch (err) {
      console.error("Error fetching schedules:", err);
      toast.error("Failed to load schedules");
    } finally {
      setLoading(false);
    }
  };

  // Prevent background scrolling when modal is open
  useEffect(() => {
    if (modalOpen) {
      document.body.style.overflow = "hidden";
    } else {
      document.body.style.overflow = "unset";
    }
    return () => {
      document.body.style.overflow = "unset";
    };
  }, [modalOpen]);

  if (loading) {
    return (
      <div className="flex items-center justify-center py-10">
        <div className="h-6 w-6 border-2 border-indigo-600 border-t-transparent rounded-full animate-spin" />
      </div>
    );
  }

  const activeClasses = upcoming.filter((item: any) => {
    const scheduledEnd =
      new Date(item.rawStartTime).getTime() + (item.duration || 60) * 60000;
    return Date.now() < scheduledEnd;
  });

  return (
    <div className="w-full h-full flex flex-col bg-transparent">
      <div className="flex-1 overflow-y-auto mb-6 pr-2 -mr-2 no-scrollbar">
        {activeClasses.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-10 opacity-40">
            <Clock className="text-gray-300 mb-2" size={32} />
            <p className="text-[10px] font-black uppercase tracking-widest text-gray-400">
              No upcoming classes
            </p>
          </div>
        ) : (
          <div className="flex flex-col gap-4">
            {activeClasses.map((ev: any, idx: number) => {
              const themeClass = "border-indigo-100 bg-indigo-50/20";
              const isToday = ev.date === today;
              const scheduledEnd =
                new Date(ev.rawStartTime).getTime() +
                (ev.duration || 60) * 60000;
              const isWithinTimeWindow = Date.now() < scheduledEnd;
              const isReallyEnded =
                ev.status === "completed" && !isWithinTimeWindow;

              return (
                <motion.div
                  key={ev.id}
                  initial={{ opacity: 0, x: 20 }}
