"use client";

import React, { useState, useEffect } from "react";
import { Clock, Timer, Calendar as CalendarIcon } from "lucide-react";
import { UpcomingClass } from "./UpcomingClasses";
import { ModernModal } from "@/components/ui/modern-modal";

interface AllSchedulesModalProps {
  isOpen: boolean;
  onClose: () => void;
  classes: UpcomingClass[];
}

export default function AllSchedulesModal({
  isOpen,
  onClose,
  classes,
}: AllSchedulesModalProps) {
  const [selectedDay, setSelectedDay] = useState<string>("");

  const dayOptions = React.useMemo(() => {
    const days = new Map<string, string>();
    classes.forEach((classItem) => {
      const date = new Date(classItem.startTime);
      if (Number.isNaN(date.getTime())) return;
      const dayKey = date.toISOString().slice(0, 10); // YYYY-MM-DD
      const label = date.toLocaleDateString("en-US", {
        weekday: "short",
        month: "short",
        day: "numeric",
        year: "numeric",
      });
      if (!days.has(dayKey)) days.set(dayKey, label);
    });
    return Array.from(days.entries()).map(([value, label]) => ({
      value,
      label,
    }));
  }, [classes]);

  const filteredClasses = React.useMemo(() => {
    if (!selectedDay) return [];
    return classes.filter((classItem) => {
      const date = new Date(classItem.startTime);
      if (Number.isNaN(date.getTime())) return false;
      const dayKey = date.toISOString().slice(0, 10);
      return dayKey === selectedDay;
    });
  }, [classes, selectedDay]);

  // When the modal opens, default to today if available, otherwise first available day
  useEffect(() => {
    if (!isOpen || classes.length === 0) return;
    const todayKey = new Date().toISOString().slice(0, 10);
    if (dayOptions.find((d) => d.value === todayKey)) {
      setSelectedDay(todayKey);
      return;
    }
    if (dayOptions.length > 0) setSelectedDay(dayOptions[0].value);
  }, [isOpen, classes, dayOptions]);

  const getStatusColor = (status: string) => {
    switch (status) {
      case "scheduled":
        return "bg-blue-100 text-blue-700 border-blue-200";
      case "ongoing":
        return "bg-green-100 text-green-700 border-green-200";
      case "completed":
        return "bg-gray-100 text-gray-700 border-gray-200";
      default:
        return "bg-gray-100 text-gray-700 border-gray-200";
    }
  };

  const getWeekdayLabel = (startTime: string) => {
    const date = new Date(startTime);
    if (Number.isNaN(date.getTime())) return "";
    return date.toLocaleDateString("en-US", { weekday: "short" });
  };

  const handleQuickJoin = (url: string) => {
    window.open(url, "_blank", "noopener,noreferrer");
  };

  return (
    <ModernModal
      open={isOpen}
      onOpenChange={(open) => !open && onClose()}
      title="All Scheduled Classes"
      subtitle={
        selectedDay
          ? `Showing: ${dayOptions.find((d) => d.value === selectedDay)?.label ?? selectedDay}`
          : "View upcoming schedules"
      }
    >
      <div className="space-y-4">
        {/* Day Selector */}
        {dayOptions.length > 0 && (
          <div className="flex items-center gap-2 mb-4">
            <CalendarIcon size={16} className="text-gray-400" />
            <select
              value={selectedDay}
              onChange={(event) => setSelectedDay(event.target.value)}
              className="border border-gray-200 rounded-lg text-sm px-3 py-1.5 bg-gray-50 shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500/20 font-medium"
            >
              {dayOptions.map((option) => (
                <option key={option.value} value={option.value}>
                  {option.label}
                </option>
              ))}
            </select>
          </div>
        )}

        {/* Content */}
        <div className="overflow-y-auto max-h-[60vh] -mx-1 px-1">
          {filteredClasses.length === 0 ? (
            <div className="text-center py-12 text-gray-500 bg-gray-50 rounded-2xl border-2 border-dashed border-gray-100">
              <p className="font-medium">No scheduled classes found</p>
            </div>
          ) : (
            <div className="space-y-3">
              {filteredClasses.map((classItem) => (
                <div
                  key={classItem.id}
                  className="bg-white border border-gray-100 rounded-2xl p-4 shadow-sm hover:shadow-md hover:border-blue-100 transition-all group"
                >
                  <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-3">
                    <div className="flex-1">
                      <div className="flex items-center gap-2 mb-2">
                        <span
                          className={`text-[10px] px-2 py-0.5 rounded-full border font-bold tracking-wider ${getStatusColor(classItem.status)}`}
                        >
                          {classItem.status.toUpperCase()}
                        </span>
                      </div>
                      <h3 className="font-bold text-gray-900 group-hover:text-blue-600 transition-colors">
                        {classItem.classTitle}
                      </h3>
                      <p className="text-sm text-gray-600 mt-1">
                        <span className="font-semibold text-gray-400 uppercase text-[10px] tracking-widest text-indigo-100">
                          Intake
                        </span>{" "}
                        {classItem.intakeName} &nbsp;•&nbsp;
                        <span className="font-semibold text-gray-400 uppercase text-[10px] tracking-widest text-indigo-100">
                          Course
                        </span>{" "}
                        {classItem.courseName}
                      </p>
                      <div className="text-sm text-gray-500 mt-3 flex flex-wrap items-center gap-4">
                        <span className="flex items-center gap-1.5 bg-gray-50 px-2 py-1 rounded-lg border border-gray-100">
                          <Clock size={14} className="text-blue-500" />
                          <span className="font-bold text-gray-700">
                            {getWeekdayLabel(classItem.startTime)}
                          </span>
                          <span className="text-gray-400">
                            {new Date(classItem.startTime).toLocaleString()}
                          </span>
                        </span>
                        <span className="flex items-center gap-1.5 bg-gray-50 px-2 py-1 rounded-lg border border-gray-100">
                          <Timer size={14} className="text-amber-500" />
                          <span className="font-bold text-gray-700">
                            {classItem.duration} min
                          </span>
                        </span>
                      </div>
                    </div>
                    <div className="flex gap-2">
                      {classItem.zoomJoinUrl ? (
                        <button
                          onClick={() => handleQuickJoin(classItem.zoomJoinUrl)}
                          className="w-full md:w-auto px-6 py-2.5 text-sm bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 transition shadow-lg shadow-blue-100 active:scale-95"
                        >
                          Quick Join
                        </button>
                      ) : null}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </ModernModal>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import {
  Calendar,
  BookOpen,
  CreditCard,
  Building2,
  DollarSign,
  Check,
} from "lucide-react";
import { ModernModal } from "@/components/ui/modern-modal";
import pb, { isSuperuserOnlyError } from "@/lib/pocketbase";
import { toast } from "sonner";
import {
  calculateEnrollmentFees,
  EnrollmentFeeCalculation,
} from "@/lib/feeCalculator";
import {
  generateRegistrationNumber,
  rollbackRegistrationNumber,
  generateInstallmentId,
  generatePaymentReferenceId,
} from "@/lib/registrationNumberGenerator";

interface EnrollCourseModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSuccess: () => void;
  studentId: string;
}

interface Intake {
  id: string;
  code: string;
  name: string;
}

interface CourseIntakeFee {
  id: string;
  course_intake: string;
  course_fee: number;
  registration_fee: number;
  duration: number;
  expand?: {
    course_intake: {
      expand?: {
        course: { id: string; name: string; code: string };
      };
    };
  };
}

export function EnrollCourseModal({
  isOpen,
  onClose,
  onSuccess,
  studentId,
}: EnrollCourseModalProps) {
  const [loading, setLoading] = useState(false);
  const [fetchingData, setFetchingData] = useState(false);

  // Data arrays
  const [intakes, setIntakes] = useState<Intake[]>([]);
  const [courseIntakes, setCourseIntakes] = useState<CourseIntakeFee[]>([]);

  // Selected State
  const [selectedIntakeId, setSelectedIntakeId] = useState("");
  const [selectedCourseIntakeId, setSelectedCourseIntakeId] = useState("");
  const [paymentOption, setPaymentOption] = useState<
    "full_payment" | "installments_only" | "upfront_installments"
  >("full_payment");

  // Payment configuration
  const [includeRegistrationFee, setIncludeRegistrationFee] = useState(true);
  const [discountType, setDiscountType] = useState<
    "percentage" | "flat" | null
  >(null);
  const [discountValue, setDiscountValue] = useState(0);
  const [customUpfrontAmount, setCustomUpfrontAmount] = useState(0);
  const [feeCalculation, setFeeCalculation] =
    useState<EnrollmentFeeCalculation | null>(null);

  // Fetch intakes on open
  useEffect(() => {
    if (isOpen) {
      fetchIntakes();
      setSelectedIntakeId("");
      setSelectedCourseIntakeId("");
      setPaymentOption("full_payment");
      setIncludeRegistrationFee(true);
      setDiscountType(null);
      setDiscountValue(0);
      setCustomUpfrontAmount(0);
      setFeeCalculation(null);
    }
  }, [isOpen]);

  // Fetch specific courses when intake changes
  useEffect(() => {
    if (selectedIntakeId) {
      fetchCoursesForIntake(selectedIntakeId);
    } else {
      setCourseIntakes([]);
    }
  }, [selectedIntakeId]);

  // Recalculate fees when payment options change
  useEffect(() => {
    if (selectedCourseIntakeId) {
      const selectedCourse = courseIntakes.find(
        (c) => c.id === selectedCourseIntakeId,
      );
      if (
        selectedCourse?.course_fee !== undefined &&
        selectedCourse?.duration !== undefined
      ) {
        const calc = calculateEnrollmentFees(
          selectedCourse.course_fee,
          selectedCourse.registration_fee || 0,
          selectedCourse.duration,
          paymentOption,
          includeRegistrationFee,
          discountType,
          discountValue,
          customUpfrontAmount,
        );
        setFeeCalculation(calc);
      }
    } else {
      setFeeCalculation(null);
    }
  }, [
    selectedCourseIntakeId,
    paymentOption,
    includeRegistrationFee,
    discountType,
    discountValue,
    customUpfrontAmount,
    courseIntakes,
  ]);

  const fetchIntakes = async () => {
    try {
      const records = await pb.collection("intakes").getFullList<Intake>({
        sort: "-created",
      });
      setIntakes(records);
    } catch (error) {
      if (!isSuperuserOnlyError(error)) {
        console.error("Error fetching intakes:", error);
      }
      toast.error("Failed to load intakes");
    }
  };

  const fetchCoursesForIntake = async (intakeId: string) => {
    setFetchingData(true);
    try {
      const records = await pb
        .collection("course_intake_fees")
        .getFullList<CourseIntakeFee>({
          filter: `course_intake.intake = "${intakeId}"`,
          expand: "course_intake.course",
        });
      setCourseIntakes(records);
    } catch (error) {
      if (!isSuperuserOnlyError(error)) {
        console.error("Error fetching courses:", error);
      }
      toast.error("Failed to load courses");
    } finally {
      setFetchingData(false);
    }
  };

  const handleSubmit = async () => {
    if (!selectedCourseIntakeId) {
      toast.error("Please select a course to enroll.");
      return;
    }

    if (paymentOption === "upfront_installments" && customUpfrontAmount <= 0) {
      toast.error("Please enter an upfront amount greater than 0");
      return;
    }

    setLoading(true);
    let registrationNumber: string | null = null;
    try {
      const selectedCourse = courseIntakes.find(
        (c) => c.id === selectedCourseIntakeId,
      );
      const selectedIntake = intakes.find((i) => i.id === selectedIntakeId);

      if (!selectedCourse || !selectedIntake) {
        toast.error("Invalid intake or course selection");
        return;
      }

      if (!feeCalculation) {
        toast.error("Fee calculation not available");
        return;
      }

      // Generate unique registration number
      registrationNumber = await generateRegistrationNumber(
        selectedIntake.code,
        selectedCourse.expand?.course_intake?.expand?.course?.code || "COURSE",
      );

      // Use the already selected fee record
      const courseIntakeFeeId = selectedCourse.id;
      const courseIntakeId = selectedCourse.course_intake;

      // Create enrollment with all fields
      const enrollmentRecord = await pb.collection("enrollments").create({
        student: studentId,
        registration_number: registrationNumber,
        course_intake: courseIntakeId,
        course_intake_fees: courseIntakeFeeId,

        // Payment configuration
        payment_option: paymentOption,
        registration_fee: includeRegistrationFee,

        // Discount details
        discount_type: discountType || "",
        discount: feeCalculation.discount_amount,

        // Fee breakdown
        total_course_fee: feeCalculation.total_course_fee,
        fee_after_discount: feeCalculation.fee_after_discount,
        upfront_payment: feeCalculation.upfront_payment,
        installment_amount: feeCalculation.installment_amount,
        installment_count: feeCalculation.installment_count,
        months_remaining: feeCalculation.months_remaining,

        // Status fields
        enrollment_date: new Date().toISOString(),
        enrollement_status: "enrolled",
        certificate_status: "pending",
        remarks: discountType
          ? `Enrolled with ${discountType} discount of ${discountValue}${discountType === "percentage" ? "%" : " LKR"}`
          : "",
      });

      // Auto-create payment and installment records (non-blocking)
      try {
        // Registration fee — always a separate record
        if (
          includeRegistrationFee &&
          feeCalculation.registration_fee_amount > 0
        ) {
          await pb.collection("payments").create({
            reference_Id: generatePaymentReferenceId(
              registrationNumber,
              "registration",
            ),
            enrollment: enrollmentRecord.id,
            student: studentId,
            amount: feeCalculation.registration_fee_amount,
            payment_type: "registration",
            verified: false,
            bank_name: "",
            remarks: "Registration fee - one-time enrollment charge",
          });
        }

        // Course fee upfront portion — separate record
        const coursePortion =
          feeCalculation.upfront_payment -
          (includeRegistrationFee ? feeCalculation.registration_fee_amount : 0);
        if (coursePortion > 0) {
          const coursePayType =
            paymentOption === "full_payment" ? "full_payment" : "upfront";
          await pb.collection("payments").create({
            reference_Id: generatePaymentReferenceId(
              registrationNumber,
              coursePayType,
            ),
            enrollment: enrollmentRecord.id,
            student: studentId,
            amount: coursePortion,
            payment_type: coursePayType,
            verified: false,
            bank_name: "",
            remarks: `Auto-generated ${coursePayType} payment - Awaiting student payment confirmation`,
          });
        }

        // Create installment schedule if payment plan has installments
        if (feeCalculation.installment_count > 0) {
          const enrollmentDate = new Date();
          let firstDueDate = new Date(enrollmentDate);

          if (paymentOption === "upfront_installments") {
            // First installment starts the month after the upfront payment
            firstDueDate.setMonth(firstDueDate.getMonth() + 1);
          }
          // installments_only: first installment due same month as enrollment

          for (let i = 1; i <= feeCalculation.installment_count; i++) {
            const dueDate = new Date(firstDueDate);
            dueDate.setMonth(dueDate.getMonth() + (i - 1));

            const installmentId = generateInstallmentId(registrationNumber, i);

            await pb.collection("installments").create({
              installement_id: installmentId,
              enrollment: enrollmentRecord.id,
              due_date: dueDate.toISOString().split("T")[0],
              amount: feeCalculation.installment_amount,
              status: "pending",
              remarks: `Installment ${i} of ${feeCalculation.installment_count}`,
            });
          }
        }
      } catch (paymentError: any) {
        console.error(
          "Payment/installment creation error:",
          paymentError?.message,
          paymentError?.data,
        );
      }

      toast.success(
        `Enrolled successfully! Registration: ${registrationNumber}`,
      );
      onSuccess();
      onClose();
    } catch (error: any) {
      if (registrationNumber) {
        await rollbackRegistrationNumber(registrationNumber);
      }
      if (!isSuperuserOnlyError(error)) {
        console.error("Error creating enrollment:", error);
      }
      toast.error(
        isSuperuserOnlyError(error)
          ? "You don't have permission to perform this action."
          : error?.message || "Failed to create enrollment.",
      );
    } finally {
      setLoading(false);
    }
  };

  return (
    <ModernModal
      open={isOpen}
      onOpenChange={(v) => !v && onClose()}
      title="Enroll New Course"
      subtitle="Add a new academic pathway to this student's profile."
    >
      <div className="space-y-6">
        {/* Step 1: Intake */}
        <div className="space-y-3">
          <label className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-gray-500 ml-1">
            <Calendar size={12} className="text-indigo-400" />
            1. Select Academic Intake
          </label>
          <select
            value={selectedIntakeId}
            onChange={(e) => {
              setSelectedIntakeId(e.target.value);
              setSelectedCourseIntakeId(""); // Reset course on intake change
            }}
            className="w-full bg-white border-2 border-indigo-50 rounded-xl p-4 text-xs font-bold text-gray-900 focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/10 transition-all cursor-pointer outline-none"
          >
            <option value="">-- Choose an Intake --</option>
            {intakes.map((intake) => (
              <option key={intake.id} value={intake.id}>
                {intake.name} ({intake.code})
              </option>
            ))}
          </select>
        </div>

        {/* Step 2: Course Selection */}
        <div className="space-y-3">
          <label className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-gray-500 ml-1">
            <BookOpen size={12} className="text-indigo-400" />
            2. Available Courses
          </label>
          <div className="space-y-2">
            {!selectedIntakeId ? (
              <div className="p-4 bg-gray-50 rounded-xl border border-gray-100 text-center">
                <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">
                  Select an intake to view courses
                </p>
              </div>
            ) : fetchingData ? (
              <div className="p-4 bg-indigo-50/50 rounded-xl border border-indigo-100 text-center">
                <p className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest animate-pulse">
                  Loading available courses...
                </p>
              </div>
            ) : courseIntakes.length === 0 ? (
              <div className="p-4 bg-orange-50 rounded-xl border border-orange-100 text-center">
                <p className="text-[10px] font-bold text-orange-600 uppercase tracking-widest">
                  No courses available for this intake.
                </p>
              </div>
            ) : (
              courseIntakes.map((c) => {
                const courseInfo = c.expand?.course_intake?.expand?.course;
                const isSelected = selectedCourseIntakeId === c.id;

                return (
                  <div
                    key={c.id}
                    onClick={() => setSelectedCourseIntakeId(c.id)}
                    className={`p-4 rounded-xl border-2 transition-all cursor-pointer flex justify-between items-center ${
                      isSelected
                        ? "bg-indigo-50 border-indigo-500 shadow-md shadow-indigo-100"
                        : "bg-white border-gray-100 hover:border-indigo-200"
                    }`}
                  >
                    <div>
                      <h4
                        className={`text-sm font-black uppercase tracking-tight ${isSelected ? "text-indigo-900" : "text-gray-900"}`}
                      >
                        {courseInfo?.name || "Unknown Course"}
                      </h4>
                      <p
                        className={`text-[10px] font-bold tracking-widest uppercase mt-1 ${isSelected ? "text-indigo-500" : "text-gray-400"}`}
                      >
                        {courseInfo?.code || "N/A"} • {c.duration || "0"} Months
                      </p>
                    </div>
                    <div className="text-right">
                      <p
                        className={`text-[9px] font-black uppercase tracking-widest ${isSelected ? "text-indigo-400" : "text-gray-400"}`}
                      >
                        Total Fee
                      </p>
                      <p
                        className={`text-xs font-black ${isSelected ? "text-indigo-600" : "text-gray-900"}`}
                      >
                        LKR {c.course_fee.toLocaleString()}
                      </p>
                    </div>
                  </div>
                );
              })
            )}
          </div>
        </div>

        {/* Step 3: Payment Type */}
        {selectedCourseIntakeId && (
          <div className="space-y-3 animate-in fade-in slide-in-from-top-2 duration-300">
            <label className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-gray-500 ml-1">
              <CreditCard size={12} className="text-indigo-400" />
              3. Payment Structure
            </label>
            <div className="grid grid-cols-3 gap-3">
              {[
                {
                  id: "full_payment",
                  label: "Full Payment",
                  desc: "Entire course fee upfront",
                },
                {
                  id: "installments_only",
                  label: "Full Installments",
                  desc: "Full fee in monthly installments",
                },
                {
                  id: "upfront_installments",
                  label: "Upfront + Installments",
                  desc: "Enter upfront; balance monthly",
                },
              ].map((type) => (
                <button
                  key={type.id}
                  onClick={() => {
                    setPaymentOption(type.id as any);
                    if (type.id !== "upfront_installments")
                      setCustomUpfrontAmount(0);
                  }}
                  className={`p-3 rounded-xl border-2 transition-all text-left ${
                    paymentOption === type.id
                      ? "bg-indigo-600 border-indigo-600 text-white shadow-lg shadow-indigo-200"
                      : "bg-white border-gray-100 text-gray-500 hover:border-indigo-200 hover:text-indigo-600"
                  }`}
                >
                  <div
                    className={`text-[10px] font-black uppercase tracking-widest ${
                      paymentOption === type.id ? "text-white" : ""
                    }`}
                  >
                    {type.label}
                  </div>
                  <div
                    className={`text-[9px] font-medium mt-0.5 ${
                      paymentOption === type.id
                        ? "text-indigo-200"
                        : "text-gray-400"
                    }`}
                  >
                    {type.desc}
                  </div>
                </button>
              ))}
            </div>

            {/* Custom Upfront Amount */}
            {paymentOption === "upfront_installments" && (
              <div className="animate-in fade-in slide-in-from-top-2 duration-200 space-y-1">
                <label className="flex items-center gap-1 text-[10px] font-black uppercase tracking-widest text-gray-500 ml-1">
                  <CreditCard size={10} className="text-indigo-400" />
                  Upfront Amount (LKR) <span className="text-rose-500">*</span>
                </label>
                <input
                  type="number"
                  min="1"
                  max={feeCalculation?.fee_after_discount ?? undefined}
                  step="100"
                  value={customUpfrontAmount || ""}
                  onChange={(e) =>
                    setCustomUpfrontAmount(parseFloat(e.target.value) || 0)
                  }
                  placeholder="e.g. 5000"
                  className="w-full px-4 py-3 bg-white border-2 border-gray-100 rounded-xl text-sm font-bold text-gray-900 focus:border-indigo-400 focus:ring-4 focus:ring-indigo-100/50 transition-all placeholder:text-gray-300"
                />
                {feeCalculation && customUpfrontAmount > 0 && (
                  <p className="text-[9px] font-medium text-gray-400 ml-1">
                    Balance LKR{" "}
                    {Math.max(
                      0,
                      feeCalculation.fee_after_discount - customUpfrontAmount,
                    ).toLocaleString()}{" "}
                    →{" "}
                    {courseIntakes.find((c) => c.id === selectedCourseIntakeId)
                      ?.duration
                      ? (courseIntakes.find(
                          (c) => c.id === selectedCourseIntakeId,
                        )?.duration ?? 1) - 1
                      : 0}{" "}
                    installments
                  </p>
                )}
              </div>
            )}

            {/* Registration Fee Toggle */}
            {selectedCourseIntakeId &&
              (() => {
                const course = courseIntakes.find(
                  (c) => c.id === selectedCourseIntakeId,
                );
                const regFee = course?.registration_fee || 0;
                if (regFee <= 0) return null;
                return (
                  <div className="flex items-center justify-between px-4 py-3 bg-white rounded-xl border-2 border-gray-100">
                    <div>
                      <div className="text-[10px] font-black text-gray-700 uppercase tracking-widest">
                        Registration Fee
                      </div>
                      <div className="text-[10px] font-bold text-indigo-600 mt-0.5">
                        LKR {regFee.toLocaleString()}
                      </div>
                    </div>
                    <button
                      type="button"
                      className={`relative inline-flex h-7 w-12 items-center rounded-full transition-all ${
                        includeRegistrationFee
                          ? "bg-indigo-600 ring-4 ring-indigo-100"
                          : "bg-gray-300"
                      }`}
                      onClick={() =>
                        setIncludeRegistrationFee(!includeRegistrationFee)
                      }
                    >
                      <span
                        className={`inline-block h-5 w-5 bg-white rounded-full shadow-sm transition-transform ${
                          includeRegistrationFee
                            ? "translate-x-6"
                            : "translate-x-1"
                        }`}
                      />
                    </button>
                  </div>
                );
              })()}

            {/* Step 4: Discount (New) */}
            <div className="space-y-3 pt-2">
              <label className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-gray-500 ml-1">
                <DollarSign size={12} className="text-green-500" />
                4. Discount Options (Optional)
              </label>
              <div className="grid grid-cols-3 gap-3">
                <select
                  value={discountType || ""}
                  onChange={(e) => {
                    setDiscountType((e.target.value as any) || null);
                    setDiscountValue(0);
                  }}
                  className="px-4 py-2.5 bg-white border-2 border-gray-100 rounded-xl text-[10px] font-black uppercase tracking-widest text-gray-900 focus:border-indigo-400 focus:ring-4 focus:ring-indigo-100/50 transition-all outline-none"
                >
                  <option value="">No Discount</option>
                  <option value="percentage">Percentage %</option>
                  <option value="flat">Flat Amount</option>
                </select>
                <input
                  type="number"
                  min="0"
                  step={discountType === "percentage" ? "1" : "100"}
                  value={discountValue || ""}
                  onChange={(e) => setDiscountValue(parseFloat(e.target.value) || 0)}
                  disabled={!discountType}
                  placeholder={discountType === "percentage" ? "e.g. 10%" : "e.g. 5000"}
                  className="col-span-2 px-4 py-2.5 bg-white border-2 border-gray-100 rounded-xl text-xs font-bold text-gray-900 disabled:bg-gray-50 disabled:text-gray-300 focus:border-indigo-400 focus:ring-4 focus:ring-indigo-100/50 transition-all placeholder:text-gray-300"
                />
              </div>
            </div>

            {/* Detailed Fee Breakdown (New) */}
            {feeCalculation && (
              <div className="mt-4 p-5 bg-gradient-to-br from-indigo-50/50 to-white rounded-2xl border-2 border-indigo-100 shadow-sm animate-in fade-in zoom-in-95 duration-500">
                <div className="flex items-center gap-2 mb-4">
                  <div className="w-1 h-5 bg-indigo-600 rounded-full" />
                  <span className="text-[10px] font-black text-indigo-900 uppercase tracking-widest">
                    Fee Calculation Breakdown
                  </span>
                </div>

                <div className="space-y-2.5">
                  <div className="flex justify-between items-center text-[10px]">
                    <span className="font-bold text-gray-400 uppercase tracking-widest">
                      Course Fee
                    </span>
                    <span className="font-black text-gray-900">
                      LKR {feeCalculation.total_course_fee.toLocaleString()}
                    </span>
                  </div>

                  {feeCalculation.discount_amount > 0 && (
                    <div className="flex justify-between items-center text-[10px]">
                      <span className="font-bold text-emerald-500 uppercase tracking-widest">
                        Discount Applied
                      </span>
                      <span className="font-black text-emerald-500">
                        - LKR {feeCalculation.discount_amount.toLocaleString()}
                      </span>
                    </div>
                  )}

                  {includeRegistrationFee && feeCalculation.registration_fee_amount > 0 && (
                    <div className="flex justify-between items-center text-[10px]">
                      <span className="font-bold text-gray-400 uppercase tracking-widest">
                        Registration Fee
                      </span>
                      <span className="font-black text-gray-900">
                        LKR {feeCalculation.registration_fee_amount.toLocaleString()}
                      </span>
                    </div>
                  )}

                  <div className="pt-3 mt-1 border-t border-indigo-100/50">
                    <div className="flex justify-between items-end">
                      <div>
                        <p className="text-[9px] font-black text-indigo-400 uppercase tracking-widest mb-1">
                          {paymentOption === "installments_only"
                            ? "Initial Payment"
                            : paymentOption === "full_payment"
                              ? "Total Combined Fee"
                              : "Upfront Payment"}
                        </p>
                        <p className="text-xl font-black text-indigo-600">
                          LKR {feeCalculation.upfront_payment.toLocaleString()}
                        </p>
                      </div>
                      {feeCalculation.installment_count > 0 && (
                        <div className="text-right">
                          <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1">
                            {feeCalculation.installment_count}x Installments
                          </p>
                          <p className="text-xs font-black text-gray-900">
                            LKR {feeCalculation.installment_amount.toLocaleString()}
                            <span className="text-[9px] text-gray-400 ml-1">/mo</span>
                          </p>
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              </div>
            )}
          </div>
        )}

        {/* Action Buttons */}
        <div className="flex gap-4 pt-6 mt-6 border-t border-gray-100">
          <button
            onClick={onClose}
            disabled={loading}
            className="flex-1 py-4 rounded-2xl bg-gray-100 text-gray-600 font-black text-[10px] tracking-widest hover:bg-gray-200 transition-all uppercase active:scale-95 disabled:opacity-50"
          >
            Cancel
          </button>
          <button
            onClick={handleSubmit}
            disabled={loading || !selectedCourseIntakeId || !feeCalculation}
            className="flex-1 py-4 rounded-2xl bg-indigo-600 text-white font-black text-[10px] tracking-widest shadow-xl shadow-indigo-200 hover:bg-indigo-700 transition-all uppercase active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
          >
            {loading ? (
              <span className="w-4 h-4 border-2 border-white/20 border-t-white rounded-full animate-spin" />
            ) : (
              <Check size={16} />
            )}
            {!feeCalculation && selectedCourseIntakeId
              ? "Calculating Fees..."
              : loading
                ? "Enrolling..."
                : "Complete Enrollment"}
          </button>
        </div>
      </div>
    </ModernModal>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import {
  User,
  CreditCard,
  DollarSign,
  Check,
  Search,
  Loader2,
  Users,
} from "lucide-react";
import { ModernModal } from "@/components/ui/modern-modal";
import { Badge } from "@/components/ui/badge";
import pb from "@/lib/pocketbase";
import { toast } from "sonner";
import {
  calculateEnrollmentFees,
  EnrollmentFeeCalculation,
} from "@/lib/feeCalculator";
import {
  generateRegistrationNumber,
  rollbackRegistrationNumber,
  generateInstallmentId,
  generatePaymentReferenceId,
} from "@/lib/registrationNumberGenerator";

interface EnrollExistingStudentModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSuccess: () => void;
  intakeId: string;
  courseIntakeId: string;
}

interface Student {
  id: string;
  userId: string;
  name: string;
  email: string;
  mobile: string;
  academicStatus: string;
  avatar?: string;
}

export function EnrollExistingStudentModal({
  isOpen,
  onClose,
  onSuccess,
  intakeId,
  courseIntakeId,
}: EnrollExistingStudentModalProps) {
  const [stage, setStage] = useState(1); // 1: Select Student, 2: Payment Options
  const [loading, setLoading] = useState(false);
  const [fetchingStudents, setFetchingStudents] = useState(false);

  // Students
  const [students, setStudents] = useState<Student[]>([]);
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedStudent, setSelectedStudent] = useState<Student | null>(null);

  // Course fee details
  const [courseFee, setCourseFee] = useState(0);
  const [registrationFee, setRegistrationFee] = useState(0);
  const [duration, setDuration] = useState(0);
  const [courseIntakeFeeId, setCourseIntakeFeeId] = useState("");
  const [intakeCode, setIntakeCode] = useState("");
  const [courseCode, setCourseCode] = useState("");

  // Payment options
  const [paymentOption, setPaymentOption] = useState<
    "full_payment" | "upfront_installments" | "installments_only"
  >("full_payment");
  const [includeRegistrationFee, setIncludeRegistrationFee] = useState(true);
  const [discountType, setDiscountType] = useState<
    "percentage" | "flat" | null
  >(null);
  const [discountValue, setDiscountValue] = useState(0);
  const [customUpfrontAmount, setCustomUpfrontAmount] = useState(0);
  const [feeCalculation, setFeeCalculation] =
    useState<EnrollmentFeeCalculation | null>(null);

  // Fetch students and course details when modal opens
  useEffect(() => {
    if (isOpen) {
      fetchPendingStudents();
      fetchCourseDetails();
      resetModal();
    }
  }, [isOpen, courseIntakeId]);

  // Recalculate fees when payment options change
  useEffect(() => {
    if (stage === 2 && courseFee > 0) {
      const calc = calculateEnrollmentFees(
        courseFee,
        registrationFee,
        duration,
        paymentOption,
        includeRegistrationFee,
        discountType,
        discountValue,
        paymentOption === "upfront_installments"
          ? customUpfrontAmount
          : undefined,
      );
      setFeeCalculation(calc);
    }
  }, [
    stage,
    courseFee,
    registrationFee,
    duration,
    paymentOption,
    includeRegistrationFee,
    discountType,
    discountValue,
    customUpfrontAmount,
  ]);

  function resetModal() {
    setStage(1);
    setSelectedStudent(null);
    setSearchQuery("");
    setPaymentOption("full_payment");
    setIncludeRegistrationFee(true);
    setDiscountType(null);
    setDiscountValue(0);
    setCustomUpfrontAmount(0);
    setFeeCalculation(null);
  }

  async function fetchPendingStudents() {
    try {
      setFetchingStudents(true);

      // Get all students with pending academic status who are not already enrolled in this course
      const allStudents = await pb.collection("users").getFullList({
        filter: `role = "student" && academicStatus = "pending"`,
        sort: "name",
      });

      // Get already enrolled students in this course
      const enrollments = await pb.collection("enrollments").getFullList({
        filter: `course_intake = "${courseIntakeId}"`,
        fields: "student",
      });

      const enrolledStudentIds = enrollments.map((e: any) => e.student);

      // Filter out already enrolled students and map to Student interface
      const availableStudents: Student[] = allStudents
        .filter((s: any) => !enrolledStudentIds.includes(s.id))
        .map((s: any) => ({
          id: s.id,
          userId: s.userId || "",
          name: s.name || "",
          email: s.email || "",
          mobile: s.mobile || "",
          academicStatus: s.academicStatus || "pending",
          avatar: s.avatar || "",
        }));

      setStudents(availableStudents);
    } catch (error) {
      console.error("Error fetching students:", error);
      toast.error("Failed to load students");
    } finally {
      setFetchingStudents(false);
    }
  }

  async function fetchCourseDetails() {
    try {
      // Fetch course_intake_fees
      const fees = await pb.collection("course_intake_fees").getFullList({
        filter: `course_intake = "${courseIntakeId}"`,
        expand: "course_intake.course,course_intake.intake",
      });

      if (fees.length > 0) {
        const fee = fees[0];
        setCourseFee(fee.course_fee);
        setRegistrationFee(fee.registration_fee);
        setDuration(fee.duration);
        setCourseIntakeFeeId(fee.id);

        // Get intake and course codes (with direct-fetch fallback)
        const expandedIntakeCode =
          fee.expand?.course_intake?.expand?.intake?.code || "";
        const expandedCourseCode =
          fee.expand?.course_intake?.expand?.course?.code || "";

        if (!expandedIntakeCode && fee.expand?.course_intake?.intake) {
          try {
            const intakeRec = await pb
              .collection("intakes")
              .getOne(fee.expand.course_intake.intake);
            setIntakeCode(intakeRec.code || "");
          } catch {
            setIntakeCode("");
          }
        } else {
          setIntakeCode(expandedIntakeCode);
        }

        if (!expandedCourseCode && fee.expand?.course_intake?.course) {
          try {
            const courseRec = await pb
              .collection("courses")
              .getOne(fee.expand.course_intake.course);
            setCourseCode(courseRec.code || "");
          } catch {
            setCourseCode("");
          }
        } else {
          setCourseCode(expandedCourseCode);
        }
      }
    } catch (error) {
      console.error("Error fetching course details:", error);
      toast.error("Failed to load course details");
    }
  }

  async function handleEnroll() {
    if (!selectedStudent || !feeCalculation || !courseIntakeFeeId) return;

    if (paymentOption === "upfront_installments" && customUpfrontAmount <= 0) {
      toast.error("Please enter an upfront amount greater than 0");
      return;
    }

    let registrationNumber: string | null = null;
    try {
      setLoading(true);

      // Generate registration number
      registrationNumber = await generateRegistrationNumber(
        intakeCode,
        courseCode,
      );

      const enrollmentDate = new Date().toISOString();

      // Create enrollment
      const enrollmentData = {
        student: selectedStudent.id,
        registration_number: registrationNumber,
        course_intake: courseIntakeId,
        course_intake_fees: courseIntakeFeeId,
        payment_option: paymentOption,
        registration_fee: includeRegistrationFee,
        discount_type: discountType || "",
        discount: feeCalculation.discount_amount,
        total_course_fee: feeCalculation.total_course_fee,
        fee_after_discount: feeCalculation.fee_after_discount,
        upfront_payment: feeCalculation.upfront_payment,
        installment_amount: feeCalculation.installment_amount,
        installment_count: feeCalculation.installment_count,
        months_remaining: feeCalculation.months_remaining,
        enrollment_date: enrollmentDate,
        enrollement_status: "enrolled",
        certificate_status: "pending",
        remarks: "",
      };

      const enrollment = await pb
        .collection("enrollments")
        .create(enrollmentData);

      // Auto-create payment and installment records (non-blocking)
      try {
        // Registration fee — always a separate record
        if (
          includeRegistrationFee &&
          feeCalculation.registration_fee_amount > 0
        ) {
          await pb.collection("payments").create({
            reference_Id: generatePaymentReferenceId(
              registrationNumber,
              "registration",
            ),
            enrollment: enrollment.id,
            student: selectedStudent.id,
            amount: feeCalculation.registration_fee_amount,
            payment_type: "registration",
            verified: false,
            bank_name: "",
            remarks: "Registration fee - one-time enrollment charge",
          });
        }

        // Course fee upfront portion — separate record
        const coursePortion =
          feeCalculation.upfront_payment -
          (includeRegistrationFee ? feeCalculation.registration_fee_amount : 0);
        if (coursePortion > 0) {
          const coursePayType =
            paymentOption === "full_payment" ? "full_payment" : "upfront";
          await pb.collection("payments").create({
            reference_Id: generatePaymentReferenceId(
              registrationNumber,
              coursePayType,
            ),
            enrollment: enrollment.id,
            student: selectedStudent.id,
            amount: coursePortion,
            payment_type: coursePayType,
            verified: false,
            bank_name: "",
            remarks: `Auto-generated ${coursePayType} payment - Awaiting student payment confirmation`,
          });
        }

        // Create installment schedule
        if (feeCalculation.installment_count > 0) {
          // upfront_installments: first due month after upfront payment (+1)
          // installments_only: first due same month as enrollment (+0)
          const startMonth = paymentOption === "upfront_installments" ? 1 : 0;
          for (let i = 1; i <= feeCalculation.installment_count; i++) {
            const installmentId = generateInstallmentId(registrationNumber, i);
            const dueDate = new Date(enrollmentDate);
            dueDate.setMonth(dueDate.getMonth() + startMonth + (i - 1));
            await pb.collection("installments").create({
              installement_id: installmentId,
              enrollment: enrollment.id,
              due_date: dueDate.toISOString().split("T")[0],
              amount: feeCalculation.installment_amount,
              status: "pending",
              remarks: `Installment ${i} of ${feeCalculation.installment_count}`,
            });
          }
        }
      } catch (paymentError: any) {
        console.error(
          "Payment/installment creation error:",
          paymentError?.message,
          paymentError?.data,
        );
      }

      // Update student's academic status
      await pb.collection("users").update(selectedStudent.id, {
        academicStatus: "enrolled",
      });

      toast.success(`${selectedStudent.name} enrolled successfully!`);
      onSuccess();
      onClose();
    } catch (error: any) {
      console.error("Error enrolling student:", error?.message, error?.data);
      const fieldErrors = error?.data?.data
        ? Object.entries(error.data.data)
            .map(([field, err]: any) => `${field}: ${err?.message || err}`)
            .join(", ")
        : null;
      if (registrationNumber) {
        await rollbackRegistrationNumber(registrationNumber);
      }
      toast.error(fieldErrors || error?.message || "Failed to enroll student");
    } finally {
      setLoading(false);
    }
  }

  const filteredStudents = students.filter(
    (s) =>
      s.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      s.email.toLowerCase().includes(searchQuery.toLowerCase()) ||
      s.userId.toLowerCase().includes(searchQuery.toLowerCase()),
  );

  return (
    <ModernModal
      open={isOpen}
      onOpenChange={(open) => {
        if (!open) onClose();
      }}
      title={
        stage === 1 ? "Select Student to Enroll" : "Configure Payment Options"
      }
      subtitle={
        stage === 1
          ? "Choose a student with pending status to enroll in this course"
          : `Enrolling ${selectedStudent?.name || ""}`
      }
      avatarChar="E"
      avatarColor="bg-green-600"
      className="max-w-6xl"
    >
      <div className="space-y-6">
        {stage === 1 ? (
          // Stage 1: Select Student
          <>
            {/* Search Bar */}
            <div className="relative">
              <Search
                className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400"
                size={20}
              />
              <input
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Search by name, email, or student ID..."
                className="w-full pl-12 pr-5 py-4 bg-gray-50 border border-gray-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-green-500/20 font-medium transition-all"
              />
            </div>

            {/* Students List */}
            <div className="space-y-3 max-h-[500px] overflow-y-auto">
              {fetchingStudents ? (
                <div className="flex items-center justify-center py-20">
                  <Loader2 className="w-8 h-8 text-green-600 animate-spin" />
                </div>
              ) : filteredStudents.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-20 text-center">
                  <Users size={48} className="text-gray-300 mb-4" />
                  <p className="text-sm font-bold text-gray-400 uppercase tracking-widest">
                    {searchQuery
                      ? "No students found matching your search"
                      : "No pending students available"}
                  </p>
                  <p className="text-xs text-gray-400 mt-2">
                    All eligible students may already be enrolled in this course
                  </p>
                </div>
              ) : (
                filteredStudents.map((student) => (
                  <button
                    key={student.id}
                    onClick={() => {
                      setSelectedStudent(student);
                      setStage(2);
                    }}
                    className="w-full p-6 bg-white border-2 border-gray-100 rounded-2xl hover:border-green-600 hover:bg-green-50/30 transition-all text-left group"
                  >
                    <div className="flex items-center gap-4">
                      <div className="w-14 h-14 rounded-2xl bg-gradient-to-br from-green-500 to-emerald-600 flex items-center justify-center text-white font-black text-xl shadow-lg">
                        {student.name.charAt(0).toUpperCase()}
                      </div>
                      <div className="flex-1">
                        <div className="font-black text-lg text-gray-900 group-hover:text-green-600 transition-colors">
                          {student.name}
                        </div>
                        <div className="flex items-center gap-3 mt-1">
                          <span className="text-xs font-medium text-gray-500">
                            {student.email}
                          </span>
                          <span className="text-xs font-bold text-gray-400">
                            •
                          </span>
                          <span className="text-xs font-medium text-gray-500">
                            {student.userId}
                          </span>
                        </div>
                        {student.mobile && (
                          <div className="text-xs font-medium text-gray-400 mt-1">
                            📱 {student.mobile}
                          </div>
                        )}
                      </div>
                      <Badge className="bg-amber-100 text-amber-700 border-0 px-3 py-1 rounded-lg text-xs font-black uppercase">
                        Pending
                      </Badge>
                    </div>
                  </button>
                ))
              )}
            </div>
          </>
        ) : (
          // Stage 2: Payment Options
          <div className="space-y-5">
            {/* Selected Student Info - compact */}
            <div className="flex items-center gap-3 px-4 py-3 bg-gray-50 border border-gray-100 rounded-2xl">
              <div className="w-10 h-10 rounded-xl bg-green-600 flex items-center justify-center text-white font-black text-base flex-shrink-0">
                {selectedStudent?.name.charAt(0).toUpperCase()}
              </div>
              <div className="min-w-0">
                <div className="font-black text-sm text-gray-900 truncate">
                  {selectedStudent?.name}
                </div>
                <div className="text-xs font-medium text-gray-400 truncate">
                  {selectedStudent?.email}
                </div>
              </div>
            </div>

            {/* Payment Structure - compact stacked */}
            <div>
              <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-3 ml-1">
                Payment Structure
              </label>
              <div className="space-y-2">
                {[
                  {
                    value: "full_payment",
                    label: "Full Payment",
                    desc: "Pay the entire course fee upfront",
                  },
                  {
                    value: "upfront_installments",
                    label: "Upfront + Installments",
                    desc: "Enter an upfront amount — balance splits into monthly installments",
                  },
                  {
                    value: "installments_only",
                    label: "Full Installments",
                    desc: "Full course fee converts to equal monthly installments",
                  },
                ].map((option) => (
                  <button
                    key={option.value}
                    type="button"
                    onClick={() => {
                      setPaymentOption(option.value as any);
                      if (option.value !== "upfront_installments")
                        setCustomUpfrontAmount(0);
                    }}
                    className={`w-full flex items-center justify-between px-5 py-3 rounded-2xl border-2 transition-all text-left ${
                      paymentOption === option.value
                        ? "border-green-600 bg-green-50"
                        : "border-gray-100 bg-gray-50 hover:border-green-200"
                    }`}
                  >
                    <div>
                      <div
                        className={`text-sm font-black uppercase tracking-wide ${
                          paymentOption === option.value
                            ? "text-green-700"
                            : "text-gray-700"
                        }`}
                      >
                        {option.label}
                      </div>
                      <div className="text-[10px] font-medium text-gray-400 mt-0.5">
                        {option.desc}
                      </div>
                    </div>
                    {paymentOption === option.value && (
                      <Check
                        size={16}
                        className="text-green-600 flex-shrink-0"
                      />
                    )}
                  </button>
                ))}
              </div>
            </div>

            {/* Custom Upfront Amount — shown only for upfront_installments */}
            {paymentOption === "upfront_installments" && (
              <div className="animate-in fade-in slide-in-from-top-2 duration-200">
                <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2 ml-1">
                  Upfront Amount (LKR) <span className="text-rose-500">*</span>
                </label>
                <input
                  type="number"
                  min="1"
                  max={feeCalculation?.fee_after_discount ?? undefined}
                  step="100"
                  value={customUpfrontAmount || ""}
                  onChange={(e) =>
                    setCustomUpfrontAmount(parseFloat(e.target.value) || 0)
                  }
                  placeholder="e.g. 5000"
                  className="w-full px-5 py-4 bg-white border-2 border-gray-100 rounded-2xl text-sm font-bold text-gray-900 focus:outline-none focus:ring-2 focus:ring-green-500/20 transition-all placeholder:text-gray-300"
                />
                {feeCalculation && (
                  <p className="text-[10px] font-medium text-gray-400 mt-1.5 ml-1">
                    Balance:{" "}
                    <span className="font-bold text-gray-600">
                      LKR{" "}
                      {Math.max(
                        0,
                        feeCalculation.fee_after_discount -
                          (customUpfrontAmount || 0),
                      ).toLocaleString()}
                    </span>{" "}
                    splits into{" "}
                    <span className="font-bold text-green-600">
                      {duration > 1 ? duration - 1 : 1} monthly installments
                    </span>
                  </p>
                )}
              </div>
            )}

            {/* Registration Fee Toggle */}
            <div className="flex items-center justify-between p-5 bg-white rounded-2xl border-2 border-gray-100 shadow-sm">
              <div className="flex flex-col gap-1">
                <span className="text-sm font-black text-gray-700 uppercase tracking-wide">
                  Include Registration Fee
                </span>
                <span className="text-xs font-bold text-green-600">
                  LKR {registrationFee.toLocaleString()}
                </span>
                <span className="text-[10px] font-medium text-gray-400 uppercase tracking-widest">
                  One-time enrollment charge
                </span>
              </div>
              <button
                type="button"
                className={`relative inline-flex h-8 w-14 items-center rounded-full transition-all shadow-md ${
                  includeRegistrationFee
                    ? "bg-green-600 ring-4 ring-green-200"
                    : "bg-gray-300"
                }`}
                onClick={() =>
                  setIncludeRegistrationFee(!includeRegistrationFee)
                }
              >
                <span
                  className={`inline-block h-6 w-6 bg-white rounded-full shadow-sm transition-transform ${
                    includeRegistrationFee ? "translate-x-7" : "translate-x-1"
                  }`}
                />
              </button>
            </div>

            {/* Discount Section */}
            <div className="space-y-3">
              <label className="flex items-center gap-2 text-xs font-black text-gray-700 uppercase tracking-widest">
                <DollarSign size={14} className="text-green-600" />
                Apply Discount (Optional)
              </label>
              <div className="grid grid-cols-2 gap-4">
                <select
                  value={discountType || ""}
                  onChange={(e) =>
                    setDiscountType(
                      e.target.value === ""
                        ? null
                        : (e.target.value as "percentage" | "flat"),
                    )
                  }
                  className="px-5 py-4 bg-white border-2 border-gray-100 rounded-2xl focus:outline-none focus:ring-2 focus:ring-green-500/20 font-bold transition-all"
                >
                  <option value="">No Discount</option>
                  <option value="percentage">Percentage (%)</option>
                  <option value="flat">Flat Amount (LKR)</option>
                </select>
                <input
                  type="number"
                  value={discountValue}
                  onChange={(e) =>
                    setDiscountValue(parseFloat(e.target.value) || 0)
                  }
                  disabled={!discountType}
                  placeholder="Enter value"
                  className="px-5 py-4 bg-white border-2 border-gray-100 rounded-2xl focus:outline-none focus:ring-2 focus:ring-green-500/20 font-bold transition-all disabled:opacity-50"
                />
              </div>
            </div>

            {/* Fee Breakdown */}
            {feeCalculation && (
              <div className="p-6 bg-gradient-to-br from-green-50 via-emerald-50 to-teal-50 rounded-2xl border-2 border-green-100">
                <div className="text-xs font-black text-green-700 uppercase tracking-widest mb-4">
                  Fee Breakdown
                </div>
                <div className="space-y-3">
                  <div className="flex justify-between items-center text-sm">
                    <span className="font-medium text-gray-600">
                      Course Fee
                    </span>
                    <span className="font-bold text-gray-900">
                      LKR {feeCalculation.total_course_fee.toLocaleString()}
                    </span>
                  </div>
                  {feeCalculation.discount_amount > 0 && (
                    <>
                      <div className="flex justify-between items-center text-sm">
                        <span className="font-medium text-gray-600">
                          Discount Applied
                        </span>
                        <span className="font-bold text-green-600">
                          - LKR{" "}
                          {feeCalculation.discount_amount.toLocaleString()}
                        </span>
                      </div>
                      <div className="flex justify-between items-center text-sm">
                        <span className="font-medium text-gray-600">
                          Fee After Discount
                        </span>
                        <span className="font-bold text-gray-900">
                          LKR{" "}
                          {feeCalculation.fee_after_discount.toLocaleString()}
                        </span>
                      </div>
                    </>
                  )}
                  {includeRegistrationFee && (
                    <div className="flex justify-between items-center text-sm">
                      <span className="font-medium text-gray-600">
                        Registration Fee
                      </span>
                      <span className="font-bold text-gray-900">
                        LKR{" "}
                        {feeCalculation.registration_fee_amount.toLocaleString()}
                      </span>
                    </div>
                  )}
                  <div className="border-t-2 border-green-200 pt-3 mt-3">
                    {paymentOption === "installments_only" ? (
                      <p className="text-xs font-bold text-orange-500 uppercase tracking-widest">
                        No upfront course payment — full fee splits into
                        installments
                      </p>
                    ) : (
                      <div className="flex justify-between items-center">
                        <span className="text-base font-black text-gray-900 uppercase">
                          {paymentOption === "full_payment"
                            ? "Full Payment"
                            : "Upfront Payment"}
                        </span>
                        <span className="text-2xl font-black text-green-600">
                          LKR
                          {paymentOption === "full_payment"
                            ? ` ${feeCalculation.upfront_payment.toLocaleString()}`
                            : ` ${customUpfrontAmount.toLocaleString()}`}
                        </span>
                      </div>
                    )}
                  </div>
                  {feeCalculation.installment_count > 0 && (
                    <div className="flex justify-between items-center text-sm">
                      <span className="font-medium text-gray-600">
                        Monthly Installments
                      </span>
                      <span className="font-bold text-gray-900">
                        {feeCalculation.installment_count} × LKR{" "}
                        {feeCalculation.installment_amount.toLocaleString()}
                      </span>
                    </div>
                  )}
                </div>
              </div>
            )}

            {/* Actions */}
            <div className="flex gap-3 pt-4">
              <button
                onClick={() => setStage(1)}
                disabled={loading}
                className="flex-1 py-4 bg-gray-100 text-gray-700 rounded-2xl font-black text-sm hover:bg-gray-200 transition-all uppercase tracking-widest disabled:opacity-50"
              >
                Back
              </button>
              <button
                onClick={handleEnroll}
                disabled={loading || !feeCalculation}
                className="flex-1 py-4 bg-green-600 text-white rounded-2xl font-black text-sm shadow-xl shadow-green-100 hover:bg-green-700 transition-all uppercase tracking-widest flex items-center justify-center gap-2 disabled:opacity-50"
              >
                {loading ? (
                  <>
                    <Loader2 size={18} className="animate-spin" />
                    Enrolling...
                  </>
                ) : (
                  <>
                    <Check size={18} />
                    Enroll Student
                  </>
                )}
              </button>
            </div>
          </div>
        )}
      </div>
    </ModernModal>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import {
  User,
  Mail,
  Phone,
  MapPin,
  ChevronRight,
  ChevronLeft,
  Check,
  Key,
  Calendar,
  Type,
  IdCard,
  Globe,
  MessageSquare,
  Camera,
  Upload,
  X,
  Shield,
  GraduationCap,
  Building2,
  Briefcase,
} from "lucide-react";
import { ModernModal } from "@/components/ui/modern-modal";
import { Badge } from "@/components/ui/badge";
import pb, { isSuperuserOnlyError } from "@/lib/pocketbase";
import { toast } from "sonner";
import Image from "next/image";

interface EditUser {
  id: string;
  userId: string;
  name: string;
  nameinitials: string;
  email: string;
  role: "admin" | "lecturer";
  gender: string;
  dateOfBirth: string;
  IdentificationDocument: string;
  countryCode: string;
  mobile: string;
  whatsapp: string;
  address: string;
  city: string;
  branch: string;
  designation: string;
  field: string;
  mainDepartment: string;
  subDepartment: string;
  hiredOn: string;
  internalNotes: string;
  avatar: string;
  collectionId: string;
}

interface RegisterStaffModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSuccess: () => void;
  defaultRole?: "admin" | "lecturer";
  editUser?: EditUser | null;
}

export function RegisterStaffModal({
  isOpen,
  onClose,
  onSuccess,
  defaultRole = "admin",
  editUser = null,
}: RegisterStaffModalProps) {
  const isEditMode = !!editUser;
  const [stage, setStage] = useState(1);
  const [loading, setLoading] = useState(false);
  const [validationError, setValidationError] = useState("");
  const [avatarFile, setAvatarFile] = useState<File | null>(null);
  const [avatarPreview, setAvatarPreview] = useState<string | null>(null);

  const [formData, setFormData] = useState({
    // Stage 1: Role & Identity
    role: defaultRole as "admin" | "lecturer",
    name: "",
    nameinitials: "",
    gender: "male",
    dateOfBirth: "",
    IdentificationDocument: "",

    // Stage 2: Contact
    email: "",
    mobile: "",
    whatsapp: "",
    address: "",
    city: "",
    countryCode: "+94",

    // Stage 3: Account & Role Details
    userId: "",
    password: "",
    branch: "Colombo",
    designation: "",
    field: "",
    mainDepartment: "",
    subDepartment: "",
    hiredOn: new Date().toISOString().slice(0, 10),
    internalNotes: "",
  });

  useEffect(() => {
    if (isOpen) {
      setStage(1);
      setAvatarFile(null);
      setValidationError("");

      if (editUser) {
        // Pre-fill with existing user data
        setFormData({
          role: editUser.role,
          name: editUser.name || "",
          nameinitials: editUser.nameinitials || "",
          gender: editUser.gender || "male",
          dateOfBirth: editUser.dateOfBirth
            ? editUser.dateOfBirth.slice(0, 10)
            : "",
          IdentificationDocument: editUser.IdentificationDocument || "",
          email: editUser.email || "",
          mobile: editUser.mobile || "",
          whatsapp: editUser.whatsapp || "",
          address: editUser.address || "",
          city: editUser.city || "",
          countryCode: editUser.countryCode || "+94",
          userId: editUser.userId || "",
          password: "",
          branch: editUser.branch || "Colombo",
          designation: editUser.designation || "",
          field: editUser.field || "",
          mainDepartment: editUser.mainDepartment || "",
          subDepartment: editUser.subDepartment || "",
          hiredOn: editUser.hiredOn
            ? editUser.hiredOn.slice(0, 10)
            : new Date().toISOString().slice(0, 10),
          internalNotes: editUser.internalNotes || "",
        });
        // Show existing avatar if any
        if (editUser.avatar) {
          setAvatarPreview(
            pb.files.getURL(editUser, editUser.avatar, { thumb: "200x200" }),
          );
        } else {
          setAvatarPreview(null);
        }
      } else {
        // Reset for create mode
        setFormData((prev) => ({
          ...prev,
          role: defaultRole,
          name: "",
          nameinitials: "",
          gender: "male",
          dateOfBirth: "",
          IdentificationDocument: "",
          email: "",
          mobile: "",
          whatsapp: "",
          address: "",
          city: "",
          countryCode: "+94",
          userId: "",
          password: "",
          branch: "Colombo",
          designation: "",
          field: "",
          mainDepartment: "",
          subDepartment: "",
          hiredOn: new Date().toISOString().slice(0, 10),
          internalNotes: "",
        }));
        setAvatarPreview(null);
        generateNextUserId(defaultRole);
      }
    }
  }, [isOpen, defaultRole, editUser]);

  // Re-generate userId when role changes (only in create mode)
  useEffect(() => {
    if (isOpen && !isEditMode) {
      generateNextUserId(formData.role);
    }
  }, [formData.role]);

  const generateNextUserId = async (role: "admin" | "lecturer") => {
    try {
      if (role === "admin") {
        const records = await pb.collection("users").getList(1, 1, {
          filter: 'userId ~ "ADMIN%"',
          sort: "-userId",
        });

        let nextNumber = 1;
        if (records.items.length > 0) {
          const lastUserId = records.items[0].userId;
          const numMatch = lastUserId.match(/ADMIN(\d+)$/);
          if (numMatch) {
            nextNumber = parseInt(numMatch[1]) + 1;
          }
        }

        const nextUserId = `ADMIN${String(nextNumber).padStart(4, "0")}`;
        setFormData((prev) => ({ ...prev, userId: nextUserId }));
      } else {
        // Lecturer: ACDX-LECT0001
        const records = await pb.collection("users").getList(1, 1, {
          filter: 'userId ~ "ACDX-LECT%"',
          sort: "-userId",
        });

        let nextNumber = 1;
        if (records.items.length > 0) {
          const lastUserId = records.items[0].userId;
          const numMatch = lastUserId.match(/LECT(\d+)$/);
          if (numMatch) {
            nextNumber = parseInt(numMatch[1]) + 1;
          }
        }

        const nextUserId = `ACDX-LECT${String(nextNumber).padStart(4, "0")}`;
        setFormData((prev) => ({ ...prev, userId: nextUserId }));
      }
    } catch (error) {
      if (!isSuperuserOnlyError(error)) {
        console.error("Error generating userId:", error);
      }
      const fallback =
        role === "admin"
          ? `ADMIN${Date.now().toString().slice(-4)}`
          : `ACDX-LECT${Date.now().toString().slice(-4)}`;
      setFormData((prev) => ({ ...prev, userId: fallback }));
    }
  };

  const handleAvatarChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setAvatarFile(file);
      const reader = new FileReader();
      reader.onloadend = () => setAvatarPreview(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const getMissingRequiredFields = () => {
    const missing: string[] = [];

    if (stage === 1) {
      if (!formData.name.trim()) missing.push("Full Name");
      if (!formData.nameinitials.trim()) missing.push("Name with Initials");
      if (!formData.dateOfBirth) missing.push("Date of Birth");
      if (!formData.IdentificationDocument.trim())
        missing.push("ID / Passport Number");
    }

    if (stage === 2) {
      if (!formData.email.trim()) missing.push("Email");
      if (!formData.mobile.trim()) missing.push("Mobile");
    }

    return missing;
  };

  const handlePrimaryAction = () => {
    const missing = getMissingRequiredFields();
    if (missing.length) {
      const message = `Please fill required fields: ${missing.join(", ")}`;
      setValidationError(message);
      toast.error(message);
      return;
    }
    if (stage === 3) {
      handleSubmit();
      return;
    }
    setValidationError("");
    setStage((prev) => prev + 1);
  };

  const handleSubmit = async () => {
    setLoading(true);
    try {
      const data = new FormData();
      data.append("name", formData.name);
      data.append("nameinitials", formData.nameinitials);
      data.append("email", formData.email);
      data.append("gender", formData.gender);
      data.append("dateOfBirth", formData.dateOfBirth);
      data.append("IdentificationDocument", formData.IdentificationDocument);
      data.append("countryCode", formData.countryCode);
      data.append("mobile", formData.mobile);
      data.append("whatsapp", formData.whatsapp || formData.mobile);
      data.append("address", formData.address);
      data.append("city", formData.city);
      data.append("role", formData.role);
      data.append("branch", formData.branch);
      data.append("designation", formData.designation);
      data.append("field", formData.field);
      data.append("mainDepartment", formData.mainDepartment);
      data.append("subDepartment", formData.subDepartment);
      data.append("hiredOn", formData.hiredOn);
      data.append("internalNotes", formData.internalNotes);

      if (avatarFile) {
        data.append("avatar", avatarFile);
      }

      if (isEditMode && editUser) {
        // If admin entered a new password, reset it via server-side admin API
        if (formData.password) {
          const res = await fetch(
            `/api/admin/users/${editUser.id}/reset-password`,
            {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({ newPassword: formData.password }),
            },
          );

          if (!res.ok) {
            const err = await res.json().catch(() => null);
            const msg = err?.error || "Failed to reset password";
            toast.error(msg);
            setLoading(false);
            return;
          }
        }

        // Update existing user (non-password fields) directly via PocketBase
        data.append("userId", formData.userId);
        data.append("emailVisibility", "true");

        await pb.collection("users").update(editUser.id, data);

        toast.success(
          `${formData.role === "admin" ? "Admin" : "Lecturer"} account updated: ${formData.userId}`,
        );
      } else {
        // Create new user
        data.append("userId", formData.userId);
        data.append("password", formData.password || formData.userId);
        data.append("passwordConfirm", formData.password || formData.userId);
        data.append("emailVisibility", "true");
        data.append("accountStatus", "active");

        // Non-required fields with defaults
        data.append("guardianName", "N/A");
        data.append("guardianRelationship", "guardian");
        data.append("guardianContact", "N/A");

        await pb.collection("users").create(data);

        toast.success(
          `${formData.role === "admin" ? "Admin" : "Lecturer"} account created: ${formData.userId}`,
        );
      }

      onSuccess();
      onClose();
    } catch (error: any) {
      console.error(
        `Error ${isEditMode ? "updating" : "creating"} staff account:`,
        error,
      );

      // Extract field-specific error messages
      const fieldErrors = error?.response?.data || {};
      let firstErrorMessage = "";

      for (const field in fieldErrors) {
        if (fieldErrors[field]?.message) {
          firstErrorMessage = `${field}: ${fieldErrors[field].message}`;
          break;
        }
      }

      const errorMessage =
        firstErrorMessage ||
        `Failed to ${isEditMode ? "update" : "create"} account`;
      toast.error(errorMessage);
    } finally {
      setLoading(false);
    }
  };

  const stages = [
