      </div>
    </ModernModal>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import {
  User,
  Mail,
  Phone,
  MapPin,
  BookOpen,
  CreditCard,
  ChevronRight,
  ChevronLeft,
  Check,
  Key,
  Layers,
  Calendar,
  DollarSign,
  Type,
  IdCard,
  Users,
  Building2,
  Globe,
  MessageSquare,
  Hash,
  Camera,
  Upload,
  X,
} from "lucide-react";
import { ModernModal } from "@/components/ui/modern-modal";
import { Badge } from "@/components/ui/badge";
import pb, { isSuperuserOnlyError } from "@/lib/pocketbase";
import { toast } from "sonner";
import Image from "next/image";
import {
  calculateEnrollmentFees,
  EnrollmentFeeCalculation,
} from "@/lib/feeCalculator";
import {
  generateRegistrationNumber,
  rollbackRegistrationNumber,
  generateInstallmentId,
  generatePaymentReferenceId,
} from "@/lib/registrationNumberGenerator";

interface RegisterStudentModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSuccess: () => void;
  enrollOnly?: {
    id?: string;
    name?: string;
    email?: string;
    preselectedIntakeId?: string;
    preselectedCourseIntakeId?: string;
  };
}

interface Intake {
  id: string;
  code: string;
  name: string;
}

interface CourseIntakeFee {
  id: string;
  course_intake: string;
  course_fee: number;
  registration_fee: number;
  duration: number;
  expand?: {
    course_intake: {
      expand?: {
        course: { id: string; name: string; code: string };
      };
    };
  };
}

export function RegisterStudentModal({
  isOpen,
  onClose,
  onSuccess,
  enrollOnly,
}: RegisterStudentModalProps) {
  const [stage, setStage] = useState(enrollOnly ? 4 : 1);
  const [loading, setLoading] = useState(false);
  const [fetchingData, setFetchingData] = useState(false);

  const [intakes, setIntakes] = useState<Intake[]>([]);
  const [courseIntakes, setCourseIntakes] = useState<CourseIntakeFee[]>([]);
  const [avatarFile, setAvatarFile] = useState<File | null>(null);
  const [avatarPreview, setAvatarPreview] = useState<string | null>(null);
  const [enrollNow, setEnrollNow] = useState(true);
  const [validationError, setValidationError] = useState<string>("");
  const [feeCalculation, setFeeCalculation] =
    useState<EnrollmentFeeCalculation | null>(null);

  const [formData, setFormData] = useState({
    // Stage 1: Identity
    name: enrollOnly?.name || "",
    nameinitials: "",
    gender: "male",
    dateOfBirth: "",
    IdentificationDocument: "",

    // Stage 2: Contact
    email: enrollOnly?.email || "",
    mobile: "",
    whatsapp: "",
    address: "",
    city: "",
    countryCode: "+94",

    // Stage 3: Account & Site
    userId: "",
    password: "",
    branch: "Colombo",

    // Guardian Details (required)
    guardianName: "",
    guardianRelationship: "",
    guardianContact: "",

    // Stage 4: Enrollment
    intakeId: "",
    courseIntakeFeeId: "", // This maps to course_intake_fees
    paymentOption: "full_payment" as
      | "full_payment"
      | "upfront_installments"
      | "installments_only",
    includeRegistrationFee: true,
    customUpfrontAmount: 0,
    discountType: null as "percentage" | "flat" | null,
    discountValue: 0,
  });

  useEffect(() => {
    if (isOpen) {
      setStage(enrollOnly ? 4 : 1);
      setFormData((prev) => ({
        ...prev,
        name: enrollOnly?.name || "",
        email: enrollOnly?.email || "",
        intakeId: enrollOnly?.preselectedIntakeId || "",
      }));
      fetchIntakes();
      if (!enrollOnly?.id) {
        generateNextUserId();
      }
      setAvatarFile(null);
      setAvatarPreview(null);
      setEnrollNow(true);
      setValidationError("");
      setFeeCalculation(null);
    }
  }, [isOpen, enrollOnly]);

  // Preselect course when courseIntakes load
  useEffect(() => {
    if (enrollOnly?.preselectedCourseIntakeId && courseIntakes.length > 0) {
      const matchingFee = courseIntakes.find(
        (f) => f.course_intake === enrollOnly.preselectedCourseIntakeId,
      );
      if (matchingFee) {
        setFormData((prev) => ({
          ...prev,
          courseIntakeFeeId: matchingFee.id,
        }));
      }
    }
  }, [enrollOnly?.preselectedCourseIntakeId, courseIntakes]);

  // Recalculate fees when payment options change
  useEffect(() => {
    if (formData.courseIntakeFeeId && enrollNow) {
      const selectedFee = courseIntakes.find(
        (f) => f.id === formData.courseIntakeFeeId,
      );
      if (selectedFee) {
        const calc = calculateEnrollmentFees(
          selectedFee.course_fee,
          selectedFee.registration_fee,
          selectedFee.duration,
          formData.paymentOption,
          formData.includeRegistrationFee,
          formData.discountType,
          formData.discountValue,
          formData.paymentOption === "upfront_installments"
            ? formData.customUpfrontAmount
            : undefined,
        );
        setFeeCalculation(calc);
      }
    } else {
      setFeeCalculation(null);
    }
  }, [
    formData.courseIntakeFeeId,
    formData.paymentOption,
    formData.includeRegistrationFee,
    formData.customUpfrontAmount,
    formData.discountType,
    formData.discountValue,
    enrollNow,
    courseIntakes,
  ]);

  const handleAvatarChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setAvatarFile(file);
      const reader = new FileReader();
      reader.onloadend = () => {
        setAvatarPreview(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const generateNextUserId = async () => {
    try {
      // Get the latest user with a userId starting with ACDX
      const records = await pb.collection("users").getList(1, 1, {
        filter: 'userId ~ "ACDX%"',
        sort: "-userId",
      });

      let nextNumber = 100001; // Default starting number

      if (records.items.length > 0) {
        const lastUserId = records.items[0].userId;
        const lastNumberMatch = lastUserId.match(/\d+$/);
        if (lastNumberMatch) {
          nextNumber = parseInt(lastNumberMatch[0]) + 1;
        }
      }

      const nextUserId = `ACDX${nextNumber}`;
      setFormData((prev) => ({ ...prev, userId: nextUserId }));
    } catch (error) {
      if (!isSuperuserOnlyError(error)) {
        console.error("Error generating userId:", error);
      }
      // Fallback to a timestamp based unique ID if DB fetch fails
      const fallbackId = `ACDX${Date.now().toString().slice(-6)}`;
      setFormData((prev) => ({ ...prev, userId: fallbackId }));
    }
  };

  useEffect(() => {
    if (formData.intakeId) {
      fetchCoursesForIntake(formData.intakeId);
    }
  }, [formData.intakeId]);

  const fetchIntakes = async () => {
    try {
      const records = await pb.collection("intakes").getFullList<Intake>({
        sort: "-created",
      });
      setIntakes(records);
    } catch (error) {
      if (!isSuperuserOnlyError(error)) {
        console.error("Error fetching intakes:", error);
      }
    }
  };

  const fetchCoursesForIntake = async (intakeId: string) => {
    setFetchingData(true);
    try {
      // Fetch course_intake_fees and expand course_intake -> course
      const records = await pb
        .collection("course_intake_fees")
        .getFullList<CourseIntakeFee>({
          filter: `course_intake.intake = "${intakeId}"`,
          expand: "course_intake.course",
        });
      setCourseIntakes(records);
    } catch (error) {
      if (!isSuperuserOnlyError(error)) {
        console.error("Error fetching courses:", error);
      }
    } finally {
      setFetchingData(false);
    }
  };

  const handleNext = () => {
    setValidationError("");
    setStage((prev) => prev + 1);
  };
  const handleBack = () => {
    setValidationError("");
    setStage((prev) => prev - 1);
  };

  const getMissingRequiredFields = () => {
    const missing: string[] = [];

    if (stage === 1) {
      if (!formData.name.trim()) missing.push("Full Name");
      if (!formData.nameinitials.trim()) missing.push("Name with Initials");
      if (!formData.dateOfBirth) missing.push("Date of Birth");
      if (!formData.IdentificationDocument.trim())
        missing.push("ID / Passport Number");
      if (!formData.guardianName.trim()) missing.push("Guardian Name");
      if (!formData.guardianRelationship.trim())
        missing.push("Guardian Relationship");
      if (!formData.guardianContact.trim()) missing.push("Guardian Contact");
    }

    if (stage === 2) {
      if (!formData.email.trim()) missing.push("Email");
      if (!formData.mobile.trim()) missing.push("Mobile");
    }

    if (stage === 4 && enrollNow && !formData.courseIntakeFeeId) {
      missing.push("Course Selection");
    }

    if (
      stage === 4 &&
      enrollNow &&
      formData.paymentOption === "upfront_installments" &&
      formData.customUpfrontAmount <= 0
    ) {
      missing.push("Upfront Amount (must be greater than 0)");
    }

    return missing;
  };

  const handlePrimaryAction = () => {
    const missing = getMissingRequiredFields();
    if (missing.length) {
      const message = `Please fill required fields: ${missing.join(", ")}`;
      setValidationError(message);
      toast.error(message);
      return;
    }

    if (stage === 4) {
      handleSubmit();
      return;
    }

    handleNext();
  };

  const handleSubmit = async () => {
    setLoading(true);
    let registrationNumber: string | null = null;
    try {
      let studentId = enrollOnly?.id;

      if (!enrollOnly) {
        // Step 1: Create User with all schema fields using FormData for Avatar
        const data = new FormData();
        data.append("userId", formData.userId);
        data.append("name", formData.name);
        data.append("nameinitials", formData.nameinitials);
        data.append("email", formData.email);
        data.append("gender", formData.gender);
        data.append("dateOfBirth", formData.dateOfBirth);
        data.append("IdentificationDocument", formData.IdentificationDocument);
        data.append("countryCode", formData.countryCode);
        data.append("mobile", formData.mobile);
        data.append("whatsapp", formData.whatsapp);
        data.append("address", formData.address);
        data.append("city", formData.city);
        data.append("guardianName", formData.guardianName);
        data.append("guardianRelationship", formData.guardianRelationship);
        data.append("guardianContact", formData.guardianContact);
        data.append("password", formData.password || formData.userId);
        data.append("passwordConfirm", formData.password || formData.userId);
        data.append("emailVisibility", "true");
        data.append("role", "student");
        data.append("branch", formData.branch);
        data.append("accountStatus", "active");
        data.append("academicStatus", enrollNow ? "enrolled" : "pending");

        if (avatarFile) {
          data.append("avatar", avatarFile);
        }

        const newUser = await pb.collection("users").create(data);
        studentId = newUser.id;
      }

      // Step 2: Create Enrollment with complete data
      if (enrollNow && formData.courseIntakeFeeId) {
        const selectedFee = courseIntakes.find(
          (f) => f.id === formData.courseIntakeFeeId,
        );
        const selectedIntake = intakes.find((i) => i.id === formData.intakeId);

        if (selectedFee && selectedIntake) {
          // Calculate all fees
          const feeCalc = calculateEnrollmentFees(
            selectedFee.course_fee,
            selectedFee.registration_fee,
            selectedFee.duration,
            formData.paymentOption,
            formData.includeRegistrationFee,
            formData.discountType,
            formData.discountValue,
            formData.paymentOption === "upfront_installments"
              ? formData.customUpfrontAmount
              : undefined,
          );

          // Generate unique registration number
          const courseInfo = selectedFee.expand?.course_intake?.expand?.course;
          registrationNumber = await generateRegistrationNumber(
            selectedIntake.code,
            courseInfo?.code || "COURSE",
          );

          // Create enrollment with all fields populated
          const enrollmentRecord = await pb.collection("enrollments").create({
            student: studentId,
            registration_number: registrationNumber,
            course_intake: selectedFee.course_intake,
            course_intake_fees: formData.courseIntakeFeeId,
            payment_option: formData.paymentOption,
            registration_fee: formData.includeRegistrationFee,
            discount_type: formData.discountType || "",
            discount: feeCalc.discount_amount,
            total_course_fee: feeCalc.total_course_fee,
            fee_after_discount: feeCalc.fee_after_discount,
            upfront_payment: feeCalc.upfront_payment,
            installment_amount: feeCalc.installment_amount,
            installment_count: feeCalc.installment_count,
            months_remaining: feeCalc.months_remaining,
            enrollment_date: new Date().toISOString(),
            enrollement_status: "enrolled",
            certificate_status: "pending",
            remarks: formData.discountType
              ? `Enrolled with ${formData.discountType} discount of ${formData.discountValue}${formData.discountType === "percentage" ? "%" : " LKR"}`
              : "",
          });

          // Auto-create payment and installment records (non-blocking)
          try {
            // Registration fee — always a separate record
            if (
              formData.includeRegistrationFee &&
              feeCalc.registration_fee_amount > 0
            ) {
              await pb.collection("payments").create({
                reference_Id: generatePaymentReferenceId(
                  registrationNumber,
                  "registration",
                ),
                enrollment: enrollmentRecord.id,
                student: studentId,
                amount: feeCalc.registration_fee_amount,
                payment_type: "registration",
                verified: false,
                bank_name: "",
                remarks: "Registration fee - one-time enrollment charge",
              });
            }

            // Course fee upfront portion — separate record
            const coursePortion =
              feeCalc.upfront_payment -
              (formData.includeRegistrationFee
                ? feeCalc.registration_fee_amount
                : 0);
            if (coursePortion > 0) {
              const coursePayType =
                formData.paymentOption === "full_payment"
                  ? "full_payment"
                  : "upfront";
              await pb.collection("payments").create({
                reference_Id: generatePaymentReferenceId(
                  registrationNumber,
                  coursePayType,
                ),
                enrollment: enrollmentRecord.id,
                student: studentId,
                amount: coursePortion,
                payment_type: coursePayType,
                verified: false,
                bank_name: "",
                remarks: `Auto-generated ${coursePayType} payment - Awaiting student payment confirmation`,
              });
            }

            if (feeCalc.installment_count > 0) {
              const enrollmentDate = new Date();
              let firstDueDate = new Date(enrollmentDate);
              if (formData.paymentOption === "upfront_installments") {
                // First installment starts the month after the upfront payment
                firstDueDate.setMonth(firstDueDate.getMonth() + 1);
              }
              // installments_only: first installment due same month as enrollment
              for (let i = 1; i <= feeCalc.installment_count; i++) {
                const dueDate = new Date(firstDueDate);
                dueDate.setMonth(dueDate.getMonth() + (i - 1));
                const installmentId = generateInstallmentId(
                  registrationNumber,
                  i,
                );
                await pb.collection("installments").create({
                  installement_id: installmentId,
                  enrollment: enrollmentRecord.id,
                  due_date: dueDate.toISOString().split("T")[0],
                  amount: feeCalc.installment_amount,
                  status: "pending",
                  remarks: `Installment ${i} of ${feeCalc.installment_count}`,
                });
              }
            }
          } catch (paymentError: any) {
            console.error(
              "Payment/installment creation error:",
              paymentError?.message,
              paymentError?.data,
            );
          }

          toast.success(
            `Student ${enrollOnly ? "enrolled" : "registered"} successfully! Registration: ${registrationNumber}`,
          );
        }
      } else if (!enrollNow) {
        toast.success("Student registered successfully!");
      }
      onSuccess();
      onClose();
    } catch (error: any) {
      if (registrationNumber) {
        await rollbackRegistrationNumber(registrationNumber);
      }
      if (isSuperuserOnlyError(error)) {
        toast.error("You don't have permission to perform this action.");
      } else {
        toast.error(error.message || "Something went wrong");
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <ModernModal
      open={isOpen}
      onOpenChange={(v) => !v && onClose()}
      title={enrollOnly ? "Enroll Student" : "Register Student"}
      subtitle={
        enrollOnly
          ? `Add ${enrollOnly.name} to a new course`
          : "Complete the 4-stage registration process"
      }
      avatarChar={enrollOnly ? "E" : "S"}
      avatarColor={enrollOnly ? "bg-green-600" : "bg-indigo-600"}
    >
      <div className="space-y-5">
        {/* Step progress bar */}
        {!enrollOnly && (
          <div className="space-y-2">
            <div className="flex gap-1.5">
              {[1, 2, 3, 4].map((s) => (
                <div
                  key={s}
                  className={`h-1.5 flex-1 rounded-full transition-all duration-300 ${
                    stage >= s ? "bg-indigo-600" : "bg-gray-100"
                  }`}
                />
              ))}
            </div>
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">
              Step {stage} of 4 —{" "}
              {stage === 1
                ? "Identity"
                : stage === 2
                  ? "Contact"
                  : stage === 3
                    ? "Account"
                    : "Course & Payment"}
            </p>
          </div>
        )}

        {/* ── Stage 1: Identity ── */}
        {stage === 1 && (
          <div className="space-y-5 animate-in fade-in duration-300">
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-3 ml-1">
                  Full Name
                </label>
                <input
                  type="text"
                  value={formData.name}
                  required
                  onChange={(e) =>
                    setFormData({ ...formData, name: e.target.value })
                  }
                  placeholder="John Doe"
                  className="w-full px-5 py-4 bg-gray-50 border border-gray-100 rounded-2xl focus:outline-none focus:ring-2 focus:ring-indigo-500/20 font-bold transition-all text-gray-900"
                />
              </div>
              <div>
                <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-3 ml-1">
                  Initials
                </label>
                <input
                  type="text"
                  value={formData.nameinitials}
                  required
                  onChange={(e) =>
                    setFormData({ ...formData, nameinitials: e.target.value })
                  }
                  placeholder="J.D."
                  className="w-full px-5 py-4 bg-gray-50 border border-gray-100 rounded-2xl focus:outline-none focus:ring-2 focus:ring-indigo-500/20 font-bold transition-all text-gray-900"
                />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-3 ml-1">
                  Gender
                </label>
                <select
                  value={formData.gender}
                  required
                  onChange={(e) =>
                    setFormData({ ...formData, gender: e.target.value })
                  }
                  className="w-full px-5 py-4 bg-gray-50 border border-gray-100 rounded-2xl focus:outline-none focus:ring-2 focus:ring-indigo-500/20 font-bold transition-all text-gray-900 appearance-none"
                >
                  <option value="male">Male</option>
                  <option value="female">Female</option>
                </select>
              </div>
              <div>
                <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-3 ml-1">
                  Date of Birth
                </label>
                <input
                  type="date"
                  value={formData.dateOfBirth}
                  required
                  onChange={(e) =>
                    setFormData({ ...formData, dateOfBirth: e.target.value })
                  }
                  className="w-full px-5 py-4 bg-gray-50 border border-gray-100 rounded-2xl focus:outline-none focus:ring-2 focus:ring-indigo-500/20 font-bold transition-all text-gray-900"
                />
              </div>
            </div>

            <div>
              <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-3 ml-1">
                ID / Passport Number
              </label>
              <input
                type="text"
                value={formData.IdentificationDocument}
                required
                onChange={(e) =>
                  setFormData({
                    ...formData,
                    IdentificationDocument: e.target.value,
                  })
                }
                placeholder="NIC or Passport"
                className="w-full px-5 py-4 bg-gray-50 border border-gray-100 rounded-2xl focus:outline-none focus:ring-2 focus:ring-indigo-500/20 font-bold transition-all text-gray-900"
              />
            </div>

            <div className="pt-2 border-t border-gray-50">
              <p className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-4 ml-1">
                Guardian Details
              </p>
              <div className="space-y-4">
                <div>
                  <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-3 ml-1">
                    Guardian Name
                  </label>
                  <input
                    type="text"
                    value={formData.guardianName}
                    required
                    onChange={(e) =>
                      setFormData({ ...formData, guardianName: e.target.value })
                    }
                    placeholder="Guardian full name"
                    className="w-full px-5 py-4 bg-gray-50 border border-gray-100 rounded-2xl focus:outline-none focus:ring-2 focus:ring-indigo-500/20 font-bold transition-all text-gray-900"
                  />
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-3 ml-1">
                      Relationship
                    </label>
                    <select
                      value={formData.guardianRelationship}
                      required
                      onChange={(e) =>
                        setFormData({
                          ...formData,
                          guardianRelationship: e.target.value,
                        })
                      }
                      className="w-full px-5 py-4 bg-gray-50 border border-gray-100 rounded-2xl focus:outline-none focus:ring-2 focus:ring-indigo-500/20 font-bold transition-all text-gray-900 appearance-none"
                    >
                      <option value="">Select</option>
                      <option value="father">Father</option>
                      <option value="mother">Mother</option>
                      <option value="guardian">Guardian</option>
                    </select>
                  </div>
                  <div>
                    <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-3 ml-1">
                      Guardian Contact
                    </label>
                    <input
                      type="text"
                      value={formData.guardianContact}
                      required
                      onChange={(e) =>
                        setFormData({
                          ...formData,
                          guardianContact: e.target.value,
                        })
                      }
                      placeholder="Phone number"
                      className="w-full px-5 py-4 bg-gray-50 border border-gray-100 rounded-2xl focus:outline-none focus:ring-2 focus:ring-indigo-500/20 font-bold transition-all text-gray-900"
                    />
                  </div>
                </div>
              </div>
            </div>

            <div className="pt-2 border-t border-gray-50">
              <p className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-4 ml-1">
                Student Avatar
              </p>
              <div className="flex items-center gap-5">
                <div className="relative">
                  <div className="w-20 h-20 rounded-2xl bg-gray-50 border border-gray-100 flex items-center justify-center overflow-hidden">
                    {avatarPreview ? (
                      <div className="relative w-full h-full">
                        <Image
                          src={avatarPreview}
                          alt="Avatar Preview"
                          fill
                          className="object-cover"
                        />
                      </div>
                    ) : (
                      <Camera className="text-gray-300" size={28} />
                    )}
                  </div>
                  {avatarPreview && (
                    <button
                      onClick={() => {
                        setAvatarFile(null);
                        setAvatarPreview(null);
                      }}
                      className="absolute -top-2 -right-2 w-6 h-6 bg-red-500 text-white rounded-lg flex items-center justify-center shadow border-2 border-white"
                    >
                      <X size={12} />
                    </button>
                  )}
                </div>
                <label className="cursor-pointer flex items-center gap-2 px-5 py-3 bg-gray-50 border border-gray-100 hover:bg-gray-100 text-gray-700 rounded-2xl transition-all font-bold text-xs uppercase tracking-widest">
                  <Upload size={14} />
                  {avatarFile ? "Change Photo" : "Upload Photo"}
                  <input
                    type="file"
                    className="hidden"
                    accept="image/*"
                    onChange={handleAvatarChange}
                  />
                </label>
                <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">
                  JPG, PNG or GIF · Max 5MB
                </span>
              </div>
            </div>
          </div>
        )}

        {/* ── Stage 2: Contact ── */}
        {stage === 2 && (
          <div className="space-y-5 animate-in fade-in duration-300">
            <div>
              <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-3 ml-1">
                Email Address
              </label>
              <input
                type="email"
                value={formData.email}
                onChange={(e) =>
                  setFormData({ ...formData, email: e.target.value })
                }
                placeholder="john@example.com"
                className="w-full px-5 py-4 bg-gray-50 border border-gray-100 rounded-2xl focus:outline-none focus:ring-2 focus:ring-indigo-500/20 font-bold transition-all text-gray-900"
              />
            </div>

            <div className="grid grid-cols-3 gap-4">
              <div>
                <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-3 ml-1">
                  Country Code
                </label>
                <input
                  type="text"
                  value={formData.countryCode}
                  onChange={(e) =>
                    setFormData({ ...formData, countryCode: e.target.value })
                  }
                  placeholder="+94"
                  className="w-full px-5 py-4 bg-gray-50 border border-gray-100 rounded-2xl focus:outline-none focus:ring-2 focus:ring-indigo-500/20 font-bold transition-all text-gray-900"
                />
              </div>
              <div>
                <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-3 ml-1">
                  Mobile
                </label>
                <input
                  type="tel"
                  value={formData.mobile}
                  onChange={(e) =>
                    setFormData({ ...formData, mobile: e.target.value })
                  }
                  placeholder="77 XXX XXXX"
                  className="w-full px-5 py-4 bg-gray-50 border border-gray-100 rounded-2xl focus:outline-none focus:ring-2 focus:ring-indigo-500/20 font-bold transition-all text-gray-900"
                />
              </div>
              <div>
                <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-3 ml-1">
                  WhatsApp
                </label>
                <input
                  type="tel"
                  value={formData.whatsapp}
                  onChange={(e) =>
                    setFormData({ ...formData, whatsapp: e.target.value })
                  }
                  placeholder="77 XXX XXXX"
                  className="w-full px-5 py-4 bg-gray-50 border border-gray-100 rounded-2xl focus:outline-none focus:ring-2 focus:ring-indigo-500/20 font-bold transition-all text-gray-900"
                />
              </div>
            </div>

            <div className="grid grid-cols-3 gap-4">
              <div className="col-span-2">
                <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-3 ml-1">
                  Physical Address{" "}
                  <span className="text-gray-300 normal-case font-medium">
                    (optional)
                  </span>
                </label>
                <input
                  type="text"
                  value={formData.address}
                  onChange={(e) =>
                    setFormData({ ...formData, address: e.target.value })
                  }
                  placeholder="Street, Area"
                  className="w-full px-5 py-4 bg-gray-50 border border-gray-100 rounded-2xl focus:outline-none focus:ring-2 focus:ring-indigo-500/20 font-bold transition-all text-gray-900"
                />
              </div>
              <div>
                <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-3 ml-1">
                  City{" "}
                  <span className="text-gray-300 normal-case font-medium">
                    (optional)
                  </span>
                </label>
                <input
                  type="text"
                  value={formData.city}
                  onChange={(e) =>
                    setFormData({ ...formData, city: e.target.value })
                  }
                  placeholder="Colombo"
                  className="w-full px-5 py-4 bg-gray-50 border border-gray-100 rounded-2xl focus:outline-none focus:ring-2 focus:ring-indigo-500/20 font-bold transition-all text-gray-900"
                />
              </div>
            </div>
          </div>
        )}

        {/* ── Stage 3: Account ── */}
        {stage === 3 && (
          <div className="space-y-5 animate-in fade-in duration-300">
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-3 ml-1">
                  Student User ID
                </label>
                <div className="relative">
                  <input
                    type="text"
                    value={formData.userId}
                    readOnly
