                          {feeCalculation.registration_fee_amount > 0 && (
                            <div className="flex justify-between items-center text-xs">
                              <span className="font-bold text-gray-500 uppercase tracking-widest">
                                Registration Fee
                              </span>
                              <span className="font-black text-gray-900">
                                LKR{" "}
                                {feeCalculation.registration_fee_amount.toLocaleString()}
                              </span>
                            </div>
                          )}
                        </div>

                        <div className="pt-4 border-t-2 border-indigo-100">
                          {formData.paymentOption === "installments_only" ? (
                            <p className="text-[10px] font-bold text-orange-500 uppercase tracking-widest">
                              No upfront course payment — full fee splits into
                              installments
                            </p>
                          ) : (
                            <div className="flex justify-between items-center mb-2">
                              <span className="font-black text-sm text-indigo-700 uppercase tracking-widest">
                                {formData.paymentOption === "full_payment"
                                  ? "Full Payment"
                                  : "Upfront Payment"}
                              </span>
                              <span className="font-black text-2xl text-indigo-600">
                                LKR{" "}
                                {formData.paymentOption === "full_payment"
                                  ? feeCalculation.upfront_payment.toLocaleString()
                                  : formData.customUpfrontAmount.toLocaleString()}
                              </span>
                            </div>
                          )}
                        </div>

                        {feeCalculation.installment_count > 0 && (
                          <div className="pt-3 border-t border-gray-100">
                            <div className="flex justify-between items-center">
                              <span className="font-bold text-xs text-gray-700 uppercase tracking-widest">
                                {feeCalculation.installment_count} Monthly
                                Installments
                              </span>
                              <span className="font-black text-lg text-gray-900">
                                LKR{" "}
                                {feeCalculation.installment_amount.toLocaleString()}{" "}
                                <span className="text-xs font-bold text-gray-400">
                                  each
                                </span>
                              </span>
                            </div>
                            <p className="text-[10px] font-medium text-gray-400 mt-1 uppercase tracking-widest">
                              Total Installments: LKR{" "}
                              {(
                                feeCalculation.installment_amount *
                                feeCalculation.installment_count
                              ).toLocaleString()}
                            </p>
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                )}
              </>
            ) : (
              <div className="py-20 px-8 bg-indigo-50/30 rounded-[3rem] border-2 border-dashed border-indigo-100/50 text-center space-y-6 animate-in zoom-in-95 duration-500">
                <div className="w-20 h-20 bg-white rounded-[2rem] flex items-center justify-center text-indigo-600 mx-auto shadow-sm ring-8 ring-indigo-50/50">
                  <Check size={36} />
                </div>
                <div className="space-y-2">
                  <h3 className="text-xl font-black text-indigo-950 uppercase tracking-tight">
                    Ready for Pending Registration
                  </h3>
                  <p className="text-xs font-bold text-indigo-400/80 uppercase tracking-widest leading-relaxed">
                    The student will be added to your directory <br /> with a{" "}
                    <span className="text-indigo-600 font-extrabold">
                      Pending
                    </span>{" "}
                    Academic Status.
                  </p>
                </div>
              </div>
            )}
          </div>
        )}

        {/* ── Action Buttons ── */}
        <div className="flex flex-col gap-3 pt-6 border-t border-gray-50">
          {validationError && (
            <p className="text-[10px] font-black text-rose-500 uppercase tracking-widest text-center">
              {validationError}
            </p>
          )}
          <button
            type="button"
            disabled={loading}
            onClick={handlePrimaryAction}
            className="w-full py-4 bg-indigo-600 text-white rounded-2xl font-black text-sm shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all uppercase tracking-widest disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
          >
            {loading ? (
              <div className="h-5 w-5 border-2 border-white border-t-transparent rounded-full animate-spin" />
            ) : stage === 4 ? (
              <>
                <Check size={16} />
                {enrollNow ? "Complete Enrollment" : "Register Pending Student"}
              </>
            ) : (
              <>
                Continue
                <ChevronRight size={16} />
              </>
            )}
          </button>
          {stage > (enrollOnly ? 4 : 1) && (
            <button
              type="button"
              onClick={handleBack}
              disabled={loading}
              className="w-full py-2 font-bold text-xs text-gray-400 hover:text-gray-600 transition-colors uppercase tracking-widest disabled:opacity-50"
            >
              ← Back
            </button>
          )}
        </div>
      </div>
    </ModernModal>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import AdminStatsCard from "./AdminStatsCard";
import * as LucideIcons from "lucide-react";

interface StatItem {
  title: string;
  value: string | number;
  icon: React.ComponentType<any>; // icon component
  bgColor: string;
  iconColor: string;
  trend?: {
    value: string;
    isPositive: boolean;
  };
}

interface StatsCarouselProps {
  stats: StatItem[];
  children?: React.ReactNode;
}

export default function StatsCarousel({ stats, children }: StatsCarouselProps) {
  const [currentIndex, setCurrentIndex] = useState(0);

  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentIndex((prev) => (prev + 1) % stats.length);
    }, 4000);
    return () => clearInterval(interval);
  }, [stats.length]);

  return (
    <div className="mb-4">
      {/* Mobile/Tablet Carousel (< lg) */}
      <div className="lg:hidden">
        <div className="relative overflow-hidden rounded-[2rem] shadow-sm bg-white/50 border border-indigo-50/50">
          <div
            className="flex transition-all duration-700 ease-[cubic-bezier(0.23,1,0.32,1)]"
            style={{
              transform: `translateX(-${currentIndex * 100}%)`,
            }}
          >
            {stats.map((stat, index) => {
              const Icon = stat.icon;
              return (
                <div key={index} className="w-full flex-shrink-0 p-1">
                  <AdminStatsCard {...stat} icon={Icon} />
                </div>
              );
            })}
          </div>
        </div>
        {/* Carousel Indicators - Refined Premium Dots */}
        <div className="flex justify-center gap-3 mt-6">
          {stats.map((_, index) => (
            <button
              key={index}
              onClick={() => setCurrentIndex(index)}
              className={`h-1.5 rounded-full transition-all duration-500 ${
                currentIndex === index
                  ? "bg-indigo-600 w-8"
                  : "bg-indigo-100 w-3 hover:bg-indigo-200"
              }`}
              aria-label={`Go to slide ${index + 1}`}
            />
          ))}
        </div>
      </div>

      {/* Large Desktop Grid (>= lg) */}
      <div className="hidden lg:grid grid-cols-4 gap-6">
        {stats.map((stat, index) => (
          <div
            key={index}
            className="animate-in fade-in slide-in-from-bottom-4 duration-700"
            style={{ animationDelay: `${index * 100}ms` }}
          >
            <AdminStatsCard {...stat} />
          </div>
        ))}
        {children}
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState, useCallback } from "react";
import { Pencil, Eraser, Trash2, Undo2, X, Minus, Plus } from "lucide-react";

interface DrawEvent {
  type: "draw" | "clear" | "undo";
  x?: number;
  y?: number;
  prevX?: number;
  prevY?: number;
  color?: string;
  thickness?: number;
  tool?: string;
}

interface WhiteboardProps {
  isHost: boolean;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  incomingDrawEvents: any[];
  onDraw: (event: DrawEvent) => void;
  onClose: () => void;
}

const COLORS = [
  "#ffffff",
  "#ef4444",
  "#f97316",
  "#eab308",
  "#22c55e",
  "#3b82f6",
  "#8b5cf6",
  "#ec4899",
];

export default function Whiteboard({
  isHost,
  incomingDrawEvents,
  onDraw,
  onClose,
}: WhiteboardProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isDrawing, setIsDrawing] = useState(false);
  const [color, setColor] = useState("#ffffff");
  const [thickness, setThickness] = useState(3);
  const [tool, setTool] = useState<"pen" | "eraser">("pen");
  const lastPos = useRef<{ x: number; y: number } | null>(null);
  const historyRef = useRef<ImageData[]>([]);
  const processedEventsRef = useRef(0);

  // Helper to redraw a set of events
  const drawEvents = useCallback(
    (
      ctx: CanvasRenderingContext2D,
      canvas: HTMLCanvasElement,
      events: any[],
    ) => {
      for (const evt of events) {
        if (evt.type === "draw" && evt.prevX != null && evt.x != null) {
          ctx.beginPath();
          ctx.strokeStyle =
            evt.tool === "eraser" ? "#1a1a2e" : evt.color || "#ffffff";
          ctx.lineWidth = evt.thickness || 3;
          ctx.lineCap = "round";
          ctx.lineJoin = "round";
          ctx.moveTo(evt.prevX * canvas.width, evt.prevY * canvas.height);
          ctx.lineTo(evt.x * canvas.width, evt.y * canvas.height);
          ctx.stroke();
        } else if (evt.type === "clear") {
          ctx.fillStyle = "#1a1a2e";
          ctx.fillRect(0, 0, canvas.width, canvas.height);
        }
      }
    },
    [],
  );

  // Initialize canvas & handle resize
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const resize = () => {
      const rect = canvas.parentElement?.getBoundingClientRect();
      if (!rect) return;
      canvas.width = rect.width;
      canvas.height = rect.height;
      const ctx = canvas.getContext("2d");
      if (ctx) {
        ctx.fillStyle = "#1a1a2e";
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        // Redraw EVERYTHING because the canvas was cleared by resize
        drawEvents(ctx, canvas, incomingDrawEvents);
      }
    };
    resize();
    window.addEventListener("resize", resize);
    return () => window.removeEventListener("resize", resize);
  }, [incomingDrawEvents, drawEvents]);

  // Process ONLY incoming draw events incrementally
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const newEvents = incomingDrawEvents.slice(processedEventsRef.current);
    drawEvents(ctx, canvas, newEvents);
    processedEventsRef.current = incomingDrawEvents.length;
  }, [incomingDrawEvents, drawEvents]);

  const saveHistory = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    historyRef.current.push(
      ctx.getImageData(0, 0, canvas.width, canvas.height),
    );
    if (historyRef.current.length > 50) historyRef.current.shift();
  }, []);

  const getCanvasPos = (
    e: React.MouseEvent<HTMLCanvasElement>,
  ): { x: number; y: number } => {
    const canvas = canvasRef.current!;
    const rect = canvas.getBoundingClientRect();
    return {
      x: (e.clientX - rect.left) / canvas.width,
      y: (e.clientY - rect.top) / canvas.height,
    };
  };

  const handleMouseDown = (e: React.MouseEvent<HTMLCanvasElement>) => {
    if (!isHost) return;
    saveHistory();
    setIsDrawing(true);
    const pos = getCanvasPos(e);
    lastPos.current = pos;
  };

  const handleMouseMove = (e: React.MouseEvent<HTMLCanvasElement>) => {
    if (!isDrawing || !isHost) return;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx || !lastPos.current) return;

    const pos = getCanvasPos(e);
    const strokeColor = tool === "eraser" ? "#1a1a2e" : color;

    ctx.beginPath();
    ctx.strokeStyle = strokeColor;
    ctx.lineWidth = tool === "eraser" ? thickness * 4 : thickness;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.moveTo(
      lastPos.current.x * canvas.width,
      lastPos.current.y * canvas.height,
    );
    ctx.lineTo(pos.x * canvas.width, pos.y * canvas.height);
    ctx.stroke();

    // Broadcast the drawing event
    const drawEvt: DrawEvent = {
      type: "draw",
      x: pos.x,
      y: pos.y,
      prevX: lastPos.current.x,
      prevY: lastPos.current.y,
      color,
      thickness: tool === "eraser" ? thickness * 4 : thickness,
      tool,
    };
    onDraw(drawEvt);
    lastPos.current = pos;
  };

  const handleMouseUp = () => {
    setIsDrawing(false);
    lastPos.current = null;
  };

  const handleClear = () => {
    if (!isHost) return;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    saveHistory();
    ctx.fillStyle = "#1a1a2e";
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    onDraw({ type: "clear" });
  };

  const handleUndo = () => {
    if (!isHost) return;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    const prev = historyRef.current.pop();
    if (prev) {
      ctx.putImageData(prev, 0, 0);
    }
  };

  return (
    <div className="absolute inset-0 z-40 flex flex-col bg-gray-950/95 backdrop-blur-xl animate-in fade-in duration-200">
      {/* Toolbar */}
      <div className="flex items-center justify-between px-4 py-3 bg-black/40 border-b border-white/10">
        <div className="flex items-center gap-3">
          <div className="flex items-center gap-1 bg-white/5 rounded-xl p-1 border border-white/10">
            <Pencil size={14} className="ml-2 text-indigo-400" />
            <span className="text-[10px] font-black tracking-widest uppercase text-white/60 mx-1">
              Whiteboard
            </span>
          </div>

          {isHost && (
            <>
              {/* Tool Selector */}
              <div className="flex items-center bg-white/5 rounded-xl p-1 border border-white/10 gap-0.5">
                <button
                  onClick={() => setTool("pen")}
                  className={`p-2 rounded-lg transition-all ${tool === "pen" ? "bg-indigo-600 text-white shadow-lg" : "text-gray-400 hover:text-white hover:bg-white/10"}`}
                  title="Pen"
                >
                  <Pencil size={16} />
                </button>
                <button
                  onClick={() => setTool("eraser")}
                  className={`p-2 rounded-lg transition-all ${tool === "eraser" ? "bg-indigo-600 text-white shadow-lg" : "text-gray-400 hover:text-white hover:bg-white/10"}`}
                  title="Eraser"
                >
                  <Eraser size={16} />
                </button>
              </div>

              {/* Color Palette */}
              <div className="flex items-center gap-1 bg-white/5 rounded-xl p-1.5 border border-white/10">
                {COLORS.map((c) => (
                  <button
                    key={c}
                    onClick={() => setColor(c)}
                    className={`w-5 h-5 rounded-full transition-all hover:scale-125 ${color === c ? "ring-2 ring-white ring-offset-2 ring-offset-gray-950 scale-110" : ""}`}
                    style={{ backgroundColor: c }}
                  />
                ))}
              </div>

              {/* Thickness */}
              <div className="flex items-center gap-1 bg-white/5 rounded-xl p-1 border border-white/10">
                <button
                  onClick={() => setThickness(Math.max(1, thickness - 1))}
                  className="p-1.5 rounded-lg text-gray-400 hover:text-white hover:bg-white/10 transition-all"
                >
                  <Minus size={14} />
                </button>
                <span className="text-[10px] font-black text-white/60 w-4 text-center">
                  {thickness}
                </span>
                <button
                  onClick={() => setThickness(Math.min(20, thickness + 1))}
                  className="p-1.5 rounded-lg text-gray-400 hover:text-white hover:bg-white/10 transition-all"
                >
                  <Plus size={14} />
                </button>
              </div>

              {/* Undo / Clear */}
              <div className="flex items-center gap-0.5 bg-white/5 rounded-xl p-1 border border-white/10">
                <button
                  onClick={handleUndo}
                  className="p-2 rounded-lg text-gray-400 hover:text-white hover:bg-white/10 transition-all"
                  title="Undo"
                >
                  <Undo2 size={16} />
                </button>
                <button
                  onClick={handleClear}
                  className="p-2 rounded-lg text-red-400 hover:text-red-300 hover:bg-red-500/10 transition-all"
                  title="Clear all"
                >
                  <Trash2 size={16} />
                </button>
              </div>
            </>
          )}

          {!isHost && (
            <span className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">
              View Only
            </span>
          )}
        </div>

        <button
          onClick={onClose}
          className="p-2 rounded-lg text-gray-400 hover:text-white hover:bg-white/10 transition-all"
          title="Close whiteboard"
        >
          <X size={18} />
        </button>
      </div>

      {/* Canvas */}
      <div className="flex-1 relative overflow-hidden">
        <canvas
          ref={canvasRef}
          onMouseDown={handleMouseDown}
          onMouseMove={handleMouseMove}
          onMouseUp={handleMouseUp}
          onMouseLeave={handleMouseUp}
          className={`absolute inset-0 ${isHost ? (tool === "eraser" ? "cursor-cell" : "cursor-crosshair") : "cursor-default"}`}
        />
      </div>
    </div>
  );
}

