"use client";

import React, { useMemo, useState, useEffect } from "react";
import { AnimatePresence, motion } from "framer-motion";
import {
  CreditCard,
  FileText,
  CheckCircle,
  Download,
  Printer,
  X,
} from "lucide-react";
import { RaisePaymentModal } from "@/components/student/RaisePaymentModal";

// Types
type PaymentStatus = "Paid" | "Pending" | "Failed";

type PaymentDue = {
  amount: number;
  currency: string;
  dueDate: string;
  description?: string;
  course?: string;
};

type CourseInfo = {
  courseName: string;
  totalFee: number;
  currency: string;
};

type PaymentHistoryItem = {
  id: string;
  date: string;
  description: string;
  amount: number;
  currency: string;
  status: PaymentStatus;
  receiptUrl?: string;
  course?: string;
  reference_Id?: string;
};

interface StudentPaymentProps {
  selectedCourse?: string;
  installments?: any[];
  payments?: any[];
  enrolledCourses?: any[];
}

export default function StudentPayment({
  selectedCourse,
  installments = [],
  payments = [],
  enrolledCourses = [],
}: StudentPaymentProps) {
  // Find registration and upfront payments for the course
  // registrationPayments and upfrontPayments should be filtered from the mapped paymentFeed below
  const [showHistoryModal, setShowHistoryModal] = useState(false);
  const [showPayModal, setShowPayModal] = useState(false);
  const [activeCourse, setActiveCourse] = useState<string>("");
  const [showSuccess, setShowSuccess] = useState(false);

  // Course theme mapping
  const courseThemes: Record<
    string,
    { bg: string; text: string; border: string }
  > = {
    "Graphic Design": {
      bg: "bg-indigo-50",
      text: "text-indigo-600",
      border: "border-indigo-100",
    },
    "Web Development": {
      bg: "bg-emerald-50",
      text: "text-emerald-600",
      border: "border-emerald-100",
    },
    Exam: {
      bg: "bg-amber-50",
      text: "text-amber-600",
      border: "border-amber-100",
    },
    Library: {
      bg: "bg-rose-50",
      text: "text-rose-600",
      border: "border-rose-100",
    },
  };

  const getTheme = (name?: string) =>
    courseThemes[name || ""] || {
      bg: "bg-gray-50",
      text: "text-gray-500",
      border: "border-gray-100",
    };

  // Real data will be fetched from PocketBase via props
  const courseOptions = enrolledCourses.map((c) => c.name);

  const closePayModal = () => {
    setShowPayModal(false);
  };

  useEffect(() => {
    if (selectedCourse) {
      setActiveCourse(selectedCourse);
    } else if (courseOptions.length === 1 && !activeCourse) {
      setActiveCourse(courseOptions[0]);
    }
  }, [selectedCourse, courseOptions, activeCourse]);

  useEffect(() => {
    const handleOpenPay = (e: any) => {
      if (e.detail?.course) setActiveCourse(e.detail.course);
      setShowPayModal(true);
    };
    const handleOpenHistory = () => setShowHistoryModal(true);

    window.addEventListener("open-pay-modal", handleOpenPay as any);
    window.addEventListener("open-history-modal", handleOpenHistory as any);
    return () => {
      window.removeEventListener("open-pay-modal", handleOpenPay as any);
      window.removeEventListener(
        "open-history-modal",
        handleOpenHistory as any,
      );
    };
  }, []);

  // Group installments and payments by course
  const course = selectedCourse;
  const courseInstallments = installments.filter((i) =>
    enrolledCourses.find((c) => c.name === course && c.id === i.enrollment),
  );
  const coursePayments = payments.filter((p) =>
    enrolledCourses.find((c) => c.name === course && c.id === p.enrollment),
  );
  // Map installments to feed items
  const installmentFeed = courseInstallments.map((i) => ({
    id: i.id,
    date: i.due_date,
    description: i.remarks || "Installment Due",
    amount: i.amount,
    currency: "USD",
    status: i.status === "paid" ? "Paid" : "Pending",
    course,
    payment_type: i.payment_type || "installment", // Ensure payment_type exists
    reference_Id: undefined,
  }));
  // Map payments to feed items
  const paymentFeed = coursePayments.map((p) => ({
    id: p.id,
    date: p.date_paid || p.created || "",
    description: p.remarks || "Payment",
    amount: p.amount,
    currency: "USD",
    status: p.verified ? "Paid" : "Pending",
    course,
    payment_type: p.payment_type,
    reference_Id: p.reference_Id,
  }));

  // derive combined history from installments and payments feeds
  const history = useMemo(
    () => [...installmentFeed, ...paymentFeed],
    [installmentFeed, paymentFeed],
  );

  // Get current month/year
  const now = new Date();
  const currentMonth = now.getMonth();
  const currentYear = now.getFullYear();
  // Filter pending installments for current month
  const pendingThisMonth = installmentFeed.filter(
    (i) =>
      i.status === "Pending" &&
      new Date(i.date).getMonth() === currentMonth &&
      new Date(i.date).getFullYear() === currentYear,
  );

  // Calculate total balance for the selected course
  const totalBalance = useMemo(() => {
    // Sum all pending installment amounts for the selected course
    return installmentFeed
      .filter((i) => i.status === "Pending")
      .reduce((sum, i) => sum + i.amount, 0);
  }, [installmentFeed]);

  // prepare options for pay modal
  const paymentOptions = useMemo(() => {
    // start with due this month installments
    let opts = pendingThisMonth.map((i) => ({
      ...i,
      label: i.description,
    }));

    // additionally include any pending registration/upfront payments
    const extra = paymentFeed
      .filter(
        (p) =>
          p.status === "Pending" &&
          (p.payment_type === "registration" || p.payment_type === "upfront"),
      )
      .map((p) => ({
        id: p.id,
        date: p.date,
        description: p.description,
        amount: p.amount,
        currency: p.currency,
        status: p.status,
        course: p.course,
        payment_type: p.payment_type,
        reference_Id: p.reference_Id,
        label:
          p.payment_type === "registration"
            ? "Registration Fee"
            : "Upfront Fee",
      }));

    opts = [...opts, ...extra];

    if (opts.length > 0) return opts;

    // fallback option: full balance
    return [
      {
        id: "full",
        label: "Full Balance",
        amount: totalBalance,
        currency: "USD",
        status: "Pending",
        reference_Id: undefined,
      },
    ];
  }, [pendingThisMonth, totalBalance, paymentFeed]);
  // Find registration and upfront payments using payment_type field
  // Show registration and upfront payments for the selected course, regardless of status
  const registrationPayments = paymentFeed.filter(
    (p) => p.payment_type === "registration",
  );
  const upfrontPayments = paymentFeed.filter(
    (p) => p.payment_type === "upfront",
  );

  let filteredFeed;
  if (pendingThisMonth.length > 0) {
    filteredFeed = [
      ...pendingThisMonth,
      ...registrationPayments,
      ...upfrontPayments,
    ]
      .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())
      .slice(0, 3);
  } else {
    // Always show registration and upfront payments, plus up to 3 most recent verified payments
    const verifiedPayments = [
      ...registrationPayments,
      ...upfrontPayments,
      ...paymentFeed.filter(
        (p) =>
          p.status === "Paid" &&
          p.payment_type !== "registration" &&
          p.payment_type !== "upfront",
      ),
    ].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    filteredFeed = verifiedPayments.slice(0, 3);
  }

  const handleSubmitReceipt = async (data: {
    selectedInvoice: any;
    files: File[];
    remarks: string;
  }) => {
    await new Promise((r) => setTimeout(r, 1500));
    // TODO: Integrate with PocketBase payments API
    setShowPayModal(false);
    setShowSuccess(true);
    setTimeout(() => setShowSuccess(false), 3000);
  };

  const formatCurrency = (amount: number, currency: string) =>
    new Intl.NumberFormat("en-US", { style: "currency", currency }).format(
      amount,
    );

  return (
    <div className="w-full h-full flex flex-col">
      {/* Financial Timeline Ledger */}
      <div className="relative pl-12 space-y-12">
        {/* The Axis Line */}
        <div
          className="absolute left-6 top-2 bottom-2 w-0.5 bg-dashed bg-gray-100/50"
          style={{
            backgroundImage:
              "linear-gradient(to bottom, transparent, #E5E7EB 50%, transparent)",
            backgroundSize: "1px 12px",
          }}
        />

        {filteredFeed.map((item, idx) => {
          const theme = getTheme(item.course);
          const isPending = item.status === "Pending";
          const isPaid = item.status === "Paid";

          return (
            <motion.div
              key={item.id}
              initial={{ opacity: 0, x: -20 }}
              whileInView={{ opacity: 1, x: 0 }}
              viewport={{ once: true }}
              transition={{ delay: idx * 0.1 }}
              className="relative group"
            >
              {/* Milestone Node */}
              <div
                className={`absolute -left-[30px] top-4 w-5 h-5 rounded-full border-4 border-white shadow-lg transition-all duration-500 z-10 
                ${
                  isPaid
                    ? "bg-green-500 ring-4 ring-green-100"
                    : isPending
                      ? "bg-amber-500 ring-4 ring-amber-100"
                      : "bg-red-500 ring-4 ring-red-100"
                } 
                group-hover:scale-125`}
              />

              {/* Ledger Card */}
              <div className="bg-white rounded-[2rem] border border-gray-100 p-6 flex items-center justify-between transition-all duration-500 hover:shadow-2xl hover:shadow-indigo-100/30 hover:-translate-y-1 relative overflow-hidden group/card">
                {/* Subtle Background Pattern */}
                <div
                  className={`absolute top-0 right-0 w-24 h-24 ${theme.bg} rounded-full -mr-12 -mt-12 opacity-50 transition-transform duration-700 group-hover/card:scale-150`}
                />

                <div className="flex items-center gap-6 relative z-10">
                  <div
                    className={`w-14 h-14 rounded-2xl flex items-center justify-center transition-all duration-500 shadow-sm ${
                      isPaid
                        ? "bg-green-50 text-green-600"
                        : isPending
                          ? "bg-amber-50 text-amber-600"
                          : "bg-red-50 text-red-600"
                    }`}
                  >
                    <CreditCard size={24} />
                  </div>
                  <div>
                    <h4 className="font-black text-gray-900 text-lg tracking-tight group-hover/card:text-indigo-600 transition-colors">
                      {item.payment_type === "registration"
                        ? "Registration Fee"
                        : item.payment_type === "upfront"
                          ? "Upfront Fee"
                          : item.description}
                    </h4>
                    <div className="flex items-center gap-3 mt-1.5 text-[10px] font-black uppercase tracking-widest text-gray-400">
                      <span>{item.date}</span>
                      <span className="w-1.5 h-1.5 rounded-full bg-gray-200" />
                      <span className={`${theme.text}`}>
                        {item.course || "General"}
                      </span>
                      {item.reference_Id && (
                        <>
                          <span className="w-1.5 h-1.5 rounded-full bg-gray-200" />
                          <span className="text-gray-500">Ref: {item.reference_Id}</span>
                        </>
                      )}
                    </div>
                  </div>
                </div>

                <div className="text-right flex items-center gap-8 relative z-10">
                  <div className="hidden sm:block">
                    <div
                      className={`px-3 py-1 rounded-xl text-[9px] font-black uppercase tracking-widest border border-gray-100 bg-gray-50/50 flex items-center gap-2 ${
                        isPaid
                          ? "text-green-600 border-green-100"
                          : isPending
                            ? "text-amber-600 border-amber-100"
                            : "text-red-600 border-red-100"
                      }`}
                    >
                      <div
                        className={`w-1.5 h-1.5 rounded-full ${isPaid ? "bg-green-500" : isPending ? "bg-amber-500" : "bg-red-500"}`}
                      />
                      {item.status}
                    </div>
                  </div>
                  <p className="font-black text-2xl text-gray-900 tracking-tighter">
                    {formatCurrency(item.amount, item.currency)}
                  </p>
                </div>
              </div>
            </motion.div>
          );
        })}

        {filteredFeed.length === 0 && (
          <div className="flex flex-col items-center justify-center py-20 text-center bg-gray-50/50 rounded-[2.5rem] border border-dashed border-gray-200">
            <CreditCard className="text-gray-300 mb-4" size={32} />
            <p className="text-gray-500 font-bold uppercase tracking-widest text-xs">
              Timeline is currently empty
            </p>
          </div>
        )}
      </div>

      {/* Raise Payment Modal */}
      <RaisePaymentModal
        isOpen={showPayModal}
        onClose={closePayModal}
        activeCourse={activeCourse}
        registrationNumber={
          enrolledCourses.find((c) => c.name === activeCourse)
            ?.registration_number
        }
        paymentOptions={paymentOptions}
        onSubmit={handleSubmitReceipt}
        theme={getTheme(activeCourse)}
      />

      {/* Success Notification */}
      <AnimatePresence>
        {showSuccess && (
          <motion.div
            className="fixed top-12 left-1/2 -translate-x-1/2 z-[100] bg-white rounded-3xl shadow-2xl p-6 flex items-center gap-4 border border-green-100"
            initial={{ y: -100, opacity: 0 }}
            animate={{ y: 0, opacity: 1 }}
            exit={{ y: -100, opacity: 0 }}
          >
            <div className="w-12 h-12 rounded-2xl bg-green-50 text-green-600 flex items-center justify-center shadow-sm">
              <CheckCircle size={24} />
            </div>
            <div>
              <p className="font-black text-gray-900 uppercase tracking-tight">
                Receipt Uploaded
              </p>
              <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">
                Awaiting admin verification
              </p>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* History Modal */}
      <AnimatePresence>
        {showHistoryModal && (
          <PaymentHistoryModal
            onClose={() => setShowHistoryModal(false)}
            history={history}
            courseOptions={courseOptions}
            selectedCourse={selectedCourse}
          />
        )}
      </AnimatePresence>
    </div>
  );
}

// Sub-component: Financial History Modal
function PaymentHistoryModal({
  onClose,
  history,
  courseOptions,
  selectedCourse,
}: any) {
  const [filterCourse, setFilterCourse] = useState(selectedCourse || "");

  useEffect(() => {
    // Sync with selectedCourse if it changes externally
    if (selectedCourse) setFilterCourse(selectedCourse);
  }, [selectedCourse]);

  useEffect(() => {
    document.body.style.overflow = "hidden";
    return () => {
      document.body.style.overflow = "unset";
    };
  }, []);

  const formatCurrency = (amount: number, currency: string) =>
    new Intl.NumberFormat("en-US", { style: "currency", currency }).format(
      amount,
    );

  const mergedRows = useMemo(() => {
    // Show all verified payments (including registration/upfront) and pending
    // payments only if they fall in the current month/year
    const now = new Date();
    const currentMonth = now.getMonth();
    const currentYear = now.getFullYear();

    const allPayments = history.map((h: any) => ({ ...h, type: "Payment" }));
    return allPayments
      .filter((r: any) => {
        if (filterCourse && r.course !== filterCourse) return false;
        if (r.status === "Paid") return true;
        if (r.status === "Pending") {
          const d = new Date(r.date);
          return (
            d.getMonth() === currentMonth && d.getFullYear() === currentYear
          );
        }
        return false;
      })
      .sort(
        (a: { date: string }, b: { date: string }) =>
          new Date(b.date).getTime() - new Date(a.date).getTime(),
      );
  }, [history, filterCourse]);

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <motion.div
        className="absolute inset-0 bg-gray-900/60 backdrop-blur-sm"
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        onClick={onClose}
      />
      <motion.div
        className="relative bg-white rounded-[3rem] shadow-2xl w-full max-w-5xl max-h-[90vh] overflow-hidden flex flex-col"
        initial={{ scale: 0.95, opacity: 0, y: 20 }}
        animate={{ scale: 1, opacity: 1, y: 0 }}
        exit={{ scale: 0.95, opacity: 0, y: 20 }}
      >
        <div className="p-10 border-b border-gray-100 flex items-center justify-between bg-white relative z-10">
          <div>
            <h2 className="text-4xl font-black text-gray-900 tracking-tighter">
              Finance <span className="text-indigo-600">Sync</span>
            </h2>
            <p className="text-gray-400 text-[10px] font-black uppercase tracking-[0.2em] mt-2">
              Comprehensive Account Statement
            </p>
          </div>
          <div className="flex items-center gap-6">
            {!selectedCourse && (
              <select
                className="bg-gray-50 border-none rounded-2xl px-6 py-4 text-[10px] font-black uppercase tracking-widest text-gray-600 outline-none focus:ring-4 focus:ring-indigo-100 transition-all cursor-pointer"
                value={filterCourse}
                onChange={(e) => setFilterCourse(e.target.value)}
              >
                <option value="">All Streams</option>
                {courseOptions.map((c: string) => (
                  <option key={c} value={c}>
                    {c}
                  </option>
                ))}
              </select>
            )}
            <button
              onClick={onClose}
              className="w-14 h-14 rounded-2xl bg-gray-50 flex items-center justify-center text-gray-400 hover:bg-red-50 hover:text-red-500 transition-all"
            >
              <X size={28} />
            </button>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-10 space-y-4 bg-gray-50/30">
          {mergedRows.length > 0 ? (
            mergedRows.map((row: any) => (
              <div
                key={row.id}
                className="bg-white rounded-[2.5rem] p-8 border border-gray-100 flex items-center justify-between transition-all duration-500 hover:shadow-2xl hover:shadow-indigo-100 hover:-translate-y-1 group"
              >
                <div className="flex items-center gap-8">
                  <div
                    className={`w-16 h-16 rounded-[1.5rem] flex items-center justify-center font-black shadow-sm transition-all duration-500 ${
                      row.status === "Paid"
                        ? "bg-green-50 text-green-600 border border-green-100"
                        : row.status === "Pending"
                          ? "bg-amber-50 text-amber-600 border border-amber-100"
                          : row.status === "Outstanding"
                            ? "bg-red-50 text-red-600 border border-red-100"
                            : "bg-gray-50 text-gray-400"
                    }`}
                  >
                    {row.type === "Invoice" ? (
                      <FileText size={28} />
                    ) : (
                      <CheckCircle size={28} />
                    )}
                  </div>
                  <div>
                    <h4 className="font-black text-gray-900 text-xl tracking-tight transition-colors group-hover:text-indigo-600">
                      {row.payment_type === "registration"
                        ? "Registration Fee"
                        : row.payment_type === "upfront"
                          ? "Upfront Fee"
                          : row.description}
                    </h4>
                    <div className="flex items-center gap-4 mt-2 text-[10px] font-black uppercase tracking-[0.15em] text-gray-400">
                      <span>{row.date}</span>
                      <span className="w-2 h-2 rounded-full bg-gray-200" />
                      <span className="text-indigo-400">
                        {row.course || "System Fee"}
                      </span>
                      {row.reference_Id && (
                        <>
                          <span className="w-2 h-2 rounded-full bg-gray-200" />
                          <span className="text-gray-500">Ref: {row.reference_Id}</span>
                        </>
                      )}
                    </div>
                  </div>
                </div>

                <div className="text-right flex items-center gap-12">
                  <div>
                    <p className="font-black text-2xl text-gray-900 tracking-tighter">
                      {formatCurrency(row.amount, row.currency)}
                    </p>
                    <div
                      className={`mt-2 px-4 py-1.5 rounded-xl text-[9px] font-black uppercase tracking-widest border inline-flex items-center gap-2 ${
                        row.status === "Paid"
                          ? "bg-green-50 text-green-600 border-green-200"
                          : row.status === "Pending"
                            ? "bg-amber-50 text-amber-600 border-amber-200"
                            : "bg-red-50 text-red-600 border-red-200"
                      }`}
                    >
                      <div
                        className={`w-1.5 h-1.5 rounded-full ${row.status === "Paid" ? "bg-green-600" : row.status === "Pending" ? "bg-amber-600" : "bg-red-600"}`}
                      />
                      {row.status}
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    <button className="w-12 h-12 bg-gray-50 hover:bg-gray-100 text-gray-400 hover:text-indigo-600 rounded-2xl flex items-center justify-center transition-all">
                      <Printer size={20} />
                    </button>
                    <button className="w-12 h-12 bg-gray-50 hover:bg-gray-100 text-gray-400 hover:text-indigo-600 rounded-2xl flex items-center justify-center transition-all">
                      <Download size={20} />
                    </button>
                  </div>
                </div>
              </div>
            ))
          ) : (
            <div className="flex flex-col items-center justify-center py-40 bg-white rounded-[3rem] border border-dashed border-gray-100 opacity-60">
              <FileText className="text-gray-200 mb-6" size={64} />
              <p className="text-gray-400 font-black uppercase tracking-widest text-sm">
                No Financial Records Found
              </p>
            </div>
          )}
        </div>
      </motion.div>
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { AnimatePresence, motion } from "framer-motion";
import {
  X,
  Plus,
  ArrowRight,
  AlertCircle,
  CheckCircle,
  CreditCard,
} from "lucide-react";

interface PaymentOption {
  id: string;
  label: string;
  amount: number;
  currency: string;
  status: string;
  payment_type?: string;
  [key: string]: any;
}

interface RaisePaymentModalProps {
  isOpen: boolean;
  onClose: () => void;
  activeCourse: string;
  registrationNumber?: string;
  paymentOptions: PaymentOption[];
  onSubmit: (data: {
    selectedInvoice: PaymentOption;
    files: File[];
    remarks: string;
  }) => Promise<void>;
  theme: { bg: string; text: string; border: string };
}

const formatCurrency = (amount: number, currency: string) =>
  new Intl.NumberFormat("en-US", { style: "currency", currency }).format(amount);

export function RaisePaymentModal({
  isOpen,
  onClose,
  activeCourse,
  registrationNumber,
  paymentOptions,
  onSubmit,
  theme,
}: RaisePaymentModalProps) {
  const [modalStep, setModalStep] = useState(1);
  const [files, setFiles] = useState<File[]>([]);
  const [previews, setPreviews] = useState<string[]>([]);
  const [fileError, setFileError] = useState("");
  const [remarks, setRemarks] = useState("");
  const [processing, setProcessing] = useState(false);
  const [selectedInvoice, setSelectedInvoice] = useState<PaymentOption | null>(null);

  // Lock body scroll when open
  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = "hidden";
    } else {
      document.body.style.overflow = "unset";
    }
    return () => {
      document.body.style.overflow = "unset";
    };
  }, [isOpen]);

  const resetForm = () => {
    setFiles([]);
    setPreviews([]);
    setFileError("");
    setRemarks("");
    setSelectedInvoice(null);
    setModalStep(1);
  };

  const handleClose = () => {
    resetForm();
    onClose();
  };

  const onFilesSelected = (fileList: FileList | null) => {
    if (!fileList) return;
    const arr = Array.from(fileList);
    const urls = arr.map((f) => URL.createObjectURL(f));
    setFiles(arr);
    setPreviews(urls);
    setFileError("");
  };

  const handleSubmit = async () => {
    if (!selectedInvoice) {
      setFileError("Please choose an amount to pay.");
      return;
    }
    if (files.length === 0) {
      setFileError("Please upload at least one receipt image.");
      return;
    }
    setProcessing(true);
    try {
      await onSubmit({ selectedInvoice, files, remarks });
      handleClose();
    } finally {
      setProcessing(false);
    }
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <motion.div
          className="fixed inset-0 z-50 flex items-center justify-center bg-gray-900/60 backdrop-blur-sm p-4"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          onClick={handleClose}
        >
          <motion.div
            className="relative bg-white rounded-[3rem] shadow-2xl w-full max-w-5xl max-h-[90vh] overflow-hidden flex flex-col"
            onClick={(e) => e.stopPropagation()}
            initial={{ scale: 0.95, opacity: 0, y: 20 }}
            animate={{ scale: 1, opacity: 1, y: 0 }}
            exit={{ scale: 0.95, opacity: 0, y: 20 }}
          >
            {/* Header */}
            <div className="p-10 border-b border-gray-100 flex items-center justify-between bg-white relative z-10 flex-shrink-0">
              <div className="flex items-center gap-4">
                <div className="w-14 h-14 bg-indigo-600 rounded-2xl flex items-center justify-center text-white shadow-xl shadow-indigo-100 ring-4 ring-indigo-50">
                  <CreditCard size={28} />
                </div>
                <div>
                  <h2 className="text-4xl font-black text-gray-900 tracking-tighter">
                    Raise New <span className="text-indigo-600">Payment</span>
                  </h2>
                  <p className="text-gray-400 text-[10px] font-black uppercase tracking-[0.2em] mt-2">
                    Submit fee receipt for verification
                  </p>
                </div>
              </div>
              <button
                onClick={handleClose}
                className="w-14 h-14 rounded-2xl bg-gray-50 flex items-center justify-center text-gray-400 hover:bg-red-50 hover:text-red-500 transition-all"
              >
                <X size={28} />
              </button>
            </div>

            {/* Scrollable Body */}
            <div className="flex-1 overflow-y-auto p-10 space-y-8 bg-gray-50/30">
              {/* Course indicator */}
              <div
                className={`p-6 rounded-[2rem] border ${theme.bg} ${theme.border} flex items-center gap-4`}
              >
                <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${theme.bg} ${theme.text} font-black text-sm`}>
                  <CreditCard size={18} />
                </div>
                <div>
                  <div className="flex items-center gap-2 mb-1">
                    <p className="text-[10px] font-black uppercase tracking-widest text-gray-400">
                      Managing Payment For
                    </p>
                    {registrationNumber && (
                      <span className="px-2 py-0.5 rounded-md bg-gray-100/80 text-gray-500 text-[9px] font-black tracking-widest uppercase">
                        {registrationNumber}
                      </span>
                    )}
                  </div>
                  <h4 className="text-xl font-black text-gray-900 uppercase tracking-tight">
                    {activeCourse || "General Account"}
                  </h4>
                </div>
              </div>

              {!activeCourse ? (
                <div className="text-center py-20 bg-white rounded-[2rem] border border-dashed border-gray-200">
                  <AlertCircle className="mx-auto text-amber-500 mb-4" size={48} />
                  <p className="text-sm font-black text-gray-600 uppercase tracking-widest">
                    No course selected
                  </p>
                </div>
              ) : paymentOptions.length === 0 ? (
                /* Empty State: No Pending Payments */
                <div className="text-center py-24 bg-white rounded-[2rem] border border-gray-100 shadow-sm">
                  <div className="w-24 h-24 bg-green-50 rounded-[2rem] flex items-center justify-center mx-auto mb-6 shadow-inner ring-4 ring-green-50/50">
                    <CheckCircle className="text-green-500" size={48} />
                  </div>
                  <h3 className="text-2xl font-black text-gray-900 tracking-tight mb-2">
                    You're All Caught Up!
                  </h3>
                  <p className="text-sm font-bold text-gray-400 max-w-sm mx-auto leading-relaxed">
                    There are no pending invoices or outstanding payments required for this course at the moment.
                  </p>
                </div>
              ) : (
                <>
                  {/* Step 1: Select amount */}
                  {modalStep === 1 ? (
                    <div className="space-y-6">
                      <div className="space-y-4">
                        <label className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-gray-500 ml-1">
                          1. Select Outstanding Liability
                        </label>
                        <div className="flex flex-col space-y-3">
                          {paymentOptions.map((opt) => {
                            const isSelected = selectedInvoice?.id === opt.id;
                            return (
                              <label
                                key={opt.id}
                                onClick={() => setSelectedInvoice(opt)}
                                className={`group relative overflow-hidden flex items-center justify-between p-5 bg-white rounded-2xl border-2 cursor-pointer transition-all duration-200 hover:-translate-y-0.5 ${
                                  isSelected
                                    ? "border-indigo-500 shadow-lg shadow-indigo-100/50 bg-indigo-50/10"
                                    : "border-gray-100 hover:border-indigo-200 hover:shadow-md"
                                }`}
                              >
                                {isSelected && (
                                  <div className="absolute left-0 top-0 bottom-0 w-1 bg-indigo-500" />
                                )}
                                <div className="relative z-10 flex items-center gap-5">
                                  <div className={`w-5 h-5 rounded-full border-2 flex items-center justify-center transition-colors flex-shrink-0 ${isSelected ? "border-indigo-600 bg-indigo-600" : "border-gray-300 bg-white group-hover:border-indigo-300"}`}>
                                    {isSelected && <div className="w-2 h-2 bg-white rounded-full" />}
                                  </div>
                                  <div>
                                    <div className="flex items-center gap-3">
                                      <h5 className={`text-sm font-black uppercase tracking-tight ${isSelected ? "text-indigo-900" : "text-gray-900"}`}>
                                        {opt.label}
                                      </h5>
                                      <span className={`px-2 py-0.5 rounded-md text-[9px] font-black uppercase tracking-widest ${isSelected ? "bg-indigo-100 text-indigo-600" : "bg-gray-100 text-gray-500"}`}>
                                        {opt.payment_type === "registration" ? "Reg. Fee" : opt.payment_type === "upfront" ? "Upfront" : "Installment"}
                                      </span>
                                    </div>
                                    <p className="text-[10px] font-bold text-gray-400 mt-1 uppercase tracking-widest">
                                      Due: {opt.date ? new Date(opt.date).toLocaleDateString() : 'Now'}
                                    </p>
                                  </div>
                                </div>
                                <div className="relative z-10 text-right">
                                  <span className={`text-xl font-black tracking-tighter ${isSelected ? "text-indigo-600" : "text-gray-900"}`}>
                                    {formatCurrency(opt.amount, opt.currency)}
                                  </span>
                                </div>
                              </label>
                            );
                          })}
                        </div>
                      </div>
                    </div>
                  ) : (
                    /* Step 2: Upload & Remarks */
                    <div className="space-y-8 animate-in slide-in-from-right-4 duration-300">
                      {selectedInvoice && (
                        <div className="flex flex-col md:flex-row md:items-center justify-between p-6 bg-white rounded-[2rem] border-2 border-indigo-100 shadow-sm relative overflow-hidden">
                          <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-50/50 rounded-full -mr-16 -mt-16" />
                          <div className="relative z-10">
                            <p className="text-[10px] font-black uppercase tracking-widest text-indigo-400">
                              Selected Liability
                            </p>
                            <h4 className="text-xl font-black text-gray-900 tracking-tight mt-1 uppercase">
                              {selectedInvoice.label}
                            </h4>
                          </div>
                          <div className="relative z-10 text-left md:text-right mt-4 md:mt-0">
                            <p className="text-[10px] font-black uppercase tracking-widest text-gray-400">
                              Amount strictly required
                            </p>
                            <p className="text-3xl font-black text-indigo-600 tracking-tighter mt-1">
                              {formatCurrency(selectedInvoice.amount, selectedInvoice.currency)}
                            </p>
                          </div>
                        </div>
                      )}

                      <div className="space-y-4">
                        <label className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-gray-500 ml-1">
                          2. Upload Receipt(s)
                        </label>
                        <div className="relative group">
                          <input
                            type="file"
                            multiple
                            accept="image/*,.pdf"
                            className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-20"
                            onChange={(e) => onFilesSelected(e.target.files)}
                          />
                          <div className="w-full border-2 border-dashed border-gray-300 bg-gray-50/80 rounded-[2.5rem] p-16 text-center group-hover:border-indigo-400 group-hover:bg-indigo-50/30 transition-all duration-300">
                            <div className="w-16 h-16 bg-white rounded-full flex items-center justify-center mx-auto mb-6 shadow-sm group-hover:scale-110 transition-transform">
                              <Plus className="text-gray-400 group-hover:text-indigo-600 transition-colors" size={28} />
                            </div>
                            <p className="text-lg font-black text-gray-600 group-hover:text-indigo-600 transition-colors uppercase tracking-tight">
                              Drag & Drop Payment Slips Here
                            </p>
                            <p className="text-[10px] font-bold text-gray-400 mt-2 uppercase tracking-widest">
                              Supports JPG, PNG, PDF up to 10MB
                            </p>
                          </div>
                        </div>
                      </div>

                      {/* File Previews */}
                      {previews.length > 0 && (
                        <div className="space-y-3">
                           <label className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-gray-500 ml-1">
                            Attached Documents ({previews.length})
                          </label>
                          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                            {previews.map((src, i) => (
                              <div
                                key={i}
                                className="relative group/doc aspect-square rounded-[2rem] overflow-hidden border-2 border-gray-100 shadow-sm bg-gray-50 flex items-center justify-center"
                              >
                                <img src={src} className="w-full h-full object-cover" alt={`Receipt ${i + 1}`} />
                                <div className="absolute inset-0 bg-gray-900/60 opacity-0 group-hover/doc:opacity-100 transition-opacity flex items-center justify-center backdrop-blur-sm">
                                  <button
                                    onClick={(e) => {
                                      e.stopPropagation();
                                      const newFiles = [...files];
                                      const newPreviews = [...previews];
                                      newFiles.splice(i, 1);
                                      newPreviews.splice(i, 1);
                                      setFiles(newFiles);
                                      setPreviews(newPreviews);
                                    }}
                                    className="p-3 bg-red-500 text-white rounded-xl hover:bg-red-600 transition-colors shadow-lg"
                                  >
                                    <X size={20} />
                                  </button>
                                </div>
                              </div>
                            ))}
                          </div>
                        </div>
                      )}

                      <div className="space-y-4">
                        <label className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-gray-500 ml-1">
                          3. Additional Remarks <span className="text-gray-300">(Optional)</span>
                        </label>
                        <textarea
                          className="w-full bg-white border-2 border-gray-100 rounded-[2rem] p-6 text-sm font-bold focus:ring-4 focus:ring-indigo-100 focus:border-indigo-300 transition-all outline-none min-h-[120px] resize-none placeholder:text-gray-300"
                          placeholder="E.g., Transaction ID #XY12345, or date of transfer..."
                          value={remarks}
                          onChange={(e) => setRemarks(e.target.value)}
                        />
                      </div>

                      {fileError && (
                        <div className="flex items-center gap-3 p-4 bg-red-50 rounded-2xl border border-red-100 animate-in fade-in duration-300">
                          <AlertCircle size={20} className="text-red-500 flex-shrink-0" />
                          <p className="text-red-600 font-black text-xs uppercase tracking-widest">
                            {fileError}
                          </p>
                        </div>
                      )}
                    </div>
                  )}
                </>
              )}
            </div>

            {/* Footer Actions */}
            {activeCourse && paymentOptions.length > 0 && (
              <div className="p-8 border-t border-gray-100 bg-white flex items-center gap-4 flex-shrink-0">
                {modalStep === 2 ? (
                  <>
                    <button
                      className="flex-1 py-5 rounded-2xl bg-gray-50 text-gray-500 font-black text-[10px] tracking-widest hover:bg-gray-100 hover:text-gray-900 transition-all uppercase active:scale-95 border-2 border-transparent"
                      onClick={() => setModalStep(1)}
                    >
                      Back to Invoices
                    </button>
                    <button
                      className="flex-[2] py-5 rounded-2xl bg-indigo-600 text-white font-black text-[10px] tracking-widest shadow-xl shadow-indigo-200 hover:bg-indigo-700 transition-all uppercase active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2 border-2 border-indigo-600 disabled:border-transparent"
                      disabled={processing || files.length === 0}
                      onClick={handleSubmit}
                    >
                      {processing ? (
                        <>
                          <span className="w-5 h-5 border-4 border-white/20 border-t-white rounded-full animate-spin" />
                          Uploading Verification...
                        </>
                      ) : (
                        <>
                          <CheckCircle size={18} />
                          Confirm & Submit Payment
                        </>
                      )}
                    </button>
                  </>
                ) : (
                  <>
                    <button
                      className="flex-1 py-5 rounded-2xl bg-gray-50 text-gray-500 font-black text-[10px] tracking-widest hover:bg-gray-100 hover:text-gray-900 transition-all uppercase active:scale-95 border-2 border-transparent"
                      onClick={handleClose}
                    >
                      Cancel
                    </button>
                    <button
                      className="flex-[2] py-5 rounded-2xl bg-indigo-600 text-white font-black text-[10px] tracking-widest shadow-xl shadow-indigo-200 hover:bg-indigo-700 transition-all uppercase active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2 border-2 border-indigo-600 disabled:border-transparent"
                      disabled={!selectedInvoice}
                      onClick={() => setModalStep(2)}
                    >
                      Proceed to Payment
                      <ArrowRight size={18} />
                    </button>
                  </>
                )}
              </div>
            )}

            {/* Alt Footer for Empty State */}
            {activeCourse && paymentOptions.length === 0 && (
              <div className="p-8 border-t border-gray-100 bg-white flex items-center justify-center flex-shrink-0">
                 <button
                    className="py-5 px-12 rounded-2xl bg-gray-900 text-white font-black text-[10px] tracking-widest shadow-xl shadow-gray-200 hover:bg-gray-800 transition-all uppercase active:scale-95"
                    onClick={handleClose}
                  >
                    Close Window
                  </button>
              </div>
            )}
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

"use client";

import React from "react";
import {
  LayoutDashboard,
  BookOpen,
  CalendarDays,
  CreditCard,
  User,
  LogOut,
  ChevronRight,
  Menu,
} from "lucide-react";
import { RouteLink } from "@/components/ui/route-link";
import { useRouter } from "next/navigation";
import { usePathname } from "next/navigation";
import { logout } from "@/lib/pocketbase";

const menuItems = [
  {
    id: "dashboard",
    label: "DASHBOARD",
    icon: LayoutDashboard,
    href: "/dashboard/student",
  },
  {
    id: "courses",
    label: "MY COURSES",
    icon: BookOpen,
    href: "/dashboard/student/courses",
  },

  {
    id: "payments",
    label: "PAYMENTS",
    icon: CreditCard,
    href: "/dashboard/student/payments",
  },
  {
    id: "profile",
    label: "PROFILE",
    icon: User,
    href: "/dashboard/student/profile",
  },
];

export default function StudentSidebar({
  studentName = "Student",
  isSidebarOpen,
  setIsSidebarOpen,
}: {
  studentName?: string;
  isSidebarOpen?: boolean;
  setIsSidebarOpen?: (v: boolean) => void;
}) {
  const [profileOpen, setProfileOpen] = React.useState(false);
  const pathname = usePathname();
  const router = useRouter();

  // Determine active tab based on pathname
  const activeTab =
    menuItems.find((item) =>
      item.href === "/dashboard/student"
        ? pathname === item.href
        : pathname?.startsWith(item.href),
    )?.id || "dashboard";

  const handleLogout = async () => {
    logout();
    router.push("/login");
  };

  return (
    <>
      {isSidebarOpen && (
        <div
          className="fixed inset-0 bg-gray-950/20 backdrop-blur-md z-40 lg:hidden"
          onClick={() => setIsSidebarOpen?.(false)}
        />
      )}
      <aside
        className={`fixed top-0 left-0 h-full bg-white border-r border-gray-100 z-50 transition-all duration-500 flex flex-col ${
          isSidebarOpen ? "translate-x-0" : "-translate-x-full"
        } lg:translate-x-0 w-64 shadow-2xl shadow-indigo-900/[0.02]`}
      >
        {/* Logo */}
        <div className="px-8 py-12 flex flex-col justify-center gap-2 group cursor-default">
          <h2 className="text-2xl font-black tracking-tighter text-gray-900 flex items-center gap-1.5">
            <span className="group-hover:text-indigo-600 transition-colors duration-500">
              ACADE
            </span>
            <span className="text-indigo-600 group-hover:text-gray-900 transition-colors duration-500">
              MIX
            </span>
            <span className="w-2 h-2 rounded-full bg-indigo-600 group-hover:scale-150 transition-transform duration-500" />
          </h2>
          <div className="flex items-center gap-1">
            <div className="h-0.5 w-8 bg-indigo-600 rounded-full" />
            <div className="h-0.5 w-2 bg-indigo-200 rounded-full group-hover:w-12 transition-all duration-700" />
          </div>
        </div>

        {/* Navigation */}
        <nav className="flex-1 overflow-y-auto px-4 py-2 custom-scrollbar">
          <div className="px-4 mb-4">
            <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">
              MENU
            </span>
          </div>
          <ul className="space-y-1.5">
            {menuItems.map((item) => {
              const IconComponent = item.icon;
              const isActive = activeTab === item.id;
              return (
                <li key={item.id}>
                  <RouteLink
                    href={item.href}
                    onClick={() => setIsSidebarOpen?.(false)}
                    className={`w-full flex items-center gap-3 px-5 py-4 rounded-[1.25rem] transition-all duration-300 group ${
                      isActive
                        ? "bg-indigo-600 text-white shadow-xl shadow-indigo-100"
                        : "text-gray-500 hover:bg-indigo-50 hover:text-indigo-600"
                    }`}
                  >
                    <IconComponent
                      size={18}
                      strokeWidth={isActive ? 2.5 : 2}
                      className={`${isActive ? "scale-110" : "group-hover:scale-110"} transition-transform duration-300`}
                    />
                    <span
                      className={`text-[11px] font-black uppercase tracking-widest ${isActive ? "opacity-100" : "opacity-80 group-hover:opacity-100"}`}
                    >
                      {item.label}
                    </span>
                    {isActive && (
                      <div className="ml-auto w-1.5 h-1.5 rounded-full bg-white animate-pulse" />
                    )}
                  </RouteLink>
                </li>
              );
            })}
          </ul>
        </nav>

        {/* Profile Dropdown */}
        <div className="p-4 border-t border-gray-50">
          <div className="relative">
            <button
              onClick={() => setProfileOpen((v) => !v)}
              className="w-full flex items-center gap-3 px-4 py-3 rounded-2xl bg-gray-50 hover:bg-white hover:shadow-lg transition-all duration-300 group border border-transparent hover:border-indigo-100"
            >
              <div className="h-10 w-10 rounded-xl bg-indigo-600 flex items-center justify-center text-white font-black text-sm shadow-lg shadow-indigo-100 group-hover:scale-110 transition-transform">
                {studentName.charAt(0).toUpperCase()}
              </div>
              <div className="flex flex-col flex-1 text-left overflow-hidden">
                <span className="font-black text-[10px] text-gray-400 uppercase tracking-widest leading-none mb-1">
                  Student
                </span>
                <span className="font-bold text-sm text-gray-900 truncate">
                  {studentName}
                </span>
              </div>
              <ChevronRight
                size={14}
                className={`text-gray-300 transition-transform duration-300 ${profileOpen ? "rotate-90" : ""}`}
              />
            </button>
            {profileOpen && (
              <div className="absolute bottom-full left-0 right-0 mb-4 bg-white border border-gray-100 rounded-[2rem] shadow-2xl p-2 z-[60] animate-in fade-in slide-in-from-bottom-2 duration-300">
                <RouteLink
                  href="/dashboard/student/profile"
                  onClick={() => setProfileOpen(false)}
                  className="flex items-center gap-3 w-full text-left px-5 py-3 text-xs font-black text-gray-600 hover:bg-indigo-50 hover:text-indigo-600 rounded-2xl transition-all uppercase tracking-widest"
                >
                  <User size={14} />
                  VIEW PROFILE
                </RouteLink>
                <button
                  onClick={handleLogout}
                  className="flex items-center gap-3 w-full text-left px-5 py-3 text-xs font-black text-red-500 hover:bg-red-50 rounded-2xl transition-all uppercase tracking-widest mt-1"
                >
                  <LogOut size={14} />
                  LOG OUT
                </button>
              </div>
            )}
          </div>
        </div>
      </aside>
    </>
  );
}

