"use client";

import { useState, useEffect, useRef, useCallback } from "react";
import { GaleneClient, createGaleneClient } from "@/lib/galene";
import { toast } from "sonner";

export interface RemoteStream {
  id: string;
  stream: MediaStream;
  label?: string;
  username?: string;
  videoMuted?: boolean;
}

export interface ChatMessage {
  id: string;
  username: string;
  value: string;
  time?: number;
}

export interface Participant {
  id: string;
  username: string;
  permissions: string[];
  kind: string;
}

export interface InClassNotification {
  message: string;
  icon: string;
  type: "error" | "success" | "info" | "warning";
}

export interface UseGaleneReturn {
  connected: boolean;
  localStream: MediaStream | null;
  remoteStreams: RemoteStream[];
  error: string | null;
  connecting: boolean;
  chatMessages: ChatMessage[];
  permissions: string[];
  participants: Participant[];
  isScreenSharing: boolean;
  screenShareStream: MediaStream | null;
  connect: (group: string, username: string, password: string) => Promise<void>;
  disconnect: () => void;
  sendChat: (message: string) => void;
  toggleAudio: () => void;
  toggleVideo: () => void;
  shareScreen: () => Promise<void>;
  stopScreenShare: () => void;
  kickUser: (userId: string) => void;
  audioMuted: boolean;
  videoMuted: boolean;
  // New capabilities
  muteUser: (userId: string) => void;
  disableUserVideo: (userId: string) => void;
  makeHost: (userId: string) => void;
  removeHost: (userId: string) => void;
  raiseHand: () => void;
  lowerHand: () => void;
  raisedHands: Set<string>;
  whiteboardEvents: any[];
  whiteboardActive: boolean;
  sendUserMessage: (kind: string, dest?: string, value?: string) => void;
  ownId: string;
  inClassNotification: InClassNotification | null;
  clearNotification: () => void;
}

export function useGalene(): UseGaleneReturn {
  const clientRef = useRef<GaleneClient | null>(null);
  const [connected, setConnected] = useState(false);
  const [connecting, setConnecting] = useState(false);
  const [localStream, setLocalStream] = useState<MediaStream | null>(null);
  const [remoteStreams, setRemoteStreams] = useState<RemoteStream[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [chatMessages, setChatMessages] = useState<ChatMessage[]>([]);
  const [permissions, setPermissions] = useState<string[]>([]);
  const [participants, setParticipants] = useState<Participant[]>([]);
  const [audioMuted, setAudioMuted] = useState(false);
  const [videoMuted, setVideoMuted] = useState(false);
  const [isScreenSharing, setIsScreenSharing] = useState(false);
  const [screenShareStream, setScreenShareStream] =
    useState<MediaStream | null>(null);
  const [ownId, setOwnId] = useState<string>("");
  // New state for custom in-class notifications
  const [inClassNotification, setInClassNotification] =
    useState<InClassNotification | null>(null);
  const notificationTimeoutRef = useRef<NodeJS.Timeout | null>(null);

  const clearNotification = useCallback(() => {
    setInClassNotification(null);
    if (notificationTimeoutRef.current) {
      clearTimeout(notificationTimeoutRef.current);
    }
  }, []);

  const triggerNotification = useCallback(
    (
      message: string,
      icon: string,
      type: "error" | "success" | "info" | "warning",
    ) => {
      setInClassNotification({ message, icon, type });
      if (notificationTimeoutRef.current) {
        clearTimeout(notificationTimeoutRef.current);
      }
      notificationTimeoutRef.current = setTimeout(() => {
        setInClassNotification(null);
      }, 5000);
    },
    [],
  );

  // New state for hand raise and whiteboard events
  const [raisedHands, setRaisedHands] = useState<Set<string>>(new Set());
  // Initialize whiteboard state from sessionStorage if it exists
  const [whiteboardEvents, setWhiteboardEvents] = useState<any[]>(() => {
    if (typeof window !== "undefined") {
      const saved = sessionStorage.getItem("galene-wb-events");
      if (saved) {
        try {
          return JSON.parse(saved);
        } catch (e) {}
      }
    }
    return [];
  });

  const [whiteboardActive, setWhiteboardActive] = useState(() => {
    if (typeof window !== "undefined") {
      return sessionStorage.getItem("galene-wb-active") === "true";
    }
    return false;
  });

  // Save whiteboard changes to sessionStorage
  useEffect(() => {
    sessionStorage.setItem(
      "galene-wb-events",
      JSON.stringify(whiteboardEvents),
    );
  }, [whiteboardEvents]);

  useEffect(() => {
    sessionStorage.setItem("galene-wb-active", String(whiteboardActive));
  }, [whiteboardActive]);

  // Refs for callbacks
  const localStreamRef = useRef<MediaStream | null>(null);
  const participantsRef = useRef<Participant[]>([]);
  const permissionsRef = useRef<string[]>([]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (clientRef.current) {
        clientRef.current.disconnect();
        clientRef.current = null;
      }
    };
  }, []);

  // Generic wrapper to send user messages
  const sendUserMessage = useCallback(
    (kind: string, dest: string = "", value: string = "") => {
      if (clientRef.current) {
        clientRef.current.sendUserMessage(kind, dest, value);
      }
    },
    [],
  );

  const connect = useCallback(
    async (group: string, username: string, password: string) => {
      setConnecting(true);
      setError(null);
      // Reset ownId before new connection
      setOwnId("");

      try {
        const stream = await navigator.mediaDevices.getUserMedia({
          audio: true,
          video: {
            width: { ideal: 1280 },
            height: { ideal: 720 },
            frameRate: { ideal: 30 },
          },
        });

        // Restore muted state from sessionStorage instantly
        const savedAudioMuted =
          sessionStorage.getItem("galene-audio-muted") === "true";
        const savedVideoMuted =
          sessionStorage.getItem("galene-video-muted") === "true";

        stream
          .getAudioTracks()
          .forEach((track) => (track.enabled = !savedAudioMuted));
        stream
          .getVideoTracks()
          .forEach((track) => (track.enabled = !savedVideoMuted));

        setAudioMuted(savedAudioMuted);
        setVideoMuted(savedVideoMuted);

        setLocalStream(stream);

        const client = createGaleneClient();
        clientRef.current = client;
        // Store our own client ID for reference (used for mute, hand raise, etc.)
        setOwnId(client.id);
        localStreamRef.current = stream;

        // Connection events
        client.on("connected", (perms: string[]) => {
          setConnected(true);
          setConnecting(false);
          setPermissions(perms || []);
          permissionsRef.current = perms || [];
        });

        client.on("disconnected", (code: number, reason: string) => {
          console.warn(
            `[useGalene] Disconnected. Code: ${code}, Reason: ${reason}`,
          );
          setConnected(false);
          setConnecting(false);
        });

        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        client.on("error", (err: Error & { message?: string }) => {
          console.error("[useGalene] Error:", err);
          setError(err?.message || "Connection error");
          setConnecting(false);
        });

        // Remote streams
        client.on(
          "remoteStream",
          (data: {
            id: string;
            stream: MediaStream;
            label?: string;
            username?: string;
          }) => {
            const hasVideo = data.stream
              .getVideoTracks()
              .some((t) => t.enabled);

            setRemoteStreams((prev) => {
              const existing = prev.findIndex((s) => s.id === data.id);
              if (existing >= 0) {
                const updated = [...prev];
                updated[existing] = { ...data, videoMuted: !hasVideo };
                return updated;
              }
              return [...prev, { ...data, videoMuted: !hasVideo }];
            });
          },
        );

        client.on("remoteStreamRemoved", (data: { id: string }) => {
          setRemoteStreams((prev) => prev.filter((s) => s.id !== data.id));
        });

        // Listen for stream state changes (e.g. video muted/unmuted)
        client.on("streamState", (id: string, stream: MediaStream) => {
          const hasVideo = stream.getVideoTracks().some((t) => t.enabled);
          setRemoteStreams((prev) => {
            const existing = prev.findIndex((s) => s.id === id);
            if (existing >= 0) {
              if (prev[existing].videoMuted === !hasVideo) {
                return prev; // Ignore rapid events if truth value hasn't changed
              }
              const updated = [...prev];
              updated[existing] = {
                ...updated[existing],
                videoMuted: !hasVideo,
              };
              return updated;
            }
            return prev;
          });
        });

        // Chat
        client.on("chat", (msg: ChatMessage) => {
          setChatMessages((prev) => [...prev, msg]);
        });

        // Participants — filter out self from participants list, but sync permissions
        client.on("user", (user: Participant) => {
          if (user.id === client.id) {
            if (user.permissions) {
              setPermissions((prev) => {
                const prevStr = JSON.stringify(prev);
                const currStr = JSON.stringify(user.permissions);
                if (prevStr !== currStr) {
                  permissionsRef.current = user.permissions!;
                  return user.permissions!;
                }
                return prev;
              });
            }
            return;
          }

          setParticipants((prev) => {
            let next;
            if (user.kind === "delete") {
              next = prev.filter((p) => p.id !== user.id);
            } else {
              const existing = prev.findIndex((p) => p.id === user.id);
              if (existing >= 0) {
                const prevUser = prev[existing];
                // Check if meaningful fields changed. Ignore volume/VAD spam to prevent critical lag.
                if (
                  prevUser.username === user.username &&
                  JSON.stringify(prevUser.permissions) ===
                    JSON.stringify(user.permissions)
                ) {
                  return prev;
                }

                const updated = [...prev];
                updated[existing] = { ...prev[existing], ...user };
                next = updated;
              } else {
                next = [...prev, user];
              }
            }
            participantsRef.current = next;
            return next;
          });
        });

        // Listen for generic user messages (whiteboard, mute, hand raise)
        client.on("usermessage", (msg: { kind: string; dest: string; value: string; source: string }) => {
          const { kind, dest, value } = msg;
          // Remote mute
          if (kind === "remote-mute" && dest === client.id) {
            // Host requested mute of this client
            const ls = localStreamRef.current;
            if (ls) {
              ls.getAudioTracks().forEach((track) => {
                track.enabled = false;
              });
              setAudioMuted(true);
              triggerNotification(
                "The host has muted your microphone.",
                "🔇",
                "error",
              );
            }
          }
          // Remote video off
          if (kind === "remote-video-off" && dest === client.id) {
            const ls = localStreamRef.current;
            if (ls) {
              ls.getVideoTracks().forEach((track) => {
                track.enabled = false;
              });
              setVideoMuted(true);
              triggerNotification(
                "The host has disabled your camera.",
                "📷",
                "error",
              );
            }
          }
          // Promote/Demote Host
          if (kind === "promote-host" && dest === client.id) {
            triggerNotification(
              "You have been promoted to Host.",
              "👑",
              "success",
            );
          }
          if (kind === "demote-host" && dest === client.id) {
            triggerNotification(
              "Your Host privileges have been removed.",
              "ℹ️",
              "info",
            );
            clientRef.current?.stopScreenShare();
          }
          // Hand raise
          if (kind === "hand-raise") {
            const userId = msg.source; // source is the user who raised hand
            setRaisedHands((prev) => {
              const newSet = new Set(prev);
              if (value === "up") {
                newSet.add(userId);
                // Trigger notification for hand raise
                const user = participantsRef.current.find(
                  (p) => p.id === userId,
                );
                if (user) {
                  triggerNotification(
                    `${user.username} raised their hand`,
                    "✋",
                    "info",
                  );
                }
              } else if (value === "down") {
                newSet.delete(userId);
              }
              return newSet;
            });
          }
          // Whiteboard events
          if (kind === "whiteboard") {
            try {
              const data = JSON.parse(value);
              setWhiteboardEvents((prev) => [...prev, data]);
            } catch (e) {
              console.warn("Failed to parse whiteboard event", e);
            }
          }
          if (kind === "whiteboard-toggle") {
            setWhiteboardActive(value === "true");
          }
          // New: Handle requests for full sync (for late joiners / reloads)
          if (kind === "REQUEST_WHITEBOARD_SYNC") {
            // If we are host, send back our full history
            if (permissionsRef.current.includes("op")) {
              setWhiteboardEvents((currentEvents) => {
                const isActive =
                  sessionStorage.getItem("galene-wb-active") === "true";
                sendUserMessage(
                  "WHITEBOARD_SYNC",
                  msg.source,
                  JSON.stringify({
                    events: currentEvents,
                    active: isActive,
                  }),
                );
                return currentEvents;
              });
            }
          }
          // New: Handle receiving full sync history
          if (kind === "WHITEBOARD_SYNC") {
            try {
              const data = JSON.parse(value || "{}");
              if (data.events) {
                setWhiteboardEvents(data.events);
              }
              if (typeof data.active === "boolean") {
                setWhiteboardActive(data.active);
              }
            } catch (e) {
              console.error("Error parsing whiteboard sync:", e);
            }
          }
        });

        // Screen share events
        client.on(
          "screenShareStarted",
          (data: { id: string; stream: MediaStream }) => {
            setIsScreenSharing(true);
            setScreenShareStream(data.stream);
          },
        );

        client.on("screenShareStopped", () => {
          setIsScreenSharing(false);
          setScreenShareStream(null);
        });

        // Connect and publish
        await client.connect(group, username, password);
        await client.publishStream(stream, "camera");
      } catch (err: unknown) {
        const message =
          err instanceof Error
            ? err.message
            : "Failed to connect to virtual classroom";
        setError(message);
        setConnecting(false);
        console.error("[useGalene] Connection error:", err);
      }
    },
    [],
  );

  const disconnect = useCallback(() => {
    if (clientRef.current) {
      clientRef.current.disconnect();
      clientRef.current = null;
    }
    // Clear transient UI states
    setRaisedHands(new Set());
    setWhiteboardEvents([]);
    setWhiteboardActive(false);
    setOwnId("");
    if (localStreamRef.current) {
      localStreamRef.current.getTracks().forEach((t) => t.stop());
      localStreamRef.current = null;
    }
    setLocalStream(null);
    setConnected(false);
    setRemoteStreams([]);
    setPermissions([]);
    setParticipants([]);
    setAudioMuted(false);
    setVideoMuted(false);
    setIsScreenSharing(false);
    setScreenShareStream(null);
  }, []);

  const sendChat = useCallback((message: string) => {
    if (clientRef.current) {
      clientRef.current.sendChat(message);
    }
  }, []);


  // Host-only mute user (remote mute)
  const muteUser = useCallback(
    (userId: string) => {
      // Only send if we have op permission (host)
      if (permissions.includes("op")) {
        sendUserMessage("remote-mute", userId);
      }
    },
    [permissions, sendUserMessage],
  );

  // Hand raise actions for current user
  const raiseHand = useCallback(() => {
    sendUserMessage("hand-raise", "", "up");
  }, [sendUserMessage]);

  const lowerHand = useCallback(() => {
    sendUserMessage("hand-raise", "", "down");
  }, [sendUserMessage]);

  const disableUserVideo = useCallback(
    (userId: string) => {
      // Only send if we have op permission (host)
      if (permissions.includes("op")) {
        sendUserMessage("remote-video-off", userId);
      }
    },
    [permissions, sendUserMessage],
  );

  const makeHost = useCallback(
    (userId: string) => {
      if (permissions.includes("op") && clientRef.current) {
        // Find existing student hosts and demote them first
        const currentStudentHosts = participantsRef.current.filter(
          (p) =>
            p.permissions.includes("op") &&
            !["lecturer", "admin"].includes(p.username) &&
            p.id !== userId,
        );

        currentStudentHosts.forEach((host) => {
          clientRef.current?.userAction("unop", host.id);
          sendUserMessage("demote-host", host.id);
        });

        // Promote the new user
        clientRef.current.userAction("op", userId);
        sendUserMessage("promote-host", userId);
      }
    },
    [permissions, sendUserMessage],
  );

  const removeHost = useCallback(
    (userId: string) => {
      if (permissions.includes("op") && clientRef.current) {
        clientRef.current.userAction("unop", userId);
        sendUserMessage("demote-host", userId);
      }
    },
    [permissions, sendUserMessage],
  );

  const toggleAudio = useCallback(() => {
    const ls = localStreamRef.current;
    if (ls) {
      ls.getAudioTracks().forEach((track) => {
        track.enabled = !track.enabled;
      });
      setAudioMuted((prev) => {
        const next = !prev;
        sessionStorage.setItem("galene-audio-muted", String(next));
        return next;
      });
    }
  }, []);

  const toggleVideo = useCallback(() => {
    const ls = localStreamRef.current;
    if (ls) {
      ls.getVideoTracks().forEach((track) => {
        track.enabled = !track.enabled;
      });
      setVideoMuted((prev) => {
        const next = !prev;
        sessionStorage.setItem("galene-video-muted", String(next));
        return next;
      });
    }
  }, []);

  const shareScreen = useCallback(async () => {
    if (clientRef.current) {
      try {
        await clientRef.current.publishScreen();
      } catch (err) {
        if (err instanceof Error && err.name === "NotAllowedError") {
          console.warn("[useGalene] User cancelled screen share picker.");
        } else {
          console.warn("[useGalene] Screen share error:", err);
        }
      }
    }
  }, []);

  const stopScreenShare = useCallback(() => {
    if (clientRef.current) {
      clientRef.current.stopScreenShare();
    }
  }, []);

  const kickUser = useCallback((userId: string) => {
    if (clientRef.current) {
      clientRef.current.userAction("kick", userId);
    }
  }, []);

  return {
    connected,
    localStream,
    remoteStreams,
    error,
    connecting,
    chatMessages,
    permissions,
    participants,
    isScreenSharing,
    screenShareStream,
    connect,
    disconnect,
    sendChat,
    toggleAudio,
    toggleVideo,
    shareScreen,
    stopScreenShare,
    kickUser,
    audioMuted,
    videoMuted,
    // New capabilities
    muteUser,
    disableUserVideo,
    makeHost,
    removeHost,
    raiseHand,
    lowerHand,
    raisedHands,
    whiteboardEvents,
    whiteboardActive,
    sendUserMessage,
    ownId,
    inClassNotification,
    clearNotification,
  };
}

import { useEffect, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import { logout } from "@/lib/pocketbase";

interface UseSessionTimeoutOptions {
  timeoutMinutes?: number;
  warningMinutes?: number;
  enabled?: boolean;
}

export function useSessionTimeout({
  timeoutMinutes = 30,
  warningMinutes = 5,
  enabled = true,
}: UseSessionTimeoutOptions = {}) {
  const router = useRouter();
  const timeoutRef = useRef<NodeJS.Timeout | null>(null);
  const warningTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const [showWarning, setShowWarning] = useState(false);
  const [timeRemaining, setTimeRemaining] = useState(0);

  const resetTimeout = () => {
    // Clear existing timeouts
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    if (warningTimeoutRef.current) clearTimeout(warningTimeoutRef.current);
    setShowWarning(false);

    if (!enabled) return;

    const timeoutMs = timeoutMinutes * 60 * 1000;
    const warningMs = Math.max(0, timeoutMs - warningMinutes * 60 * 1000);

    // Set warning timeout
    if (warningMinutes > 0 && warningMinutes < timeoutMinutes) {
      warningTimeoutRef.current = setTimeout(() => {
        setShowWarning(true);
        setTimeRemaining(warningMinutes * 60);

        // Start countdown timer
        const countdownInterval = setInterval(() => {
          setTimeRemaining((prev) => {
            if (prev <= 1) {
              clearInterval(countdownInterval);
              return 0;
            }
            return prev - 1;
          });
        }, 1000);
      }, warningMs);
    }

    // Set logout timeout
    timeoutRef.current = setTimeout(() => {
      setShowWarning(false);
      logout();
      router.push("/login");
    }, timeoutMs);
  };

  const handleUserActivity = () => {
    if (showWarning) return; // Don't reset if warning is showing
    resetTimeout();
  };

  const extendSession = () => {
    setShowWarning(false);
    resetTimeout();
  };

  useEffect(() => {
    if (!enabled) return;

    // Initialize timeout on mount without triggering cascading render if already set
    resetTimeout();

    // Track user activity
    const events = [
      "mousedown",
      "mousemove",
      "keydown",
      "scroll",
      "touchstart",
      "click",
    ];

    const throttledActivity = () => {
      handleUserActivity();
    };

    events.forEach((event) => {
      document.addEventListener(event, throttledActivity, true);
    });

    return () => {
      events.forEach((event) => {
        document.removeEventListener(event, throttledActivity, true);
      });
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
      if (warningTimeoutRef.current) clearTimeout(warningTimeoutRef.current);
    };
  }, [enabled, handleUserActivity]); // Removed showWarning as it resets on every warning pop

  return {
    showWarning,
    timeRemaining,
    extendSession,
    forceLogout: () => {
      logout();
      router.push("/login");
    },
  };
}

/**
 * Galene WebRTC SFU Client
 *
 * Implements the Galene WebSocket signaling protocol for connecting to
 * Galene groups (rooms) and managing WebRTC media streams.
 *
 * Based on the official Galene protocol.js reference client:
 * https://github.com/jech/galene/blob/master/static/protocol.js
 */

const GALENE_URL =
  process.env.NEXT_PUBLIC_GALENE_URL || "http://localhost:8443";

export type GalenePermission = "op" | "present" | "observe";

export interface GaleneUser {
  id: string;
  username: string;
  permissions: GalenePermission[];
}

export interface GaleneStream {
  id: string;
  pc: RTCPeerConnection;
  stream: MediaStream;
  label?: string;
  userId?: string;
  username?: string;
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type GaleneEventCallback = (...args: any[]) => void;

/**
 * Generate a 32-hex-digit random ID (16 bytes), matching official Galene client.
 */
function newRandomId(): string {
  const a = new Uint8Array(16);
  crypto.getRandomValues(a);
  return Array.from(a)
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
}

export class GaleneClient {
  private ws: WebSocket | null = null;
  private group: string = "";
  private username: string = "";
  private password: string = "";
  /** The connection ID sent in the handshake */
  private connectionId: string = "";
  private localStream: MediaStream | null = null;
  private screenStream: MediaStream | null = null;
  /** The stream ID of the active screen share upstream */
  private _screenShareStreamId: string | null = null;

  private upStreams: Map<
    string,
    {
      pc: RTCPeerConnection;
      id: string;
      localDescriptionSent: boolean;
      localIceCandidates: RTCIceCandidate[];
    }
  > = new Map();

  private downStreams: Map<
    string,
    {
      pc: RTCPeerConnection;
      stream: MediaStream;
      id: string;
      label?: string;
      username?: string;
      remoteIceCandidates: RTCIceCandidate[];
    }
  > = new Map();

  private listeners: Map<string, GaleneEventCallback[]> = new Map();
  private _connected: boolean = false;
  private _permissions: GalenePermission[] = [];
  private rtcConfiguration: RTCConfiguration | null = null;

  get connected(): boolean {
    return this._connected;
  }

  get permissions(): GalenePermission[] {
    return this._permissions;
  }

  get screenShareStreamId(): string | null {
    return this._screenShareStreamId;
  }

  get id(): string {
    return this.connectionId;
  }

  private getWsUrl(): string {
    const base = GALENE_URL.replace(/^http/, "ws");
    return `${base}/ws`;
  }

  on(event: string, callback: GaleneEventCallback): void {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, []);
    }
    this.listeners.get(event)!.push(callback);
  }

  off(event: string, callback: GaleneEventCallback): void {
    const cbs = this.listeners.get(event);
    if (cbs) {
      this.listeners.set(
        event,
        cbs.filter((cb) => cb !== callback),
      );
    }
  }

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private emit(event: string, ...args: any[]): void {
    const cbs = this.listeners.get(event);
    if (cbs) {
      cbs.forEach((cb) => cb(...args));
    }
  }

  /**
   * Get the RTC configuration, using server-provided config if available.
   */
  private getRTCConfiguration(): RTCConfiguration {
    return (
      this.rtcConfiguration || {
        iceServers: [{ urls: "stun:stun.l.google.com:19302" }],
      }
    );
  }

  /**
   * Connect to a Galene group (room).
   */
  async connect(
    group: string,
    username: string,
    password: string,
  ): Promise<void> {
    this.group = group;
    this.username = username;
    this.password = password;
    this.connectionId = newRandomId();

    return new Promise((resolve, reject) => {
      try {
        const wsUrl = this.getWsUrl();
        this.ws = new WebSocket(wsUrl);

        this.ws.onopen = () => {
          // Send handshake with protocol version 2 and our connection ID
          this.send({
            type: "handshake",
            version: ["2"],
            id: this.connectionId,
          });
        };

        this.ws.onmessage = (event) => {
          try {
            const msg = JSON.parse(event.data);
            this.handleMessage(msg, resolve, reject);
          } catch (e) {
            console.error("[Galene] Failed to parse message:", e);
          }
        };

        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        this.ws.onerror = (error: any) => {
          const wsMsg =
            error?.message || "Check if Galene server is running at " + wsUrl;
          console.error("[Galene] WebSocket error:", error, wsMsg);
          this.emit("error", new Error(wsMsg));
          reject(new Error(wsMsg));
        };

        this.ws.onclose = (event) => {
          this._connected = false;
          this.emit("disconnected", event.code, event.reason);
          this.cleanup();
        };
      } catch (error) {
        reject(error);
      }
    });
  }

  /**
   * Handle incoming Galene protocol messages.
   */
  private handleMessage(
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    msg: any,
    connectResolve?: (value: void) => void,
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    connectReject?: (reason: any) => void,
  ): void {
    switch (msg.type) {
      case "handshake": {
        if (Array.isArray(msg.version) && msg.version.includes("2")) {
          // Version 2 confirmed, now join the group
          this.send({
            type: "join",
            kind: "join",
            group: this.group,
            username: this.username,
            password: this.password,
          });
        } else {
          const err = new Error(`Unknown protocol version: ${msg.version}`);
          this.emit("error", err);
          if (connectReject) connectReject(err);
        }
        break;
      }

      case "joined": {
        if (msg.kind === "join") {
          this._connected = true;
          this._permissions = msg.permissions || [];
          this.rtcConfiguration = msg.rtcConfiguration || null;
          this.emit("connected", msg.permissions);

          // Request to receive audio and video from all participants
          this.send({
            type: "request",
            request: { "": ["audio", "video"] },
          });

          if (connectResolve) connectResolve();
        } else if (msg.kind === "leave" || msg.kind === "fail") {
          this._connected = false;
          this._permissions = [];
          const err = new Error(msg.value || msg.error || "Join failed");
          this.emit("error", err);
          if (connectReject) connectReject(err);
        }
        break;
      }

      case "answer": {
        this.handleAnswer(msg);
        break;
      }

      case "offer": {
        this.handleOffer(msg);
        break;
      }

      case "renegotiate": {
        this.handleRenegotiate(msg);
        break;
      }

      case "ice": {
        this.handleIce(msg);
        break;
      }

      case "close": {
        this.handleStreamClose(msg);
        break;
      }

      case "abort": {
        const abortUp = this.upStreams.get(msg.id);
        if (abortUp) {
          abortUp.pc.close();
          this.upStreams.delete(msg.id);
        }
        if (!abortUp) {
          // Connection-level abort
          this._connected = false;
          const error = new Error(msg.value || "Connection aborted by server");
          this.emit("error", error);
          if (connectReject) connectReject(error);
        }
        break;
      }

      case "user": {
        this.emit("user", {
          id: msg.id,
          username: msg.username,
          permissions: msg.permissions,
          kind: msg.kind,
        });
        break;
      }

      case "chat":
      case "chathistory": {
        this.emit("chat", {
          id: msg.id || msg.source,
          username: msg.username,
          dest: msg.dest,
          value: msg.value,
          time: msg.time,
        });
        break;
      }

      case "usermessage": {
        this.emit("usermessage", msg);
        break;
      }

      case "ping": {
        this.send({ type: "pong" });
        break;
      }

      default:
        console.warn("[Galene] Unhandled message type:", msg.type, msg);
    }
  }

  /**
   * Publish local media to the group.
   * Matches the official newUpStream() + negotiate() flow.
   */
  async publishStream(stream: MediaStream, label?: string): Promise<string> {
    this.localStream = stream;
    const id = newRandomId();

    const pc = new RTCPeerConnection(this.getRTCConfiguration());

    const upEntry = {
      pc,
      id,
      localDescriptionSent: false,
      localIceCandidates: [] as RTCIceCandidate[],
    };
    this.upStreams.set(id, upEntry);

    // Buffer ICE candidates until local description is sent
    pc.onicecandidate = (event) => {
      if (!event.candidate) return;
      if (upEntry.localDescriptionSent) {
        this.send({
          type: "ice",
          id: id,
          candidate: event.candidate,
        });
      } else {
        upEntry.localIceCandidates.push(event.candidate);
      }
    };

    // Add all tracks from the local stream
    stream.getTracks().forEach((track) => {
      pc.addTrack(track, stream);
    });

    // Create and send offer
    const offer = await pc.createOffer();
    await pc.setLocalDescription(offer);

    this.send({
      type: "offer",
      source: this.connectionId,
      username: this.username,
      kind: "",
      id: id,
      label: label || "video",
      sdp: pc.localDescription!.sdp,
    });

    // Mark local description as sent and flush buffered ICE candidates
    upEntry.localDescriptionSent = true;
    for (const candidate of upEntry.localIceCandidates) {
      this.send({
        type: "ice",
        id: id,
        candidate: candidate,
      });
    }
    upEntry.localIceCandidates = [];

    this.emit("localStreamPublished", { id, stream });
    return id;
  }

  /**
   * Handle answer from Galene for our published (upstream) stream.
   */
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private async handleAnswer(msg: any): Promise<void> {
    const up = this.upStreams.get(msg.id);
    if (!up) {
      console.warn("[Galene] Got answer for unknown upstream:", msg.id);
      return;
    }
    try {
      await up.pc.setRemoteDescription(
        new RTCSessionDescription({ type: "answer", sdp: msg.sdp }),
      );
    } catch (e) {
      console.error("[Galene] Failed to set remote description:", e);
      up.pc.close();
      this.upStreams.delete(msg.id);
    }
  }

  /**
   * Handle incoming stream offer from Galene (downstream / remote participant).
   * Matches the official gotOffer() flow.
   */
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private async handleOffer(msg: any): Promise<void> {
    const id = msg.id;

    // If we already have this upstream, it's a conflict
    if (this.upStreams.has(id)) {
      console.error("[Galene] Duplicate connection id in offer");
      this.send({ type: "abort", id: id });
      return;
    }

    // Handle stream replacement
    if (msg.replace) {
      const old = this.downStreams.get(msg.replace);
      if (old) {
        old.pc.close();
        this.downStreams.delete(msg.replace);
        this.emit("remoteStreamRemoved", { id: msg.replace });
      }
    }

    const pc = new RTCPeerConnection(this.getRTCConfiguration());
    const stream = new MediaStream();

    const downEntry = {
      pc,
      stream,
      id,
      label: msg.label,
      username: msg.username,
      remoteIceCandidates: [] as RTCIceCandidate[],
    };
    this.downStreams.set(id, downEntry);

    pc.onicecandidate = (event) => {
      if (event.candidate) {
        this.send({
          type: "ice",
          id: id,
          candidate: event.candidate,
        });
      }
    };

    pc.oniceconnectionstatechange = () => {
      if (pc.iceConnectionState === "failed") {
        // Request renegotiation
        this.send({ type: "renegotiate", id: id });
      }
    };

    pc.ontrack = (event) => {
      if (event.streams.length > 0) {
        downEntry.stream = event.streams[0];
      } else {
        event.track && downEntry.stream.addTrack(event.track);
      }
      this.emit("remoteStream", {
        id,
        stream: downEntry.stream,
        label: downEntry.label,
        username: msg.username || downEntry.username,
      });
    };

    try {
      await pc.setRemoteDescription(
        new RTCSessionDescription({ type: "offer", sdp: msg.sdp }),
      );

      // Flush any buffered remote ICE candidates
      for (const candidate of downEntry.remoteIceCandidates) {
        await pc.addIceCandidate(candidate).catch(console.warn);
      }
      downEntry.remoteIceCandidates = [];

      const answer = await pc.createAnswer();
      await pc.setLocalDescription(answer);

      this.send({
        type: "answer",
        id: id,
        sdp: pc.localDescription!.sdp,
      });
    } catch (e) {
      console.error("[Galene] Failed to handle downstream offer:", e);
      pc.close();
      this.downStreams.delete(id);
    }
  }

  /**
   * Handle renegotiation request from the server for an upstream.
   */
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private async handleRenegotiate(msg: any): Promise<void> {
    const up = this.upStreams.get(msg.id);
    if (!up) {
      console.warn("[Galene] Renegotiate for unknown upstream:", msg.id);
      return;
    }

    try {
      const offer = await up.pc.createOffer({ iceRestart: true });
      await up.pc.setLocalDescription(offer);

      this.send({
        type: "offer",
        source: this.connectionId,
        username: this.username,
        kind: "renegotiate",
        id: msg.id,
        sdp: up.pc.localDescription!.sdp,
      });

      up.localDescriptionSent = true;
      for (const candidate of up.localIceCandidates) {
        this.send({
          type: "ice",
          id: msg.id,
          candidate: candidate,
        });
      }
      up.localIceCandidates = [];
    } catch (e) {
      console.error("[Galene] Renegotiation failed:", e);
    }
  }

  /**
   * Handle ICE candidates from Galene.
   */
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private async handleIce(msg: any): Promise<void> {
    const up = this.upStreams.get(msg.id);
    const down = this.downStreams.get(msg.id);

    if (up && msg.candidate) {
      try {
        if (up.pc.remoteDescription) {
          await up.pc.addIceCandidate(new RTCIceCandidate(msg.candidate));
        }
        // No buffering needed for upstream remote ICE — we already
        // have remote description set from the answer.
      } catch (e) {
        console.warn("[Galene] Failed to add ICE candidate:", e);
      }
    } else if (down && msg.candidate) {
      try {
        if (down.pc.remoteDescription) {
          await down.pc.addIceCandidate(new RTCIceCandidate(msg.candidate));
        } else {
          down.remoteIceCandidates.push(new RTCIceCandidate(msg.candidate));
        }
      } catch (e) {
        console.warn("[Galene] Failed to add ICE candidate:", e);
      }
    }
  }

  /**
   * Handle remote stream closing.
   */
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private handleStreamClose(msg: any): void {
    const down = this.downStreams.get(msg.id);
    if (down) {
      down.pc.close();
      this.downStreams.delete(msg.id);
      this.emit("remoteStreamRemoved", { id: msg.id });
    }
  }

  /**
   * Publish screen share to the group.
   * Uses getDisplayMedia to capture the screen.
   */
  async publishScreen(): Promise<string> {
    const stream = await navigator.mediaDevices.getDisplayMedia({
      video: true,
      audio: false,
    });
    this.screenStream = stream;

    const id = newRandomId();
    const pc = new RTCPeerConnection(this.getRTCConfiguration());

    const upEntry = {
      pc,
      id,
      localDescriptionSent: false,
      localIceCandidates: [] as RTCIceCandidate[],
    };
    this.upStreams.set(id, upEntry);
    this._screenShareStreamId = id;

    pc.onicecandidate = (event) => {
      if (!event.candidate) return;
      if (upEntry.localDescriptionSent) {
        this.send({ type: "ice", id, candidate: event.candidate });
      } else {
        upEntry.localIceCandidates.push(event.candidate);
      }
    };

    stream.getTracks().forEach((track) => {
      pc.addTrack(track, stream);
      // Auto-stop when user clicks browser's "Stop sharing" button
      track.onended = () => {
        this.stopScreenShare();
      };
    });

    const offer = await pc.createOffer();
    await pc.setLocalDescription(offer);

    this.send({
      type: "offer",
      source: this.connectionId,
      username: this.username,
      kind: "",
      id,
      label: "screenshare",
      sdp: pc.localDescription!.sdp,
    });

    upEntry.localDescriptionSent = true;
    for (const candidate of upEntry.localIceCandidates) {
      this.send({ type: "ice", id, candidate });
    }
    upEntry.localIceCandidates = [];

    this.emit("screenShareStarted", { id, stream });
    return id;
  }

  /**
   * Stop screen sharing.
   */
  stopScreenShare(): void {
    if (this._screenShareStreamId) {
      const up = this.upStreams.get(this._screenShareStreamId);
      if (up) {
        try {
          this.send({ type: "close", id: this._screenShareStreamId });
        } catch {
          // ignore
        }
        up.pc.close();
        this.upStreams.delete(this._screenShareStreamId);
      }
    }
    if (this.screenStream) {
      this.screenStream.getTracks().forEach((t) => t.stop());
      this.screenStream = null;
    }
    this._screenShareStreamId = null;
    this.emit("screenShareStopped");
  }

  /**
   * Perform a user action (op, unop, kick, present, unpresent).
   * Only works if the user has "op" permission.
   */
  userAction(kind: string, dest: string, value?: string): void {
    this.send({
      type: "useraction",
      source: this.connectionId,
      dest,
      username: this.username,
      kind,
      value: value || "",
    });
  }

  /**
   * Send a generic user message (for whiteboard, remote mute, hand raise, etc.).
   */
  sendUserMessage(kind: string, dest: string = "", value: string = ""): void {
    this.send({
      type: "usermessage",
      source: this.connectionId,
      dest,
      username: this.username,
      kind,
      value,
    });
  }

  /**
   * Send a chat message to the group.
   */
  sendChat(message: string, dest?: string): void {
    this.send({
      type: "chat",
      source: this.connectionId,
      username: this.username,
      dest: dest || "",
      value: message,
    });
  }

  /**
   * Disconnect from the Galene server.
   */
  disconnect(): void {
    // Close all upstream connections
    this.upStreams.forEach(({ pc, id }) => {
      try {
        this.send({ type: "close", id });
      } catch {
        // ignore
      }
      pc.close();
    });
    this.upStreams.clear();

    // Close all downstream connections
    this.downStreams.forEach(({ pc }) => pc.close());
    this.downStreams.clear();

    // Stop local stream tracks
    if (this.localStream) {
      this.localStream.getTracks().forEach((t) => t.stop());
      this.localStream = null;
    }

    // Close WebSocket
    if (this.ws) {
      this.ws.close();
      this.ws = null;
    }

    this._connected = false;
    this.emit("disconnected", 1000, "User disconnected");
  }

  /**
   * Send a message over WebSocket.
   */
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private send(msg: any): void {
    if (this.ws && this.ws.readyState === WebSocket.OPEN) {
      this.ws.send(JSON.stringify(msg));
    }
  }

  /**
   * Cleanup resources on disconnect.
   */
  private cleanup(): void {
    this.upStreams.forEach(({ pc }) => pc.close());
    this.upStreams.clear();
    this.downStreams.forEach(({ pc }) => pc.close());
    this.downStreams.clear();

    if (this.localStream) {
      this.localStream.getTracks().forEach((t) => t.stop());
      this.localStream = null;
    }
  }
}

/**
 * Get the public Galene URL for a given group.
 */
export function getGaleneGroupUrl(groupName: string): string {
  return `${GALENE_URL}/group/${groupName}/`;
}

/**
 * Create a new GaleneClient instance.
 */
export function createGaleneClient(): GaleneClient {
  return new GaleneClient();
}
